var e=JSON.parse(`[{"id":"aut.administrativo_tj.acumulacoes.0001","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 171 da Lei nº 10.261/1968, é vedada a acumulação remunerada, exceto, entre outras hipóteses,","alternativas":{"A":"a de dois cargos de professor.","B":"a de dois cargos técnicos ou científicos.","C":"a de um cargo de escrevente e outro de oficial administrativo.","D":"a de um cargo em comissão e outro efetivo, ambos remunerados.","E":"a de dois cargos de juiz."},"gabarito":"A","explicacao":"O art. 171 admite, como exceção, a acumulação de um juiz e um cargo de professor (I); de dois cargos de professor (II); de um cargo de professor e outro técnico ou científico (III); e de dois cargos privativos de médico (IV). A Constituição Federal (art. 37, XVI) disciplina hoje o tema e deve ser observada em conjunto.","explicacoes":{"A":"Correta: art. 171, II.","B":"Dois cargos técnicos não estão entre as exceções; o técnico só se acumula com o de professor (inciso III).","C":"Dois cargos administrativos comuns não podem ser acumulados.","D":"O efetivo nomeado em comissão perde o vencimento do efetivo, salvo opção (art. 172).","E":"Não há exceção para dois cargos de juiz."},"fonte":"Lei 10.261/1968, art. 171, II; CF, art. 37, XVI","mastigado":"A resposta é a letra A. A regra é não acumular cargos pagos. As exceções da lei são poucas e quase todas envolvem o magistério: juiz com professor, dois de professor, professor com técnico ou científico, e dois de médico.","teSitua":{"termos":[{"termo":"acumulação remunerada","significado":"exercício de dois ou mais cargos públicos ao mesmo tempo, recebendo por todos."},{"termo":"técnicos ou científicos","significado":"cargos que exigem conhecimento especializado de nível técnico ou superior."}],"exemplo":"Roberta dá aulas numa escola estadual de manhã e passou num concurso para professora em outra escola estadual à noite. Como se trata de dois cargos de professor, a acumulação é permitida, desde que os horários sejam compatíveis."}},{"id":"aut.administrativo_tj.acumulacoes.0002","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto dos Funcionários Públicos Civis de SP, nas hipóteses em que se admite a acumulação remunerada, ela somente é permitida quando haja correlação de matérias e compatibilidade de horários.","gabarito":"C","explicacao":"É o que exige o art. 171, § 1º, para qualquer das hipóteses de acumulação permitida.","fonte":"Lei 10.261/1968, art. 171, § 1º","mastigado":"Certo. Mesmo nos casos em que a lei permite acumular, o Estatuto exige duas coisas: que os assuntos dos cargos tenham relação entre si e que os horários não se choquem.","teSitua":{"termos":[{"termo":"correlação de matérias","significado":"relação entre os assuntos ou conteúdos dos dois cargos."},{"termo":"compatibilidade de horários","significado":"possibilidade real de cumprir as duas jornadas sem que uma se sobreponha à outra."}],"exemplo":"Augusto é engenheiro do Estado durante o dia e quer lecionar matemática à noite numa escola estadual. A acumulação é possível porque os horários não se chocam e há relação entre os conteúdos dos cargos."}},{"id":"aut.administrativo_tj.acumulacoes.0003","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Estatuto paulista, a proibição de acumular","alternativas":{"A":"estende-se a cargos, funções ou empregos em autarquias, empresas públicas e sociedades de economia mista.","B":"alcança apenas cargos da Administração direta.","C":"não se aplica às sociedades de economia mista.","D":"alcança apenas cargos do mesmo Poder.","E":"não se aplica a empregos regidos pela legislação trabalhista."},"gabarito":"A","explicacao":"O art. 171, § 2º, estende a proibição de acumular a cargos, funções ou empregos em autarquias, empresas públicas e sociedades de economia mista.","explicacoes":{"A":"Correta: art. 171, § 2º.","B":"A proibição vai além da Administração direta.","C":"As sociedades de economia mista estão expressamente incluídas.","D":"A lei não restringe a proibição ao mesmo Poder.","E":"Empregos nessas entidades também estão alcançados."},"fonte":"Lei 10.261/1968, art. 171, § 2º","mastigado":"A resposta é a letra A. Não adianta trocar o cargo por um emprego numa empresa estatal para fugir da regra. A proibição vale também para autarquias, empresas públicas e sociedades de economia mista.","teSitua":{"termos":[{"termo":"autarquias","significado":"entidades públicas criadas por lei para atividades típicas do Estado, com autonomia."},{"termo":"empresas públicas","significado":"empresas criadas pelo Estado, com capital totalmente público."},{"termo":"sociedades de economia mista","significado":"empresas com capital público e privado, controladas pelo Estado."}],"exemplo":"Gilberto é escrevente do TJSP e foi aprovado para um emprego de analista na Sabesp, sociedade de economia mista. Ele não pode acumular os dois, porque a proibição alcança também os empregos nessas empresas."}},{"id":"aut.administrativo_tj.acumulacoes.0004","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos da Lei nº 10.261/1968, a proibição de acumular proventos não se aplica aos aposentados, quanto ao exercício de mandato eletivo, cargo em comissão ou contrato para prestação de serviços técnicos ou especializados.","gabarito":"C","explicacao":"É a ressalva do art. 171, § 3º. O aposentado pode, nessas hipóteses, receber os proventos da aposentadoria e a remuneração do mandato, do cargo em comissão ou do contrato técnico.","fonte":"Lei 10.261/1968, art. 171, § 3º","mastigado":"Certo. O servidor aposentado pode continuar recebendo a aposentadoria e, ao mesmo tempo, ganhar por um mandato eletivo, por um cargo de confiança ou por um contrato de serviço técnico especializado.","teSitua":{"termos":[{"termo":"proventos","significado":"valor que o aposentado recebe mensalmente."},{"termo":"mandato eletivo","significado":"cargo político obtido por eleição, como o de vereador."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"Dona Neusa se aposentou como servidora estadual e foi eleita vereadora. Ela pode receber a aposentadoria e o subsídio de vereadora ao mesmo tempo, porque a lei libera os aposentados nesse caso."}},{"id":"aut.administrativo_tj.acumulacoes.0005","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":2,"enunciado":"Um funcionário ocupante de cargo efetivo foi nomeado para cargo em comissão. Segundo a Lei nº 10.261/1968, durante o exercício do cargo em comissão, ele","alternativas":{"A":"perderá o vencimento ou remuneração do cargo efetivo, salvo se optar por ele.","B":"acumulará as remunerações dos dois cargos.","C":"será exonerado do cargo efetivo.","D":"receberá metade da remuneração de cada cargo.","E":"não poderá optar pela remuneração do cargo efetivo."},"gabarito":"A","explicacao":"O art. 172 permite que o ocupante de cargo efetivo, ou em disponibilidade, seja nomeado para cargo em comissão, perdendo, durante o exercício desse cargo, o vencimento ou remuneração do efetivo ou o provento, salvo se optar por ele.","explicacoes":{"A":"Correta: art. 172.","B":"Não há soma das duas remunerações.","C":"Ele mantém o vínculo com o cargo efetivo.","D":"Não existe pagamento de metade de cada cargo.","E":"A lei permite a opção pela remuneração do cargo efetivo."},"fonte":"Lei 10.261/1968, art. 172","mastigado":"A resposta é a letra A. O servidor efetivo pode ir para um cargo de confiança sem perder o cargo dele. Mas não recebe pelos dois: fica com o salário do cargo em comissão, a não ser que prefira manter o do cargo efetivo.","teSitua":{"termos":[{"termo":"cargo efetivo","significado":"cargo permanente, ocupado por concursado."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."},{"termo":"optar","significado":"escolher uma entre duas possibilidades."}],"exemplo":"Marcela, escrevente efetiva, foi nomeada assessora em comissão. Ela recebe o valor do cargo em comissão; se o efetivo pagasse mais, poderia optar por continuar recebendo o do efetivo. Nunca recebe os dois."}},{"id":"aut.administrativo_tj.acumulacoes.0006","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"Conforme o Estatuto, o funcionário em disponibilidade não pode ser nomeado para cargo em comissão.","gabarito":"E","explicacao":"O art. 172 admite expressamente que o funcionário ocupante de cargo efetivo, ou em disponibilidade, seja nomeado para cargo em comissão, perdendo o provento durante o exercício, salvo se optar por ele.","fonte":"Lei 10.261/1968, art. 172","mastigado":"Errado. A lei permite que o servidor em disponibilidade seja nomeado para cargo de confiança. Enquanto estiver nele, deixa de receber o valor da disponibilidade, a menos que escolha mantê-lo.","teSitua":{"termos":[{"termo":"disponibilidade","significado":"situação do servidor que fica sem exercer cargo, recebendo proventos, aguardando aproveitamento."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"O cargo de Sílvio foi extinto e ele ficou em disponibilidade. Um diretor o convidou para um cargo em comissão. Sílvio pode aceitar; enquanto estiver no cargo, recebe a remuneração dele ou, se preferir, mantém o provento da disponibilidade."}},{"id":"aut.administrativo_tj.acumulacoes.0007","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":3,"enunciado":"Verificado, mediante processo administrativo, que o funcionário está acumulando fora das condições legais, a Lei nº 10.261/1968 prevê que ele","alternativas":{"A":"será demitido de todos os cargos e funções e obrigado a restituir o que indevidamente houver recebido.","B":"será apenas advertido verbalmente.","C":"perderá somente o cargo mais recente, sem restituição.","D":"será suspenso por 90 dias em ambos os cargos.","E":"poderá escolher um dos cargos, sem qualquer consequência."},"gabarito":"A","explicacao":"A consequência prevista no art. 174 é a demissão de todos os cargos e funções, com restituição do que recebeu indevidamente. Provada a boa-fé, o funcionário é mantido no cargo que exerce há mais tempo (§ 1º).","explicacoes":{"A":"Correta: art. 174, caput.","B":"A lei não prevê simples advertência.","C":"A regra é a demissão de todos; com boa-fé, mantém-se o cargo mais antigo, não o mais recente.","D":"A pena prevista é demissão, não suspensão.","E":"A escolha livre não é prevista; há demissão, com a exceção da boa-fé."},"fonte":"Lei 10.261/1968, art. 174, caput","mastigado":"A resposta é a letra A. Quem acumula cargos de forma proibida perde todos eles e devolve o que recebeu indevidamente. Só se provar boa-fé fica com o cargo que tem há mais tempo.","teSitua":{"termos":[{"termo":"processo administrativo","significado":"procedimento formal para apurar falta do servidor, com direito de defesa."},{"termo":"restituir","significado":"devolver aos cofres públicos o que recebeu."},{"termo":"indevidamente","significado":"sem ter direito legal a receber."}],"exemplo":"Descobriu-se que Fausto ocupava dois cargos administrativos estaduais ao mesmo tempo, o que é proibido. Após processo administrativo em que não provou boa-fé, ele foi demitido dos dois e terá de devolver o que recebeu indevidamente."}},{"id":"aut.administrativo_tj.acumulacoes.0008","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"Provada a boa-fé do funcionário que acumulava ilegalmente, segundo o Estatuto paulista, ele será mantido no cargo ou função que exercer há mais tempo.","gabarito":"C","explicacao":"É a regra do art. 174, § 1º. Sem boa-fé, além de demitido de todos os cargos, fica inabilitado por 5 anos (§ 2º).","fonte":"Lei 10.261/1968, art. 174, § 1º","mastigado":"Certo. Se o servidor mostrar que não sabia que a acumulação era proibida, ele não perde tudo: fica com o cargo mais antigo e sai do mais novo.","teSitua":{"termos":[{"termo":"boa-fé","significado":"situação de quem age honestamente, sem saber que está errado."},{"termo":"acumulava ilegalmente","significado":"ocupava ao mesmo tempo cargos que a lei não permite acumular."}],"exemplo":"Janete entrou num segundo cargo acreditando, por informação errada do setor de pessoal, que podia acumular. No processo, provou a boa-fé. Ela foi mantida no cargo que exercia há mais tempo e deixou apenas o mais recente."}},{"id":"aut.administrativo_tj.acumulacoes.0009","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":3,"enunciado":"Não provada a boa-fé, o funcionário demitido por acumulação ilegal, nos termos da Lei nº 10.261/1968, ficará ainda inabilitado para o exercício de função ou cargo público pelo prazo de","alternativas":{"A":"5 anos, inclusive em entidades que exerçam função delegada do poder público ou sejam por este mantidas ou administradas.","B":"2 anos, apenas na Administração direta.","C":"10 anos, em qualquer esfera da Federação.","D":"5 anos, apenas no Poder em que ocorreu a acumulação.","E":"8 anos, exceto em empresas públicas."},"gabarito":"A","explicacao":"O art. 174, § 2º, prevê inabilitação por 5 anos para o exercício de função ou cargo público, inclusive em entidades que exerçam função delegada do poder público ou sejam por este mantidas ou administradas.","explicacoes":{"A":"Correta: art. 174, § 2º.","B":"O prazo é de 5 anos e alcança também entidades com função delegada.","C":"O prazo é de 5 anos, não de 10.","D":"A lei não limita ao Poder em que houve a acumulação.","E":"O prazo é de 5 anos."},"fonte":"Lei 10.261/1968, art. 174, § 2º","mastigado":"A resposta é a letra A. Sem boa-fé, a pessoa perde os cargos e fica cinco anos sem poder voltar ao serviço público, inclusive em entidades que exerçam função delegada pelo poder público ou que ele mantém.","teSitua":{"termos":[{"termo":"boa-fé","significado":"situação de quem age honestamente, sem saber que está errado."},{"termo":"inabilitado","significado":"proibido, por certo tempo, de ocupar cargo ou função."},{"termo":"função delegada","significado":"atividade pública que o Estado transfere para outra entidade executar."}],"exemplo":"Otaviano escondeu de propósito que tinha dois cargos. Demitido de ambos, ele também não poderá, pelos cinco anos seguintes, assumir cargo público, nem mesmo em entidades mantidas pelo Estado."}},{"id":"aut.administrativo_tj.acumulacoes.0010","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":2,"enunciado":"Sobre a denúncia de acumulação ilegal de cargos, o Estatuto dos Funcionários Públicos Civis de SP estabelece que","alternativas":{"A":"qualquer cidadão poderá denunciar a existência de acumulação ilegal.","B":"apenas o chefe imediato pode denunciar.","C":"somente o Ministério Público tem legitimidade para denunciar.","D":"a denúncia deve ser feita exclusivamente pelo próprio funcionário.","E":"a denúncia anônima é obrigatória."},"gabarito":"A","explicacao":"O parágrafo único do art. 175 diz que qualquer cidadão poderá denunciar a existência de acumulação ilegal. O caput obriga autoridades e chefes que souberem da acumulação a comunicar o órgão competente.","explicacoes":{"A":"Correta: art. 175, parágrafo único.","B":"Qualquer cidadão pode denunciar.","C":"Não há exclusividade do Ministério Público.","D":"A lei não impõe isso ao próprio funcionário.","E":"A lei não fala em denúncia anônima obrigatória."},"fonte":"Lei 10.261/1968, art. 175, parágrafo único","mastigado":"A resposta é a letra A. Qualquer pessoa pode avisar que um servidor está acumulando cargos de forma ilegal. Além disso, os chefes que souberem disso são obrigados a comunicar o órgão competente.","teSitua":{"termos":[{"termo":"acumulação ilegal","significado":"exercício simultâneo de cargos que a lei proíbe acumular."},{"termo":"Ministério Público","significado":"instituição que fiscaliza o cumprimento da lei e defende o interesse público."}],"exemplo":"A vizinha Lurdes percebeu que um conhecido trabalhava de manhã num cargo estadual e de tarde em outro, sem relação com magistério. Ela denunciou o caso ao órgão de pessoal, como qualquer cidadão pode fazer."}},{"id":"aut.administrativo_tj.acumulacoes.0011","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a Lei nº 10.261/1968, as autoridades civis e os chefes de serviço que tiverem conhecimento de que algum subordinado está no exercício de acumulação proibida farão a devida comunicação ao órgão competente.","gabarito":"C","explicacao":"O art. 175, caput, impõe esse dever às autoridades civis, aos chefes de serviço, aos diretores das entidades referidas no § 2º do art. 174 e aos fiscais ou representantes do poder público junto a elas, para os fins do art. 174.","fonte":"Lei 10.261/1968, art. 175, caput","mastigado":"Certo. O chefe que descobre que um subordinado está acumulando cargos de forma proibida não pode ficar calado: deve comunicar ao órgão competente, para que se abra o processo.","teSitua":{"termos":[{"termo":"autoridades civis","significado":"agentes públicos com poder de decisão na Administração, fora da área militar."},{"termo":"acumulação proibida","significado":"exercício simultâneo de cargos que a lei não permite."}],"exemplo":"A chefe de seção Irene descobriu que o servidor Márcio tinha outro cargo estadual incompatível. Ela comunicou o fato ao órgão de pessoal, que abriu processo administrativo para apurar a acumulação."}},{"id":"aut.administrativo_tj.acumulacoes.0012","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":2,"enunciado":"Um juiz de direito pretende lecionar em escola pública estadual, em horário compatível. Nos termos do art. 171 da Lei nº 10.261/1968, essa acumulação","alternativas":{"A":"é permitida, por se tratar de um cargo de juiz e um de professor.","B":"é vedada, pois juízes não podem acumular nenhum cargo.","C":"só é permitida se o cargo de professor for em comissão.","D":"depende de autorização do Governador.","E":"é permitida apenas se o juiz renunciar à remuneração da magistratura."},"gabarito":"A","explicacao":"O art. 171, I, admite a acumulação de um cargo de juiz e um cargo de professor, observadas a correlação de matérias e a compatibilidade de horários (§ 1º). A Constituição também permite ao juiz exercer uma função de magistério.","explicacoes":{"A":"Correta: art. 171, I.","B":"A lei abre exceção expressa para o magistério.","C":"Não há exigência de que o cargo de professor seja em comissão.","D":"Não há exigência de autorização do Governador.","E":"Não há renúncia de remuneração; trata-se de acumulação remunerada permitida."},"fonte":"Lei 10.261/1968, art. 171, I, e § 1º","mastigado":"A resposta é a letra A. O juiz pode dar aula. É uma das exceções da lei: um cargo de juiz mais um de professor, desde que os horários caibam e haja relação entre as matérias.","teSitua":{"termos":[{"termo":"juiz de direito","significado":"magistrado que julga processos na primeira instância da Justiça estadual."},{"termo":"horário compatível","significado":"jornada que não se sobrepõe à do outro cargo."}],"exemplo":"O juiz Alberto julga processos no fórum durante o dia e, à noite, leciona direito constitucional numa faculdade estadual. A acumulação é permitida porque une um cargo de juiz e um de professor, com horários compatíveis."}},{"id":"aut.administrativo_tj.acumulacoes.0013","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Estatuto paulista, é vedada qualquer acumulação de dois cargos privativos de médico, ainda que haja compatibilidade de horários.","gabarito":"E","explicacao":"O art. 171, IV, admite a acumulação de dois cargos privativos de médico, desde que haja correlação de matérias e compatibilidade de horários (§ 1º). A Constituição (art. 37, XVI, c) amplia hoje a hipótese a dois cargos ou empregos privativos de profissionais de saúde com profissões regulamentadas.","fonte":"Lei 10.261/1968, art. 171, IV; CF, art. 37, XVI, c","mastigado":"Errado. A lei permite que um médico ocupe dois cargos de médico no serviço público, desde que os horários sejam compatíveis. É uma das poucas exceções à proibição de acumular.","teSitua":{"termos":[{"termo":"privativos de médico","significado":"cargos que só podem ser exercidos por quem é médico."},{"termo":"compatibilidade de horários","significado":"possibilidade de cumprir as duas jornadas sem sobreposição."}],"exemplo":"A doutora Paula trabalha como médica num hospital estadual pela manhã e foi aprovada para outro cargo de médica numa unidade estadual à tarde. Como os horários são compatíveis, ela pode acumular."}},{"id":"aut.administrativo_tj.acumulacoes.0014","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 173 da Lei nº 10.261/1968, não se compreende na proibição de acumular, desde que tenha correspondência com a função principal, a percepção","alternativas":{"A":"das vantagens pecuniárias enumeradas no art. 124, como gratificações, diárias e ajudas de custo.","B":"de dois vencimentos de cargos efetivos administrativos.","C":"de remuneração de emprego em sociedade de economia mista.","D":"de vencimento de cargo efetivo e de cargo em comissão, cumulativamente.","E":"de qualquer valor pago por entidade privada."},"gabarito":"A","explicacao":"O art. 173 ressalva da proibição de acumular a percepção das vantagens do art. 124 (adicionais por tempo de serviço, gratificações, diárias, ajudas de custo, entre outras), desde que tenham correspondência com a função principal.","explicacoes":{"A":"Correta: art. 173, combinado com o art. 124.","B":"Dois cargos administrativos não podem ser acumulados.","C":"A proibição se estende às sociedades de economia mista (art. 171, § 2º).","D":"Efetivo nomeado em comissão perde o vencimento do efetivo, salvo opção (art. 172).","E":"O art. 173 trata das vantagens do art. 124, não de valores de entidades privadas."},"fonte":"Lei 10.261/1968, art. 173; art. 124","mastigado":"A resposta é a letra A. Receber gratificação, diária ou ajuda de custo ligada ao próprio cargo não é acumular cargos. São vantagens que acompanham a função principal, e a lei as libera.","teSitua":{"termos":[{"termo":"vantagens pecuniárias","significado":"valores em dinheiro pagos além do vencimento, como gratificações."},{"termo":"diárias","significado":"valor pago para cobrir despesas quando o servidor viaja a serviço."},{"termo":"ajudas de custo","significado":"valor pago para cobrir despesas de mudança por interesse do serviço."},{"termo":"função principal","significado":"atividade do cargo que o servidor efetivamente ocupa."}],"exemplo":"O escrevente Danilo viajou a serviço para uma audiência em outra comarca e recebeu diárias. Isso não é acumulação proibida, porque a diária está ligada à função principal dele."}},{"id":"aut.administrativo_tj.acumulacoes.0015","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":3,"enunciado":"Uma servidora estadual, ocupante de cargo administrativo, foi aprovada para emprego de nível médio em empresa pública estadual, com horários compatíveis. Segundo a Lei nº 10.261/1968, a acumulação","alternativas":{"A":"é vedada, pois a proibição se estende a empregos em empresas públicas e não se trata de hipótese excepcionada.","B":"é permitida, porque emprego público não se confunde com cargo.","C":"é permitida, por haver compatibilidade de horários.","D":"depende apenas de autorização do chefe imediato.","E":"é permitida, desde que ela abra mão das férias de um dos vínculos."},"gabarito":"A","explicacao":"A proibição de acumular se estende a cargos, funções ou empregos em empresas públicas (art. 171, § 2º), e o caso não se enquadra em nenhuma das exceções do art. 171. A compatibilidade de horários só importa nas hipóteses permitidas (§ 1º).","explicacoes":{"A":"Correta: art. 171, caput e § 2º.","B":"O § 2º alcança expressamente os empregos.","C":"Horário compatível não basta; a hipótese precisa ser uma das exceções.","D":"Não há autorização do chefe que torne lícita a acumulação.","E":"Não há essa condição na lei."},"fonte":"Lei 10.261/1968, art. 171, caput e § 2º","mastigado":"A resposta é a letra A. Ter horários compatíveis não é suficiente. Primeiro a acumulação precisa estar entre as exceções da lei, e cargo administrativo com emprego de nível médio não está. Além disso, a proibição vale para empregos em empresas públicas.","teSitua":{"termos":[{"termo":"empresa pública","significado":"empresa criada pelo Estado, com capital totalmente público."},{"termo":"emprego","significado":"vínculo de trabalho regido pela legislação trabalhista em entidades estatais."},{"termo":"compatíveis","significado":"que podem ser cumpridos ao mesmo tempo, sem conflito."}],"exemplo":"Kátia é oficial administrativa estadual e passou num processo seletivo para assistente numa empresa pública do Estado. Mesmo trabalhando em horários diferentes, não pode manter os dois vínculos, porque a situação não está entre as exceções da lei."}},{"id":"aut.administrativo_tj.acumulacoes.0016","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos do Estatuto, a apuração de acumulação ilegal deve ser feita mediante processo administrativo, e a consequência, sem boa-fé, é a demissão de todos os cargos, com obrigação de restituir o que foi indevidamente recebido.","gabarito":"C","explicacao":"O art. 174 exige processo administrativo e prevê demissão de todos os cargos e funções e restituição do indevido. Sem boa-fé, há ainda inabilitação por 5 anos (§ 2º).","fonte":"Lei 10.261/1968, art. 174, caput e § 2º","mastigado":"Certo. A acumulação proibida precisa ser comprovada num processo, com direito de defesa. Comprovada e sem boa-fé, o servidor perde todos os cargos e devolve o dinheiro recebido indevidamente.","teSitua":{"termos":[{"termo":"processo administrativo","significado":"procedimento formal para apurar falta do servidor, com direito de defesa."},{"termo":"boa-fé","significado":"situação de quem age honestamente, sem saber que está errado."}],"exemplo":"Após denúncia, a Administração abriu processo administrativo contra Ernesto, que tinha dois cargos incompatíveis. Ele não provou boa-fé, foi demitido de ambos e terá de devolver os valores recebidos indevidamente."}},{"id":"aut.administrativo_tj.acumulacoes.0017","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, o funcionário que acumulou ilegalmente e provou boa-fé será mantido no cargo mais recente, por ser o de maior remuneração.","gabarito":"E","explicacao":"Provada a boa-fé, o funcionário é mantido no cargo ou função que exercer há mais tempo (art. 174, § 1º). O critério é a antiguidade do vínculo, não a remuneração nem o cargo mais recente.","fonte":"Lei 10.261/1968, art. 174, § 1º","mastigado":"Errado. Com boa-fé, o servidor fica com o cargo mais antigo, não com o mais novo nem com o que paga mais. O critério da lei é o tempo de exercício.","teSitua":{"termos":[{"termo":"acumulou ilegalmente","significado":"ocupou ao mesmo tempo cargos que a lei não permite acumular."},{"termo":"boa-fé","significado":"situação de quem age honestamente, sem saber que está errado."}],"exemplo":"Isadora ocupava um cargo desde 2015 e outro desde 2022, este mais bem pago. Provada a boa-fé, ela fica com o cargo de 2015, o que exerce há mais tempo, mesmo ganhando menos."}},{"id":"aut.administrativo_tj.acumulacoes.0018","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":3,"enunciado":"Um professor da rede estadual foi aprovado em concurso para cargo técnico de nível superior no Tribunal de Justiça, com horários compatíveis e correlação de matérias. Pelo art. 171 da Lei nº 10.261/1968, essa acumulação","alternativas":{"A":"é permitida, por se tratar de um cargo de professor e outro técnico ou científico.","B":"é vedada, pois o cargo técnico só pode ser acumulado com outro cargo técnico.","C":"é vedada em qualquer caso, por envolver Poderes diferentes.","D":"é permitida apenas se ele se aposentar como professor.","E":"depende de autorização do Presidente do Tribunal, independentemente dos horários."},"gabarito":"A","explicacao":"O art. 171, III, admite a acumulação de um cargo de professor e outro técnico ou científico, desde que haja correlação de matérias e compatibilidade de horários (§ 1º).","explicacoes":{"A":"Correta: art. 171, III.","B":"A lei não prevê acumulação de dois cargos técnicos.","C":"A lei não proíbe pela diferença de Poderes.","D":"Não se exige aposentadoria; é acumulação de cargos na ativa.","E":"A compatibilidade de horários é requisito legal; não há essa autorização na lei."},"fonte":"Lei 10.261/1968, art. 171, III, e § 1º","mastigado":"A resposta é a letra A. A lei permite juntar um cargo de professor com um cargo técnico ou científico. Como os horários batem e as matérias têm relação, o professor pode assumir o cargo técnico sem largar a sala de aula.","teSitua":{"termos":[{"termo":"técnico ou científico","significado":"cargo que exige conhecimento especializado, de nível técnico ou superior."},{"termo":"correlação de matérias","significado":"relação entre os conteúdos dos dois cargos."}],"exemplo":"Sandro é professor de contabilidade numa escola estadual à noite e passou para contador do Tribunal, com jornada diurna. A acumulação é permitida: um cargo de professor e outro técnico, com horários compatíveis."}},{"id":"aut.administrativo_tj.acumulacoes.0019","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Estatuto paulista, a acumulação de cargos públicos remunerados é, como regra, permitida, cabendo à lei enumerar as hipóteses de proibição.","gabarito":"E","explicacao":"A lógica é inversa: o art. 171 estabelece que é vedada a acumulação remunerada, enumerando as exceções em que ela é permitida.","fonte":"Lei 10.261/1968, art. 171, caput","mastigado":"Errado. A regra é a proibição. A lei só lista as exceções, em que acumular é permitido, como dois cargos de professor. Fora delas, acumular cargo pago é proibido.","teSitua":{"termos":[{"termo":"acumulação","significado":"exercício de dois ou mais cargos ao mesmo tempo."},{"termo":"remunerados","significado":"que pagam vencimento ou salário."}],"exemplo":"Valdir achava que podia ter quantos cargos quisesse, desde que coubessem no horário. Ao ler o Estatuto, descobriu que a regra é a proibição, e que só nas exceções da lei é permitido acumular."}},{"id":"aut.administrativo_tj.acumulacoes.0020","subtopico":"administrativo_tj.estatuto_sp.acumulacoes","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, o dever de comunicar a acumulação proibida de que tenham conhecimento alcança também","alternativas":{"A":"os diretores ou responsáveis pelas autarquias, empresas públicas e sociedades de economia mista, e os fiscais ou representantes dos poderes públicos junto a elas.","B":"apenas o Governador do Estado.","C":"somente os membros do Ministério Público.","D":"exclusivamente os Secretários de Estado.","E":"apenas os servidores da área de recursos humanos."},"gabarito":"A","explicacao":"O art. 175 inclui as autoridades civis e os chefes de serviço, bem como os diretores ou responsáveis pelas entidades referidas no § 2º do art. 174 e os fiscais ou representantes dos poderes públicos junto a elas.","explicacoes":{"A":"Correta: art. 175, caput.","B":"O dever não é só do Governador.","C":"O dever não é exclusivo do Ministério Público.","D":"Não se restringe aos Secretários.","E":"Não se restringe ao setor de recursos humanos."},"fonte":"Lei 10.261/1968, art. 175, caput","mastigado":"A resposta é a letra A. O dever de avisar é amplo: vale para autoridades e chefes do serviço público e também para diretores das empresas estatais e para quem fiscaliza essas empresas em nome do poder público.","teSitua":{"termos":[{"termo":"autarquias","significado":"entidades públicas criadas por lei para atividades típicas do Estado."},{"termo":"sociedades de economia mista","significado":"empresas com capital público e privado, controladas pelo Estado."},{"termo":"fiscais ou representantes dos poderes públicos","significado":"pessoas que acompanham e controlam a entidade em nome do Estado."}],"exemplo":"O diretor de uma empresa pública estadual soube que um empregado também ocupava cargo efetivo na Secretaria da Fazenda, fora das exceções legais. Ele comunicou o fato ao órgão competente, como exige o Estatuto."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0001","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da redação vigente da Lei nº 10.261/1968, o direito de petição contra ilegalidade ou abuso de poder e para defesa de direitos é assegurado","alternativas":{"A":"a qualquer pessoa, física ou jurídica, independentemente de pagamento.","B":"apenas aos funcionários públicos estaduais, mediante pagamento de taxa.","C":"somente às pessoas físicas residentes no Estado.","D":"apenas aos funcionários estáveis.","E":"a qualquer pessoa, desde que representada por advogado."},"gabarito":"A","explicacao":"O art. 239, com redação da LC 942/2003, assegura a qualquer pessoa, física ou jurídica, independentemente de pagamento, o direito de petição contra ilegalidade ou abuso de poder e para defesa de direitos.","explicacoes":{"A":"Correta: art. 239, caput.","B":"O direito não é restrito a funcionários e independe de pagamento.","C":"Pessoas jurídicas também têm o direito.","D":"Não há restrição a funcionários estáveis.","E":"Não se exige advogado."},"fonte":"Lei 10.261/1968, art. 239, caput (redação da LC 942/2003)","mastigado":"A resposta é a letra A. Qualquer pessoa, seja um cidadão ou uma empresa, pode fazer um pedido ou reclamação à Administração contra ilegalidade ou abuso, sem pagar nada e sem precisar de advogado.","teSitua":{"termos":[{"termo":"direito de petição","significado":"direito de fazer pedidos ou reclamações por escrito ao poder público."},{"termo":"abuso de poder","significado":"uso do cargo além dos limites da lei ou com finalidade desviada."},{"termo":"pessoa jurídica","significado":"entidade com existência legal própria, como empresa ou associação."}],"exemplo":"A empresa Alfa recebeu uma cobrança que considera ilegal de uma repartição estadual. Ela protocola uma petição contestando o ato, sem pagar nenhuma taxa e sem precisar de advogado, exercendo seu direito de petição."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0002","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto, em nenhuma hipótese a Administração poderá recusar-se a protocolar, encaminhar ou apreciar a petição, sob pena de responsabilidade do agente.","gabarito":"C","explicacao":"É o texto do art. 239, § 2º, na redação da LC 942/2003. O § 1º acrescenta que qualquer pessoa poderá reclamar sobre abuso, erro, omissão ou conduta incompatível no serviço público.","fonte":"Lei 10.261/1968, art. 239, § 2º","mastigado":"Certo. O servidor do protocolo não pode se recusar a receber o pedido de alguém, nem deixar de encaminhá-lo ou analisá-lo. Se fizer isso, ele responde pessoalmente pela recusa.","teSitua":{"termos":[{"termo":"protocolar","significado":"registrar oficialmente o recebimento de um documento, com número e data."},{"termo":"apreciar","significado":"examinar e decidir sobre o pedido."}],"exemplo":"Seu Joaquim foi ao balcão de uma repartição entregar uma reclamação. O atendente disse que não aceitaria o papel. Essa recusa é proibida: a reclamação deve ser protocolada e analisada, e o atendente pode ser responsabilizado."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0003","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Conforme a redação vigente da Lei nº 10.261/1968, ao servidor é assegurado o direito de requerer ou representar, bem como pedir reconsideração e recorrer de decisões, no prazo de","alternativas":{"A":"30 dias, salvo previsão legal específica.","B":"120 dias, em qualquer caso.","C":"5 anos, quanto a atos de demissão.","D":"15 dias, improrrogáveis.","E":"10 dias, contados da ciência."},"gabarito":"A","explicacao":"O art. 240, com redação da LC 942/2003, fixa o prazo de 30 dias, salvo previsão legal específica. A antiga redação, que falava em prescrição de 5 anos e de 120 dias, foi substituída.","explicacoes":{"A":"Correta: art. 240, redação vigente.","B":"Cento e vinte dias era prazo da redação antiga, revogada.","C":"Cinco anos era prazo da redação antiga, revogada.","D":"O prazo é de 30 dias.","E":"O prazo é de 30 dias."},"fonte":"Lei 10.261/1968, art. 240 (redação da LC 942/2003)","mastigado":"A resposta é a letra A. O servidor tem trinta dias para pedir que a decisão seja revista ou para recorrer, a não ser que outra lei preveja prazo diferente. Os prazos antigos de cinco anos e cento e vinte dias não valem mais.","teSitua":{"termos":[{"termo":"representar","significado":"comunicar formalmente uma irregularidade à autoridade."},{"termo":"pedir reconsideração","significado":"pedir à mesma autoridade que reveja a decisão que tomou."},{"termo":"previsão legal específica","significado":"regra própria de outra lei para aquele caso."}],"exemplo":"A servidora Elaine teve um pedido de licença indeferido. Ela tem trinta dias para pedir reconsideração à mesma autoridade ou recorrer, já que não há prazo especial previsto para o caso."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0004","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Lei nº 10.261/1968, é dever do funcionário","alternativas":{"A":"cumprir as ordens superiores, representando quando forem manifestamente ilegais.","B":"cumprir todas as ordens superiores, ainda que manifestamente ilegais.","C":"guardar sigilo apenas sobre assuntos que lhe forem expressamente declarados sigilosos por escrito.","D":"atender às requisições das autoridades judiciárias somente após concluir os serviços já iniciados.","E":"residir obrigatoriamente na capital do Estado."},"gabarito":"A","explicacao":"O art. 241, II, impõe cumprir as ordens superiores, representando quando forem manifestamente ilegais. O inciso IV manda guardar sigilo sobre os assuntos da repartição; o XI manda atender prontamente, com preferência, às requisições para defesa do Estado em juízo; o VII manda residir no local onde exerce o cargo ou onde autorizado.","explicacoes":{"A":"Correta: art. 241, II.","B":"Ordens manifestamente ilegais devem ser representadas, não simplesmente cumpridas.","C":"O sigilo abrange os assuntos da repartição em geral (inciso IV).","D":"As requisições para defesa do Estado em juízo têm preferência sobre qualquer outro serviço (inciso XI).","E":"O dever é residir no local onde exerce o cargo ou onde autorizado (inciso VII)."},"fonte":"Lei 10.261/1968, art. 241, II","mastigado":"A resposta é a letra A. O servidor obedece aos chefes, mas não de olhos fechados. Se a ordem for claramente ilegal, ele deve comunicar isso formalmente aos superiores, em vez de simplesmente cumprir.","teSitua":{"termos":[{"termo":"representando","significado":"comunicando formalmente, por escrito, uma irregularidade à autoridade."},{"termo":"manifestamente ilegais","significado":"claramente contrárias à lei, de forma evidente."},{"termo":"requisições","significado":"pedidos formais e obrigatórios feitos por autoridade."}],"exemplo":"O chefe de Mauro mandou que ele datasse um documento com data anterior para esconder um atraso. Como a ordem é claramente ilegal, Mauro não a cumpre e faz representação ao superior, relatando o ocorrido."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0005","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Considera-se cumprido o dever de representar aos superiores sobre irregularidades quando o funcionário apresentar denúncia diretamente à unidade de ouvidoria do órgão a que esteja vinculado, ou a outro órgão da Administração com competência para apurar a irregularidade.","gabarito":"C","explicacao":"É o que diz o parágrafo único do art. 241, acrescentado pela LC 1.419/2024, em relação ao dever do inciso V.","fonte":"Lei 10.261/1968, art. 241, V e parágrafo único (LC 1.419/2024)","mastigado":"Certo. O servidor que vê algo errado tem de avisar. Pela regra nova, ele cumpre esse dever também se fizer a denúncia direto na ouvidoria do órgão ou em outro órgão que possa investigar, sem passar pelo chefe.","teSitua":{"termos":[{"termo":"representar","significado":"comunicar formalmente uma irregularidade à autoridade."},{"termo":"ouvidoria","significado":"setor que recebe reclamações, denúncias e sugestões sobre o serviço público."}],"exemplo":"Nádia percebeu que o próprio chefe desviava material do cartório. Com receio de falar com ele, ela registrou denúncia na ouvidoria do órgão. Assim cumpriu seu dever de comunicar a irregularidade."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0006","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto paulista, constitui dever do funcionário atender prontamente, com preferência sobre qualquer outro serviço, às requisições de papéis, documentos, informações ou providências feitas pelas autoridades judiciárias ou administrativas para defesa do Estado em juízo.","gabarito":"C","explicacao":"É o dever do art. 241, XI. A preferência sobre qualquer outro serviço é característica marcante desse inciso.","fonte":"Lei 10.261/1968, art. 241, XI","mastigado":"Certo. Quando a Justiça ou a Administração pedem documentos para defender o Estado num processo, o servidor deve atender na hora, passando esse pedido à frente de qualquer outro serviço.","teSitua":{"termos":[{"termo":"requisições","significado":"pedidos formais e obrigatórios feitos por autoridade."},{"termo":"defesa do Estado em juízo","significado":"atuação para proteger os interesses do Estado num processo judicial."}],"exemplo":"A Procuradoria pediu à repartição de Celina cópias de um processo para defender o Estado numa ação. Celina interrompeu as outras tarefas e providenciou os documentos de imediato, como manda o Estatuto."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0007","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, é proibido ao funcionário, entre outras condutas,","alternativas":{"A":"retirar, sem prévia permissão da autoridade competente, qualquer documento ou objeto existente na repartição.","B":"ser acionista ou quotista de sociedade comercial.","C":"participar da direção de cooperativas e associações de classe.","D":"tratar com urbanidade as pessoas.","E":"apreciar, em trabalho assinado, os atos da Administração sob o aspecto doutrinário."},"gabarito":"A","explicacao":"O art. 242, II, proíbe retirar, sem prévia permissão, documento ou objeto da repartição. O art. 243, VI, permite ser acionista, quotista ou comanditário; o parágrafo único do art. 243 ressalva a direção de cooperativas e associações de classe; urbanidade é dever (art. 241, VI).","explicacoes":{"A":"Correta: art. 242, II.","B":"Ser acionista ou quotista é expressamente permitido (art. 243, VI, parte final).","C":"A direção de cooperativas e associações de classe está ressalvada (art. 243, parágrafo único).","D":"Tratar com urbanidade é dever (art. 241, VI).","E":"Essa ressalva constava do inciso I do art. 242, que foi revogado; não é proibição vigente."},"fonte":"Lei 10.261/1968, art. 242, II; art. 243, VI e parágrafo único","mastigado":"A resposta é a letra A. O servidor não pode levar embora papéis ou objetos da repartição sem autorização. Já ser sócio com cotas de uma empresa, ou dirigir uma cooperativa ou associação de classe, a lei permite.","teSitua":{"termos":[{"termo":"prévia permissão","significado":"autorização dada antes da conduta."},{"termo":"acionista ou quotista","significado":"pessoa que tem ações ou cotas de uma empresa, sem necessariamente administrá-la."},{"termo":"cooperativas","significado":"associações de pessoas que se unem para atividade econômica comum."},{"termo":"urbanidade","significado":"educação e cortesia no trato com as pessoas."}],"exemplo":"O escrevente Pablo quis levar um processo físico para casa para adiantar o serviço no fim de semana, sem pedir a ninguém. Isso é proibido. Mas ele pode, sem problema, ser cotista da empresa da família."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0008","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Estatuto, é proibido ao funcionário promover manifestações de apreço ou desapreço dentro da repartição, ou tornar-se solidário com elas, bem como promover ou subscrever listas de donativos dentro da repartição.","gabarito":"C","explicacao":"As duas proibições estão no art. 242, VI e VII. O inciso VII também proíbe exercer comércio entre os companheiros de serviço.","fonte":"Lei 10.261/1968, art. 242, VI e VII","mastigado":"Certo. Dentro da repartição, o servidor não pode organizar homenagens ou protestos contra pessoas, nem apoiar esses atos. Também não pode passar lista pedindo doações nem vender coisas aos colegas.","teSitua":{"termos":[{"termo":"manifestações de apreço ou desapreço","significado":"atos públicos de homenagem ou de protesto contra alguém."},{"termo":"subscrever listas de donativos","significado":"assinar ou contribuir em listas de arrecadação de doações."}],"exemplo":"Na seção de Lívia, um colega começou a passar uma lista recolhendo dinheiro para presentear o diretor e, ao mesmo tempo, vendia bolos aos colegas. As duas condutas são proibidas pelo Estatuto dentro da repartição."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0009","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente aceita ser procurador de um amigo para acompanhar um pedido na Prefeitura, sem relação de parentesco. Segundo a Lei nº 10.261/1968, essa conduta","alternativas":{"A":"é proibida, salvo quando se tratar de interesse de cônjuge ou parente até segundo grau.","B":"é permitida, desde que fora do horário de trabalho.","C":"é permitida, por se tratar de repartição municipal.","D":"é proibida apenas perante a repartição em que o funcionário estiver lotado.","E":"é permitida, se não houver remuneração."},"gabarito":"A","explicacao":"O art. 243, IX, proíbe constituir-se procurador de partes ou servir de intermediário perante qualquer repartição pública, exceto quando se tratar de interesse de cônjuge ou parente até segundo grau.","explicacoes":{"A":"Correta: art. 243, IX.","B":"A proibição não depende do horário.","C":"A vedação alcança qualquer repartição pública.","D":"A vedação alcança qualquer repartição, não só a de lotação.","E":"A gratuidade não afasta a proibição."},"fonte":"Lei 10.261/1968, art. 243, IX","mastigado":"A resposta é a letra A. O servidor não pode atuar como intermediário ou procurador de outras pessoas em repartições públicas. A única exceção é quando ele defende interesse do cônjuge ou de parente próximo, até o segundo grau.","teSitua":{"termos":[{"termo":"procurador","significado":"pessoa autorizada a agir em nome de outra."},{"termo":"intermediário","significado":"quem faz a ponte entre o interessado e a repartição para conseguir algo."},{"termo":"parente até segundo grau","significado":"pais, filhos, avós, netos e irmãos."}],"exemplo":"O escrevente Hugo foi à Prefeitura acompanhar o pedido de alvará do amigo Rogério, com procuração. Isso é proibido. Se fosse um pedido da própria mãe ou do irmão, ele poderia atuar."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0010","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Lei nº 10.261/1968, é vedado ao funcionário trabalhar sob as ordens imediatas de parentes até segundo grau, salvo quando se tratar de função de confiança e livre escolha, não podendo exceder a","alternativas":{"A":"2 o número de auxiliares nessas condições.","B":"1 o número de auxiliares nessas condições.","C":"3 o número de auxiliares nessas condições.","D":"5 o número de auxiliares nessas condições.","E":"10% do total de servidores da unidade."},"gabarito":"A","explicacao":"O art. 244 veda trabalhar sob as ordens imediatas de parentes até segundo grau, salvo função de confiança e livre escolha, não podendo exceder a 2 o número de auxiliares nessas condições.","explicacoes":{"A":"Correta: art. 244.","B":"O limite é de 2 auxiliares.","C":"O limite é de 2 auxiliares.","D":"O limite é de 2 auxiliares.","E":"A lei fixa um número, não um percentual."},"fonte":"Lei 10.261/1968, art. 244","mastigado":"A resposta é a letra A. Em regra, o servidor não pode ter como chefe direto um parente próximo. Em cargo de confiança, a exceção existe, mas só para no máximo dois auxiliares parentes.","teSitua":{"termos":[{"termo":"ordens imediatas","significado":"comando direto de um chefe, sem intermediários."},{"termo":"parentes até segundo grau","significado":"pais, filhos, avós, netos e irmãos."},{"termo":"função de confiança e livre escolha","significado":"posto escolhido livremente pela autoridade, baseado na confiança."}],"exemplo":"A diretora Sílvia queria ter três sobrinhos como subordinados diretos. Mesmo em funções de confiança, isso não é possível: o Estatuto permite, nesses casos, no máximo dois auxiliares parentes até o segundo grau."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0011","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto, o funcionário é responsável por todos os prejuízos que, nessa qualidade, causar à Fazenda Estadual, ainda que sem dolo ou culpa, bastando o nexo com o exercício do cargo.","gabarito":"E","explicacao":"O art. 245 condiciona a responsabilidade do funcionário a dolo ou culpa, devidamente apurados. Não há responsabilidade sem culpa nessa hipótese.","fonte":"Lei 10.261/1968, art. 245, caput","mastigado":"Errado. O servidor só responde pelo prejuízo que causar ao Estado se agiu de propósito ou com descuido, e isso precisa ser comprovado. Sem dolo ou culpa, não há responsabilidade dele.","teSitua":{"termos":[{"termo":"Fazenda Estadual","significado":"patrimônio e finanças do Estado."},{"termo":"dolo ou culpa","significado":"intenção de causar o dano, ou descuido, imprudência ou falta de atenção."},{"termo":"nexo","significado":"ligação entre a conduta e o resultado."}],"exemplo":"Um temporal derrubou uma árvore sobre o carro oficial que Gilson dirigia com todo o cuidado. Como não houve dolo nem culpa dele, Gilson não responde pelo prejuízo causado ao patrimônio do Estado."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0012","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Lei nº 10.261/1968, caracteriza-se especialmente a responsabilidade do funcionário, entre outras hipóteses,","alternativas":{"A":"pelas faltas, danos e avarias que sofrerem os bens e materiais sob sua guarda, ou sujeitos a seu exame ou fiscalização.","B":"pelos danos causados por terceiros a bens que não estejam sob sua guarda.","C":"pelos prejuízos decorrentes de caso fortuito, sem culpa sua.","D":"por qualquer prejuízo sofrido pelo Estado, ainda que causado por outro servidor.","E":"apenas quando houver condenação criminal."},"gabarito":"A","explicacao":"O parágrafo único do art. 245 lista, entre os casos de responsabilidade: sonegação de valores ou não prestação de contas (I); faltas, danos e avarias em bens sob sua guarda ou fiscalização (II); falta ou inexatidão de averbações em documentos da receita (III); e erro de cálculo ou redução contra a Fazenda (IV).","explicacoes":{"A":"Correta: art. 245, parágrafo único, II.","B":"A lei fala em bens sob a guarda, exame ou fiscalização do funcionário.","C":"A responsabilidade exige dolo ou culpa (caput).","D":"Cada um responde pelos próprios atos, com dolo ou culpa.","E":"A responsabilidade administrativa independe da criminal (art. 250, § 1º)."},"fonte":"Lei 10.261/1968, art. 245, parágrafo único, II","mastigado":"A resposta é a letra A. O servidor que tem bens ou materiais sob sua guarda responde se eles se perderem ou estragarem por culpa dele. Não responde por coisas fora do seu cuidado nem por acidentes sem culpa.","teSitua":{"termos":[{"termo":"avarias","significado":"danos ou estragos em um bem."},{"termo":"sob sua guarda","significado":"sob seu cuidado e responsabilidade."},{"termo":"caso fortuito","significado":"acontecimento imprevisível que ninguém poderia evitar."}],"exemplo":"Carmem era responsável pelo almoxarifado do fórum e deixou a porta aberta durante a noite. Sumiram dez caixas de papel. Por negligência na guarda, ela responde pelo prejuízo."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0013","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Um funcionário causou prejuízo à Fazenda Estadual por desfalque. De acordo com a Lei nº 10.261/1968, a indenização","alternativas":{"A":"deverá ser reposta de uma só vez.","B":"poderá ser descontada em parcelas não superiores à décima parte do vencimento.","C":"será perdoada se ele pedir exoneração.","D":"poderá ser parcelada em até 48 meses.","E":"dependerá de condenação criminal transitada em julgado."},"gabarito":"A","explicacao":"O art. 247 manda repor de uma só vez o prejuízo causado por alcance, desfalque, remissão ou omissão em efetuar recolhimento ou entrada nos prazos legais. Fora desses casos, o desconto pode ser feito no vencimento, limitado à décima parte (art. 248).","explicacoes":{"A":"Correta: art. 247.","B":"O desconto parcelado limitado a um décimo vale para os demais casos (art. 248).","C":"Não há perdão por exoneração.","D":"Não há parcelamento em 48 meses no Estatuto.","E":"A responsabilidade administrativa é independente (art. 250, § 1º)."},"fonte":"Lei 10.261/1968, arts. 247 e 248","mastigado":"A resposta é a letra A. Se o servidor desviou dinheiro (desfalque, alcance) ou deixou de recolher valores no prazo, tem de devolver tudo de uma vez. O desconto em parcelas no salário é só para os outros tipos de prejuízo.","teSitua":{"termos":[{"termo":"desfalque","significado":"desvio de dinheiro ou valores que estavam sob a responsabilidade do servidor."},{"termo":"Fazenda Estadual","significado":"patrimônio e finanças do Estado de São Paulo."},{"termo":"indenização","significado":"pagamento feito para reparar um prejuízo causado."}],"exemplo":"O caixa Jairo deixou de recolher aos cofres públicos valores recebidos no balcão e ficou com a diferença. Descoberto o desfalque, ele deve repor todo o valor de uma só vez."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0014","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Fora dos casos de alcance, desfalque, remissão ou omissão de recolhimento, a importância da indenização poderá ser descontada do vencimento ou remuneração, não excedendo o desconto à décima parte do valor destes.","gabarito":"C","explicacao":"É a regra do art. 248, caput. O parágrafo único acrescenta que, no caso de erro de cálculo ou redução contra a Fazenda sem má-fé, aplica-se pena de repreensão e, na reincidência, suspensão.","fonte":"Lei 10.261/1968, art. 248, caput","mastigado":"Certo. Nos prejuízos comuns, que não são desvio de dinheiro, o valor pode ser descontado do salário aos poucos, mas cada desconto mensal não pode passar de dez por cento do que o servidor ganha.","teSitua":{"termos":[{"termo":"indenização","significado":"pagamento para reparar um prejuízo causado."},{"termo":"décima parte","significado":"dez por cento do valor."}],"exemplo":"Por descuido, Rosana quebrou um equipamento do cartório que valia R$ 3.000. Como não houve desvio de dinheiro, o valor será descontado do salário dela em parcelas que não passam de dez por cento da remuneração."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0015","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"No caso de erro de cálculo ou redução contra a Fazenda Estadual, não tendo havido má-fé, a Lei nº 10.261/1968 prevê a aplicação da pena de","alternativas":{"A":"repreensão e, na reincidência, a de suspensão.","B":"demissão, em qualquer caso.","C":"multa e, na reincidência, a de demissão.","D":"suspensão de 90 dias.","E":"demissão a bem do serviço público."},"gabarito":"A","explicacao":"O parágrafo único do art. 248 determina, no caso do item IV do parágrafo único do art. 245 (erro de cálculo ou redução contra a Fazenda), sem má-fé, a pena de repreensão e, na reincidência, a de suspensão.","explicacoes":{"A":"Correta: art. 248, parágrafo único.","B":"A demissão não está prevista para erro sem má-fé.","C":"A lei fala em repreensão e suspensão.","D":"A suspensão vem apenas na reincidência e sem prazo fixado nesse artigo.","E":"A demissão a bem do serviço público é para faltas gravíssimas (art. 257)."},"fonte":"Lei 10.261/1968, art. 248, parágrafo único; art. 245, parágrafo único, IV","mastigado":"A resposta é a letra A. Se o servidor errou uma conta e o Estado perdeu dinheiro, mas sem má intenção, a punição é leve: repreensão. Se repetir o erro, a pena sobe para suspensão.","teSitua":{"termos":[{"termo":"erro de cálculo","significado":"conta feita de forma errada."},{"termo":"redução contra a Fazenda","significado":"diminuição indevida de valor devido ao Estado."},{"termo":"má-fé","significado":"intenção desonesta de prejudicar ou de obter vantagem."},{"termo":"reincidência","significado":"repetição de uma falta já punida antes."}],"exemplo":"Ao calcular custas, o escrevente Teles errou uma conta e o Estado recebeu menos do que devia. Como não houve má-fé, levou repreensão. Meses depois, repetiu o erro e recebeu suspensão."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0016","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto, será responsabilizado o funcionário que, fora dos casos expressamente previstos nas leis, regulamentos ou regimentos, cometer a pessoas estranhas às repartições o desempenho de encargos que lhe competirem ou aos seus subordinados.","gabarito":"C","explicacao":"É a regra do art. 249. Entregar a terceiros tarefas próprias do cargo, sem previsão normativa, gera responsabilidade do funcionário.","fonte":"Lei 10.261/1968, art. 249","mastigado":"Certo. O servidor não pode passar o próprio trabalho, ou o dos subordinados, para pessoas de fora da repartição, salvo quando a norma permitir. Se fizer isso, responde pela conduta.","teSitua":{"termos":[{"termo":"cometer","significado":"entregar ou atribuir uma tarefa a alguém."},{"termo":"pessoas estranhas às repartições","significado":"pessoas que não fazem parte do quadro do órgão público."},{"termo":"encargos","significado":"tarefas e obrigações do cargo."}],"exemplo":"Sobrecarregado, o escrevente Amauri pediu ao sobrinho, que não é servidor, para expedir mandados no sistema usando sua senha. Como não há previsão que autorize isso, Amauri será responsabilizado."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0017","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Lei nº 10.261/1968, com as alterações da LC 942/2003, a responsabilidade administrativa","alternativas":{"A":"é independente da civil e da criminal.","B":"depende sempre do resultado do processo criminal.","C":"fica excluída se houver indenização do prejuízo.","D":"só pode ser apurada após a condenação civil.","E":"é absorvida pela responsabilidade criminal, quando o fato também for crime."},"gabarito":"A","explicacao":"O art. 250 diz que a responsabilidade administrativa não exime da civil ou criminal, nem o pagamento da indenização exime da pena disciplinar; o § 1º afirma que a responsabilidade administrativa é independente da civil e da criminal.","explicacoes":{"A":"Correta: art. 250, § 1º.","B":"As esferas são independentes; o sobrestamento é exceção, por despacho motivado (§ 3º).","C":"Indenizar não afasta a pena disciplinar (caput).","D":"Não há essa dependência.","E":"As responsabilidades se somam; uma não absorve a outra."},"fonte":"Lei 10.261/1968, art. 250, caput e § 1º","mastigado":"A resposta é a letra A. Um mesmo fato pode gerar três consequências separadas: punição administrativa, obrigação de pagar o prejuízo e processo criminal. Uma não depende da outra, e pagar o prejuízo não livra da punição.","teSitua":{"termos":[{"termo":"responsabilidade administrativa","significado":"dever de responder perante a Administração por falta funcional, com punição disciplinar."},{"termo":"civil","significado":"relativa à obrigação de reparar o dano em dinheiro."},{"termo":"criminal","significado":"relativa à punição por crime, aplicada pela Justiça penal."}],"exemplo":"Ozias desviou material do fórum. Ele responde a processo disciplinar, terá de indenizar o Estado e ainda pode ser processado criminalmente. Mesmo que devolva o valor, a punição administrativa pode ser aplicada."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0018","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Um servidor demitido foi absolvido na Justiça criminal por decisão transitada em julgado que negou a existência do fato que deu origem à sua demissão. Nos termos do Estatuto paulista, ele","alternativas":{"A":"será reintegrado ao cargo, com todos os direitos e vantagens devidas, mediante simples comprovação do trânsito em julgado.","B":"não terá qualquer direito, pois as esferas são independentes.","C":"poderá ser readmitido após 5 anos.","D":"será aposentado compulsoriamente.","E":"precisará ajuizar ação própria para obter a revisão do processo."},"gabarito":"A","explicacao":"O art. 250, § 2º, prevê a reintegração do servidor absolvido pela Justiça, mediante simples comprovação do trânsito em julgado de decisão que negue a existência de sua autoria ou do fato que deu origem à demissão.","explicacoes":{"A":"Correta: art. 250, § 2º.","B":"A independência das esferas tem essa exceção expressa.","C":"Readmissão é outra figura, sem ressarcimento (art. 39).","D":"Não há aposentadoria compulsória nessa hipótese.","E":"Basta a simples comprovação do trânsito em julgado."},"fonte":"Lei 10.261/1968, art. 250, § 2º","mastigado":"A resposta é a letra A. Se a Justiça criminal diz, de forma definitiva, que o fato não existiu ou que não foi ele, o servidor demitido volta ao cargo com todos os direitos. Basta mostrar a decisão definitiva.","teSitua":{"termos":[{"termo":"absolvido","significado":"declarado não culpado pela Justiça."},{"termo":"transitada em julgado","significado":"decisão definitiva, contra a qual não cabe mais recurso."},{"termo":"reintegrado","significado":"devolvido ao cargo com os direitos do período em que ficou afastado."}],"exemplo":"Leonel foi demitido acusado de furtar um computador do fórum. Na ação penal, a Justiça concluiu, em decisão definitiva, que o furto nunca aconteceu. Com a certidão do trânsito em julgado, Leonel é reintegrado ao cargo."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0019","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, o processo administrativo só poderá ser sobrestado para aguardar decisão judicial por despacho motivado da autoridade competente para aplicar a pena.","gabarito":"C","explicacao":"É a regra do art. 250, § 3º. Enquanto o processo estiver sobrestado nessas condições, a prescrição não corre (art. 261, § 4º, 1).","fonte":"Lei 10.261/1968, art. 250, § 3º; art. 261, § 4º, 1","mastigado":"Certo. O processo disciplinar, como regra, anda sozinho. Ele só pode ser parado para esperar a decisão da Justiça se a autoridade que aplicaria a pena decidir isso de forma fundamentada.","teSitua":{"termos":[{"termo":"sobrestado","significado":"suspenso temporariamente, à espera de outro acontecimento."},{"termo":"despacho motivado","significado":"decisão escrita que apresenta as razões que a justificam."}],"exemplo":"O processo disciplinar contra Patrícia apura o mesmo fato de uma ação penal. A autoridade competente para punir decidiu, em despacho fundamentado, suspender o processo até a sentença criminal, o que impede a prescrição de correr nesse período."}},{"id":"aut.administrativo_tj.deveres_responsabilidades.0020","subtopico":"administrativo_tj.estatuto_sp.deveres_responsabilidades","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Lei nº 10.261/1968, o funcionário que adquirir materiais em desacordo com disposições legais e regulamentares","alternativas":{"A":"será responsabilizado pelo respectivo custo, sem prejuízo das penalidades disciplinares, podendo-se proceder ao desconto no seu vencimento.","B":"ficará isento de responsabilidade se os materiais forem utilizados no serviço.","C":"responderá apenas disciplinarmente, sem obrigação de ressarcir.","D":"terá de pagar o dobro do valor dos materiais.","E":"só responderá se houver condenação criminal."},"gabarito":"A","explicacao":"O art. 246 responsabiliza o funcionário pelo custo dos materiais adquiridos irregularmente, sem prejuízo das penalidades disciplinares, autorizando o desconto no vencimento ou remuneração.","explicacoes":{"A":"Correta: art. 246.","B":"O uso no serviço não afasta a responsabilidade.","C":"Há responsabilidade pelo custo, além da disciplinar.","D":"A lei não prevê pagamento em dobro.","E":"Não há exigência de condenação criminal."},"fonte":"Lei 10.261/1968, art. 246","mastigado":"A resposta é a letra A. Se o servidor compra material sem seguir as regras de compra, ele paga o custo do próprio bolso, podendo ser descontado do salário, e ainda pode sofrer punição disciplinar.","teSitua":{"termos":[{"termo":"em desacordo","significado":"de forma contrária ao que as normas exigem."},{"termo":"penalidades disciplinares","significado":"punições aplicadas ao servidor por faltas funcionais."}],"exemplo":"Sem fazer o procedimento de compra exigido, o chefe de seção Ítalo comprou cadeiras numa loja de um conhecido. Ele terá de arcar com o custo, com desconto no salário, e pode ainda responder a processo disciplinar."}},{"id":"aut.administrativo_tj.lia.0001","subtopico":"administrativo_tj.improbidade.lia","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a Lei nº 8.429/1992, com a redação dada pela Lei nº 14.230/2021, consideram-se atos de improbidade administrativa as condutas dolosas tipificadas na lei, entendendo-se por dolo a vontade livre e consciente de alcançar o resultado ilícito, não bastando a voluntariedade do agente.","gabarito":"C","explicacao":"O art. 1º, § 1º, restringe a improbidade às condutas dolosas tipificadas nos arts. 9º, 10 e 11, e o § 2º define dolo como a vontade livre e consciente de alcançar o resultado ilícito, não bastando a voluntariedade. O § 3º acrescenta que o mero exercício da função, sem prova de ato doloso com fim ilícito, afasta a responsabilidade; e o art. 17-C, § 1º, que a ilegalidade sem dolo não configura improbidade.","fonte":"Lei 8.429/1992, art. 1º, §§ 1º a 3º","mastigado":"Certo. Depois da reforma de 2021, só há improbidade quando o agente quer o resultado ilícito. Errar por descuido ou praticar um ato ilegal sem essa intenção pode gerar outras consequências, mas não é improbidade.","teSitua":{"termos":[{"termo":"improbidade administrativa","significado":"conduta desonesta de agente público que fere a Administração, punida pela lei específica."},{"termo":"dolo","significado":"vontade livre e consciente de alcançar o resultado ilícito."},{"termo":"voluntariedade","significado":"simples fato de agir por vontade própria, sem necessariamente querer o resultado ilícito."}],"exemplo":"O servidor Artur assinou um contrato com erro formal por desconhecimento, sem intenção de beneficiar ninguém. Não há improbidade. Já Beatriz fraudou propositalmente uma compra para favorecer um amigo: ela agiu com dolo e pode responder pela lei."}},{"id":"aut.administrativo_tj.lia.0002","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":2,"enunciado":"Um escrevente recebe de um advogado um aparelho celular de presente para dar andamento prioritário aos processos do escritório. Nos termos da Lei nº 8.429/1992, a conduta configura, em tese, ato de improbidade administrativa","alternativas":{"A":"que importa enriquecimento ilícito.","B":"que causa lesão ao erário, independentemente de perda patrimonial.","C":"que atenta contra os princípios, punível apenas com advertência.","D":"culposo, por ausência de dano ao Estado.","E":"que não é punível, por não haver prejuízo aos cofres públicos."},"gabarito":"A","explicacao":"O art. 9º, I, define como enriquecimento ilícito receber, para si ou para outrem, qualquer vantagem econômica, a título de presente, de quem tenha interesse que possa ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente. A aplicação das sanções independe de dano ao patrimônio público, salvo quanto ao ressarcimento e às condutas do art. 10 (art. 21, I).","explicacoes":{"A":"Correta: art. 9º, I.","B":"O art. 10 exige perda patrimonial efetiva e comprovada.","C":"Não há pena de advertência na lei; e o caso é de enriquecimento ilícito.","D":"Não existe improbidade culposa após a Lei 14.230/2021 (art. 1º, § 1º).","E":"As sanções independem de dano ao erário, salvo exceções (art. 21, I)."},"fonte":"Lei 8.429/1992, art. 9º, I; art. 21, I","mastigado":"A resposta é a letra A. O escrevente ganhou um presente de quem tinha interesse no trabalho dele. Isso é enriquecimento ilícito, mesmo sem prejuízo direto aos cofres públicos, porque ele lucrou com o cargo.","teSitua":{"termos":[{"termo":"enriquecimento ilícito","significado":"ganho indevido obtido pelo agente público em razão do cargo."},{"termo":"lesão ao erário","significado":"prejuízo efetivo ao patrimônio público."},{"termo":"andamento prioritário","significado":"tratamento à frente dos demais, furando a fila."}],"exemplo":"O advogado Renan deu um celular novo ao escrevente Caio para que seus processos fossem movimentados antes dos outros. Caio aceitou. Ele pode responder por improbidade que importa enriquecimento ilícito, mesmo que o Estado não tenha perdido dinheiro."}},{"id":"aut.administrativo_tj.lia.0003","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a Lei nº 8.429/1992, constitui ato de improbidade administrativa que causa lesão ao erário qualquer ação ou omissão dolosa que enseje","alternativas":{"A":"efetiva e comprovadamente, perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação dos bens ou haveres das entidades protegidas.","B":"presumidamente, prejuízo ao patrimônio público, ainda que não comprovado.","C":"violação a qualquer princípio da Administração, ainda que sem dano.","D":"mera perda patrimonial decorrente da atividade econômica, ainda que sem dolo.","E":"simples inobservância de formalidade legal, mesmo sem perda patrimonial, com obrigação de ressarcimento."},"gabarito":"A","explicacao":"O art. 10 exige ação ou omissão dolosa que enseje, efetiva e comprovadamente, perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação. Se a inobservância de formalidades não implicar perda patrimonial efetiva, não há ressarcimento (§ 1º), e a mera perda decorrente da atividade econômica não é improbidade, salvo ato doloso com essa finalidade (§ 2º).","explicacoes":{"A":"Correta: art. 10, caput.","B":"O dano deve ser efetivo e comprovado, não presumido.","C":"Violação a princípios é o art. 11, e com rol de condutas.","D":"A mera perda da atividade econômica não é improbidade, salvo ato doloso (§ 2º).","E":"Sem perda patrimonial efetiva, não há ressarcimento (§ 1º)."},"fonte":"Lei 8.429/1992, art. 10, caput e §§ 1º e 2º","mastigado":"A resposta é a letra A. Para haver lesão ao erário, é preciso provar que o Estado realmente perdeu dinheiro ou bens, e que o agente agiu com intenção. Dano presumido ou simples falha de formalidade não bastam.","teSitua":{"termos":[{"termo":"erário","significado":"patrimônio público; os cofres do Estado."},{"termo":"malbaratamento","significado":"desperdício ou venda por preço muito abaixo do valor."},{"termo":"dilapidação","significado":"destruição ou gasto ruinoso do patrimônio."},{"termo":"haveres","significado":"bens e valores que pertencem a alguém."}],"exemplo":"O prefeito Saulo, de propósito, alugou um imóvel para a prefeitura pelo dobro do preço de mercado, e a perícia comprovou o prejuízo. Há lesão ao erário. Se o aluguel tivesse apenas um erro de papelada, sem prejuízo, não haveria esse tipo de improbidade."}},{"id":"aut.administrativo_tj.lia.0004","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":3,"enunciado":"Após a Lei nº 14.230/2021, o art. 11 da Lei nº 8.429/1992 descreve o ato de improbidade que atenta contra os princípios da Administração como a ação ou omissão dolosa que viole os deveres de honestidade, de imparcialidade e de legalidade, caracterizada por uma das condutas nele enumeradas. Entre essas condutas está","alternativas":{"A":"nomear cônjuge, companheiro ou parente até o terceiro grau da autoridade nomeante para cargo em comissão ou de confiança.","B":"receber vantagem econômica para omitir ato de ofício.","C":"permitir a aquisição de bem por preço superior ao de mercado.","D":"incorporar ao seu patrimônio bens integrantes do acervo público.","E":"realizar operação financeira sem observância das normas legais."},"gabarito":"A","explicacao":"O nepotismo, inclusive por designações recíprocas, está no art. 11, XI. Receber vantagem para omitir ato de ofício (art. 9º, X) e incorporar bens públicos (art. 9º, XI) são enriquecimento ilícito; permitir compra acima do mercado (art. 10, V) e operação financeira irregular (art. 10, VI) são lesão ao erário.","explicacoes":{"A":"Correta: art. 11, XI.","B":"É enriquecimento ilícito (art. 9º, X).","C":"É lesão ao erário (art. 10, V).","D":"É enriquecimento ilícito (art. 9º, XI).","E":"É lesão ao erário (art. 10, VI)."},"fonte":"Lei 8.429/1992, art. 11, XI","mastigado":"A resposta é a letra A. Nomear parente para cargo de confiança é o nepotismo, que fere os princípios da Administração. As outras condutas envolvem ganho indevido do agente ou prejuízo aos cofres públicos e ficam em outros artigos da lei.","teSitua":{"termos":[{"termo":"princípios da Administração","significado":"regras básicas que orientam a atuação pública, como legalidade e imparcialidade."},{"termo":"autoridade nomeante","significado":"quem tem o poder de nomear para o cargo."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."},{"termo":"ato de ofício","significado":"ato que o agente deve praticar por dever do cargo."}],"exemplo":"O diretor Fausto nomeou o próprio sobrinho como seu assessor em comissão. A conduta se enquadra no art. 11, como ato que atenta contra os princípios da Administração, se presente o dolo exigido pela lei."}},{"id":"aut.administrativo_tj.lia.0005","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":3,"enunciado":"Conforme o art. 12 da Lei nº 8.429/1992, na hipótese de ato de improbidade que importe enriquecimento ilícito (art. 9º), o responsável está sujeito, entre outras cominações, à","alternativas":{"A":"suspensão dos direitos políticos até 14 anos e proibição de contratar com o poder público pelo prazo não superior a 14 anos.","B":"suspensão dos direitos políticos até 12 anos e multa de até 24 vezes a remuneração.","C":"suspensão dos direitos políticos de 8 a 10 anos, obrigatoriamente.","D":"apenas multa civil de até 24 vezes a remuneração, sem perda da função.","E":"suspensão dos direitos políticos até 4 anos."},"gabarito":"A","explicacao":"O art. 12, I, prevê para o art. 9º: perda dos bens acrescidos ilicitamente, perda da função pública, suspensão dos direitos políticos até 14 anos, multa equivalente ao acréscimo patrimonial e proibição de contratar ou receber benefícios por até 14 anos. Para o art. 10, os limites são de 12 anos (inciso II); para o art. 11, multa de até 24 vezes a remuneração e proibição de contratar por até 4 anos (inciso III).","explicacoes":{"A":"Correta: art. 12, I.","B":"Doze anos é o limite do art. 10; multa de 24 vezes a remuneração é do art. 11.","C":"A lei fixa teto (até 14 anos), sem mínimo de 8 anos; as penas podem ser aplicadas isolada ou cumulativamente.","D":"Essas sanções são as do art. 11 (inciso III).","E":"Quatro anos é o prazo da proibição de contratar no art. 11."},"fonte":"Lei 8.429/1992, art. 12, I a III","mastigado":"A resposta é a letra A. Quanto mais grave o ato, maior a pena. No enriquecimento ilícito, o pior caso, os direitos políticos podem ficar suspensos por até catorze anos. Na lesão ao erário, até doze. Na ofensa a princípios, não há suspensão de direitos políticos.","teSitua":{"termos":[{"termo":"cominações","significado":"penas ou sanções previstas em lei."},{"termo":"suspensão dos direitos políticos","significado":"perda temporária do direito de votar e de ser votado."},{"termo":"multa civil","significado":"pena em dinheiro aplicada na ação de improbidade."}],"exemplo":"Condenado por receber propina, o vereador Hélio teve os direitos políticos suspensos por dez anos e ficou proibido de contratar com o poder público pelo mesmo período. Ambas as penas respeitam o limite de catorze anos do enriquecimento ilícito."}},{"id":"aut.administrativo_tj.lia.0006","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos da Lei nº 8.429/1992, a perda da função pública e a suspensão dos direitos políticos","alternativas":{"A":"só se efetivam com o trânsito em julgado da sentença condenatória.","B":"efetivam-se com a publicação da sentença de primeiro grau.","C":"efetivam-se com a decisão colegiada de segundo grau, independentemente de recurso.","D":"podem ser aplicadas liminarmente pelo juiz, no início do processo.","E":"efetivam-se com a decisão administrativa da autoridade a que o agente está subordinado."},"gabarito":"A","explicacao":"O art. 20 dispõe que a perda da função pública e a suspensão dos direitos políticos só se efetivam com o trânsito em julgado da sentença condenatória, e o art. 12, § 9º, que as sanções só podem ser executadas após o trânsito em julgado. No curso do processo, o juiz pode afastar o agente, sem prejuízo da remuneração, por até 90 dias, prorrogáveis uma única vez (art. 20, §§ 1º e 2º).","explicacoes":{"A":"Correta: art. 20, caput.","B":"Exige-se o trânsito em julgado.","C":"Exige-se o trânsito em julgado.","D":"No início do processo cabe apenas afastamento cautelar, sem prejuízo da remuneração (art. 20, § 1º).","E":"As sanções da lei são aplicadas pelo Judiciário."},"fonte":"Lei 8.429/1992, art. 20, caput e §§ 1º e 2º; art. 12, § 9º","mastigado":"A resposta é a letra A. O agente só perde o cargo e os direitos políticos quando a condenação fica definitiva. Antes disso, o juiz pode no máximo afastá-lo temporariamente, sem cortar o salário, para proteger o processo.","teSitua":{"termos":[{"termo":"perda da função pública","significado":"sanção que retira o agente do cargo, emprego ou função que ocupa."},{"termo":"trânsito em julgado","significado":"momento em que a decisão se torna definitiva, sem recurso possível."},{"termo":"liminarmente","significado":"logo no início do processo, antes da decisão final."}],"exemplo":"A servidora Marta foi condenada por improbidade em primeira instância e recorreu. Enquanto o recurso não é julgado de forma definitiva, ela não perde a função nem os direitos políticos. Só com o trânsito em julgado essas sanções se efetivam."}},{"id":"aut.administrativo_tj.lia.0007","subtopico":"administrativo_tj.improbidade.lia","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a Lei nº 8.429/1992, a autoridade judicial pode determinar o afastamento do agente público do exercício do cargo, sem prejuízo da remuneração, quando necessário à instrução processual ou para evitar a iminente prática de novos ilícitos, por até 180 dias, prorrogáveis sucessivamente.","gabarito":"E","explicacao":"O art. 20, § 2º, limita esse afastamento a até 90 dias, prorrogáveis uma única vez por igual prazo, mediante decisão motivada. A afirmativa troca o prazo e a regra de prorrogação.","fonte":"Lei 8.429/1992, art. 20, §§ 1º e 2º","mastigado":"Errado. O juiz pode afastar o agente sem cortar o salário, mas por até noventa dias, prorrogáveis só uma vez. Cento e oitenta dias com prorrogações sem fim não é o que a lei diz.","teSitua":{"termos":[{"termo":"instrução processual","significado":"fase do processo em que se produzem as provas."},{"termo":"iminente","significado":"que está prestes a acontecer."},{"termo":"sem prejuízo da remuneração","significado":"mantendo o pagamento do salário durante o afastamento."}],"exemplo":"Investigado por fraudes, o diretor Rui estava pressionando testemunhas. O juiz o afastou do cargo por noventa dias, mantendo o salário, e depois prorrogou uma única vez por mais noventa dias, em decisão fundamentada."}},{"id":"aut.administrativo_tj.lia.0008","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com a Lei nº 8.429/1992, a ação para a aplicação das sanções previstas na lei prescreve em","alternativas":{"A":"8 anos, contados a partir da ocorrência do fato ou, no caso de infrações permanentes, do dia em que cessou a permanência; interrompida a prescrição, o prazo recomeça a correr pela metade.","B":"5 anos, contados do término do mandato ou do exercício do cargo em comissão.","C":"10 anos, contados da ciência do fato pela autoridade.","D":"8 anos, contados do conhecimento do fato pelo Ministério Público, sem possibilidade de interrupção.","E":"4 anos, contados da instauração do inquérito civil."},"gabarito":"A","explicacao":"O art. 23 fixa a prescrição em 8 anos, contados da ocorrência do fato ou, nas infrações permanentes, da cessação da permanência. O § 4º lista as causas de interrupção (ajuizamento da ação, publicação de sentença condenatória e de decisões confirmatórias), e o § 5º diz que, interrompida, a prescrição recomeça a correr pela metade do prazo (4 anos).","explicacoes":{"A":"Correta: art. 23, caput e § 5º.","B":"Era a regra anterior à Lei 14.230/2021.","C":"O prazo é de 8 anos e conta do fato.","D":"Conta-se do fato, e há causas de interrupção (§ 4º).","E":"Não é o prazo da lei."},"fonte":"Lei 8.429/1992, art. 23, caput, §§ 4º e 5º","mastigado":"A resposta é a letra A. Desde a reforma de 2021, o prazo para processar por improbidade é de oito anos a partir do fato. Quando a prescrição é interrompida, por exemplo com o ajuizamento da ação, o novo prazo é de quatro anos.","teSitua":{"termos":[{"termo":"prescreve","significado":"perde-se o direito de punir pelo decurso do tempo."},{"termo":"infrações permanentes","significado":"condutas ilícitas que se prolongam no tempo."},{"termo":"inquérito civil","significado":"investigação feita pelo Ministério Público para apurar fatos antes de propor ação."}],"exemplo":"Um desvio de verbas ocorreu em março de 2020. O Ministério Público tem até março de 2028 para ajuizar a ação. Ajuizada em 2026, a prescrição se interrompe e recomeça a correr por quatro anos."}},{"id":"aut.administrativo_tj.lia.0009","subtopico":"administrativo_tj.improbidade.lia","tipo":"certo_errado","dificuldade":4,"enunciado":"Nos termos da Lei nº 8.429/1992, o Ministério Público poderá celebrar acordo de não persecução civil, desde que dele advenham, ao menos, o integral ressarcimento do dano e a reversão à pessoa jurídica lesada da vantagem indevida obtida, dependendo o acordo, entre outros requisitos, de homologação judicial, independentemente de ocorrer antes ou depois do ajuizamento da ação.","gabarito":"C","explicacao":"O art. 17-B exige, como resultados mínimos, o integral ressarcimento do dano e a reversão da vantagem indevida (I e II). O § 1º condiciona o acordo, cumulativamente, à oitiva do ente lesado, à aprovação pelo órgão do MP competente se anterior à ação, e à homologação judicial em qualquer caso. O acordo pode ser celebrado na investigação, no curso da ação ou na execução da sentença (§ 4º).","fonte":"Lei 8.429/1992, art. 17-B, caput, § 1º e § 4º","mastigado":"Certo. O Ministério Público pode fazer acordo com o investigado em vez de processá-lo, mas o acordo precisa garantir a devolução de todo o prejuízo e da vantagem indevida. E, antes ou depois de existir processo, o juiz tem de homologar.","teSitua":{"termos":[{"termo":"acordo de não persecução civil","significado":"acordo do Ministério Público com o investigado para encerrar ou evitar a ação de improbidade."},{"termo":"integral ressarcimento do dano","significado":"devolução completa do prejuízo causado."},{"termo":"homologação judicial","significado":"aprovação do acordo pelo juiz, que lhe dá validade."}],"exemplo":"Investigado por superfaturar compras, o gestor Tomás aceitou acordo com o Ministério Público: devolverá todo o prejuízo e o lucro indevido. O ente lesado foi ouvido e o acordo foi levado ao juiz, que o homologou."}},{"id":"aut.administrativo_tj.lia.0010","subtopico":"administrativo_tj.improbidade.lia","tipo":"multipla","dificuldade":4,"enunciado":"Em ação de improbidade administrativa, o Ministério Público pediu a indisponibilidade de bens do réu. Segundo a Lei nº 8.429/1992, é correto afirmar que","alternativas":{"A":"é vedada a decretação de indisponibilidade da quantia de até 40 salários mínimos depositados em caderneta de poupança, em outras aplicações financeiras ou em conta-corrente.","B":"a indisponibilidade pode recair sobre o valor da multa civil a ser eventualmente aplicada.","C":"o bem de família do réu pode sempre ser declarado indisponível.","D":"a urgência para decretar a medida sem ouvir o réu é presumida.","E":"o bloqueio de contas bancárias deve ter prioridade sobre os demais bens."},"gabarito":"A","explicacao":"O art. 16, § 13, veda a indisponibilidade de até 40 salários mínimos em poupança, outras aplicações ou conta-corrente. A medida não incide sobre valores de multa civil (§ 10); o bem de família só pode ser atingido se fruto de vantagem indevida do art. 9º (§ 14); a urgência não pode ser presumida (§ 4º); e o bloqueio de contas é a última opção (§ 11).","explicacoes":{"A":"Correta: art. 16, § 13.","B":"A indisponibilidade não incide sobre valores de multa civil (§ 10).","C":"O bem de família é protegido, salvo se fruto de vantagem indevida do art. 9º (§ 14).","D":"A urgência não pode ser presumida (§ 4º).","E":"Contas bancárias só são bloqueadas na falta de outros bens (§ 11)."},"fonte":"Lei 8.429/1992, art. 16, §§ 4º, 10, 11, 13 e 14","mastigado":"A resposta é a letra A. A lei protege uma reserva mínima do réu: até quarenta salários mínimos guardados na poupança ou em conta não podem ser bloqueados. O bloqueio serve só para garantir o ressarcimento do prejuízo, e não a multa.","teSitua":{"termos":[{"termo":"indisponibilidade de bens","significado":"bloqueio dos bens do réu, que não podem ser vendidos, para garantir o ressarcimento."},{"termo":"caderneta de poupança","significado":"aplicação bancária simples, com rendimento mensal."},{"termo":"multa civil","significado":"pena em dinheiro aplicada na ação de improbidade."},{"termo":"bem de família","significado":"imóvel residencial da família, protegido por lei contra penhora."}],"exemplo":"O juiz decretou a indisponibilidade dos bens do ex-secretário Abel para garantir o ressarcimento de um desvio. Na poupança dele havia o equivalente a 30 salários mínimos, que não pôde ser bloqueado. A casa onde mora com a família, comprada muito antes dos fatos, também ficou protegida."}},{"id":"aut.administrativo_tj.movimentacao.0001","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, a transferência do funcionário de um para outro cargo de provimento efetivo","alternativas":{"A":"será feita a pedido ou ex officio, atendidos a conveniência do serviço e os requisitos para o provimento do cargo.","B":"só poderá ser feita ex officio, no interesse da Administração.","C":"só poderá ser feita a pedido, vedada a transferência ex officio.","D":"dispensa os requisitos necessários ao provimento do novo cargo.","E":"depende sempre de novo concurso público de provas e títulos."},"gabarito":"A","explicacao":"O art. 27 prevê transferências a pedido ou ex officio, atendidos sempre a conveniência do serviço e os requisitos necessários ao provimento do cargo. O art. 21 prevê, para a transferência, provas de habilitação, e não concurso competitivo.","explicacoes":{"A":"Correta: art. 27.","B":"A lei admite também a transferência a pedido.","C":"A lei admite também a transferência ex officio.","D":"Os requisitos do cargo devem ser sempre atendidos.","E":"A transferência usa prova de habilitação (art. 21), não novo concurso."},"fonte":"Lei 10.261/1968, art. 27","mastigado":"A resposta é a letra A. A transferência pode partir do próprio servidor ou da Administração. Em qualquer caso, precisa servir ao serviço público e o servidor tem de cumprir os requisitos do novo cargo.","teSitua":{"termos":[{"termo":"provimento efetivo","significado":"forma de ocupar cargo permanente, próprio de concursados."},{"termo":"ex officio","significado":"por iniciativa da própria Administração, sem pedido do interessado."},{"termo":"conveniência do serviço","significado":"aquilo que é melhor para o funcionamento do serviço público."}],"exemplo":"Paula, funcionária efetiva, pediu transferência para outro cargo efetivo mais ligado à sua formação. A Administração só deferiu após verificar que ela cumpria os requisitos do novo cargo e que a mudança atendia ao interesse do serviço."}},{"id":"aut.administrativo_tj.movimentacao.0002","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto dos Funcionários Públicos Civis de SP, a transferência será feita para cargo do mesmo padrão de vencimento ou de igual remuneração, ressalvados os casos de transferência a pedido, em que o vencimento poderá ser inferior.","gabarito":"C","explicacao":"É a regra do art. 28. Na transferência ex officio, o padrão deve ser o mesmo ou a remuneração igual; somente quando o funcionário pede é que se admite cargo de vencimento inferior.","fonte":"Lei 10.261/1968, art. 28","mastigado":"Certo. Se a Administração transfere o servidor por conta própria, não pode reduzir o que ele ganha. Mas, se é o servidor quem pede, ele pode aceitar ir para um cargo que pague menos.","teSitua":{"termos":[{"termo":"padrão de vencimento","significado":"valor do cargo, definido pela referência e pelo grau."},{"termo":"transferência a pedido","significado":"mudança de cargo solicitada pelo próprio funcionário."}],"exemplo":"Renato quer muito trabalhar na área de biblioteca e pede transferência para um cargo que paga um pouco menos. Como o pedido partiu dele, a lei permite. Se fosse a Administração a transferi-lo por conta própria, o novo cargo teria de pagar o mesmo."}},{"id":"aut.administrativo_tj.movimentacao.0003","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Lei nº 10.261/1968, a reintegração é","alternativas":{"A":"o reingresso no serviço público decorrente de decisão judicial passada em julgado, com ressarcimento de prejuízos resultantes do afastamento.","B":"o reingresso do aposentado no serviço público, a pedido ou ex officio.","C":"o reingresso do funcionário em disponibilidade.","D":"o retorno do ex-funcionário demitido, sem ressarcimento de prejuízos.","E":"a investidura em cargo mais compatível com a capacidade do funcionário."},"gabarito":"A","explicacao":"Reintegração é o reingresso decorrente de decisão judicial passada em julgado, com ressarcimento dos prejuízos do afastamento (art. 30). As demais alternativas descrevem reversão (art. 35), aproveitamento (art. 37), readmissão (art. 39) e readaptação (art. 41).","explicacoes":{"A":"Correta: art. 30.","B":"Descreve a reversão (art. 35).","C":"Descreve o aproveitamento (art. 37).","D":"Descreve a readmissão (art. 39).","E":"Descreve a readaptação (art. 41)."},"fonte":"Lei 10.261/1968, art. 30","mastigado":"A resposta é a letra A. Reintegração é a volta de quem foi afastado injustamente e ganhou na Justiça, com decisão definitiva. Por isso ele recebe tudo o que perdeu no período. Cada alternativa errada descreve outra forma de reingresso.","teSitua":{"termos":[{"termo":"reintegração","significado":"volta do servidor ao cargo por ordem judicial definitiva, com pagamento do que deixou de receber."},{"termo":"passada em julgado","significado":"decisão judicial definitiva, contra a qual não cabe mais recurso."},{"termo":"ressarcimento de prejuízos","significado":"pagamento dos valores que o servidor perdeu enquanto esteve afastado."},{"termo":"disponibilidade","significado":"situação do servidor estável que fica sem exercer o cargo, recebendo proporcionalmente, por extinção ou desnecessidade do cargo."}],"exemplo":"Edson foi demitido, mas provou na Justiça que a demissão foi ilegal. Com a decisão definitiva, ele volta ao cargo e recebe os salários do período em que ficou afastado. Isso é reintegração."}},{"id":"aut.administrativo_tj.movimentacao.0004","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":3,"enunciado":"Determinada a reintegração de um funcionário por decisão judicial, verificou-se que seu antigo cargo estava ocupado por outro servidor, que antes ocupava outro cargo. Nos termos da Lei nº 10.261/1968, esse ocupante","alternativas":{"A":"será reconduzido ao cargo que ocupava antes, sem direito a indenização.","B":"permanecerá no cargo, e o reintegrado ficará em disponibilidade.","C":"será exonerado, com direito a indenização.","D":"será posto em disponibilidade remunerada.","E":"dividirá as atribuições do cargo com o reintegrado."},"gabarito":"A","explicacao":"Pelo art. 31, § 1º, se o cargo estiver preenchido, o seu ocupante será exonerado ou, se ocupava outro cargo, a este será reconduzido, sem direito a indenização.","explicacoes":{"A":"Correta: art. 31, § 1º.","B":"A disponibilidade do reintegrado só ocorre se o cargo tiver sido extinto e não houver cargo equivalente (§ 2º).","C":"A exoneração ocorre quando o ocupante não tinha outro cargo, e sem indenização.","D":"A lei não prevê disponibilidade para o ocupante.","E":"Não há divisão de atribuições."},"fonte":"Lei 10.261/1968, art. 31, § 1º","mastigado":"A resposta é a letra A. O dono do cargo volta, e quem estava no lugar dele sai. Se esse ocupante tinha outro cargo antes, volta para ele; se não tinha, é exonerado. Em nenhum caso recebe indenização.","teSitua":{"termos":[{"termo":"reintegração","significado":"volta do servidor ao cargo por ordem judicial definitiva."},{"termo":"reconduzido","significado":"levado de volta ao cargo que ocupava anteriormente."},{"termo":"indenização","significado":"pagamento para compensar um prejuízo."}],"exemplo":"Sueli foi reintegrada por decisão judicial. Seu cargo estava com Ricardo, que antes ocupava outro cargo no Estado. Ricardo volta ao cargo antigo, sem receber indenização, e Sueli reassume o seu."}},{"id":"aut.administrativo_tj.movimentacao.0005","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Conforme o Estatuto dos Funcionários Públicos Civis de SP, se o cargo do funcionário a ser reintegrado houver sido extinto, a reintegração se fará em cargo equivalente, respeitada a habilitação profissional, ou, não sendo possível, ficará o reintegrado em disponibilidade no cargo que exercia.","gabarito":"C","explicacao":"É o que dispõe o art. 31, § 2º. Pelo caput, a reintegração se faz no cargo anteriormente ocupado e, se este tiver sido transformado, no cargo resultante.","fonte":"Lei 10.261/1968, art. 31, § 2º","mastigado":"Certo. Se o cargo antigo deixou de existir, o servidor reintegrado vai para um cargo parecido, compatível com sua formação. Se não houver, ele fica em disponibilidade, aguardando, vinculado ao cargo que tinha.","teSitua":{"termos":[{"termo":"extinto","significado":"eliminado por lei, deixando de existir."},{"termo":"habilitação profissional","significado":"formação e qualificação que a pessoa tem para exercer certa profissão."},{"termo":"disponibilidade","significado":"situação do servidor que fica sem exercer cargo, aguardando aproveitamento."}],"exemplo":"Otávio venceu ação contra sua demissão, mas o cargo dele foi extinto. A Administração procura um cargo equivalente compatível com a formação dele. Não havendo, Otávio fica em disponibilidade até poder ser aproveitado."}},{"id":"aut.administrativo_tj.movimentacao.0006","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, transitada em julgado a sentença, será expedido o decreto de reintegração no prazo máximo de","alternativas":{"A":"30 (trinta) dias.","B":"8 (oito) dias.","C":"60 (sessenta) dias.","D":"90 (noventa) dias.","E":"120 (cento e vinte) dias."},"gabarito":"A","explicacao":"O art. 32 fixa o prazo máximo de 30 dias, contados do trânsito em julgado, para expedição do decreto de reintegração.","explicacoes":{"A":"Correta: art. 32.","B":"Oito dias é prazo de outros institutos, como o período de trânsito (art. 61).","C":"Não há prazo de 60 dias para o decreto de reintegração.","D":"Noventa dias não é o prazo do art. 32.","E":"Cento e vinte dias aparece na suspensão do prazo de posse (art. 53, I)."},"fonte":"Lei 10.261/1968, art. 32","mastigado":"A resposta é a letra A. Depois que a decisão da Justiça fica definitiva, a Administração tem no máximo trinta dias para publicar o ato que devolve o servidor ao cargo.","teSitua":{"termos":[{"termo":"transitada em julgado","significado":"decisão judicial que se tornou definitiva, sem possibilidade de recurso."},{"termo":"decreto de reintegração","significado":"ato oficial que formaliza a volta do servidor ao cargo."}],"exemplo":"A ação de Vera transitou em julgado no dia 1º de março. A partir daí, o Estado tem até trinta dias para expedir o decreto que a reintegra ao cargo de onde foi afastada."}},{"id":"aut.administrativo_tj.movimentacao.0007","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, acesso é a elevação do funcionário, dentro do respectivo quadro, a cargo da mesma natureza de trabalho, de maior grau de responsabilidade e maior complexidade de atribuições, sendo de 3 (três) anos de efetivo exercício o interstício para concorrer a ele.","gabarito":"C","explicacao":"O art. 33 define acesso nesses termos, obedecidos o interstício na classe e as exigências de regulamento, e o art. 34 fixa o interstício em 3 anos de efetivo exercício. O acesso é feito mediante aferição do mérito (art. 33, § 2º).","fonte":"Lei 10.261/1968, arts. 33 e 34","mastigado":"Certo. Acesso é subir para um cargo do mesmo tipo de trabalho, porém mais complexo e com mais responsabilidade. Para concorrer, o servidor precisa de pelo menos três anos de exercício efetivo.","teSitua":{"termos":[{"termo":"acesso","significado":"subida do funcionário para cargo mais complexo da mesma natureza de trabalho, por mérito."},{"termo":"quadro","significado":"conjunto de carreiras e cargos isolados de um órgão."},{"termo":"interstício","significado":"tempo mínimo que o servidor precisa ficar num degrau antes de concorrer ao seguinte."}],"exemplo":"Marina está há quatro anos no cargo. Abre-se seleção de acesso para um cargo de maior responsabilidade da mesma área. Como já cumpriu o interstício de três anos, ela pode concorrer, e será avaliada pelo mérito."}},{"id":"aut.administrativo_tj.movimentacao.0008","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com o Estatuto paulista, serão reservados para acesso","alternativas":{"A":"os cargos cujas atribuições exijam experiência prévia do exercício de outro cargo.","B":"todos os cargos de provimento em comissão.","C":"os cargos isolados de qualquer natureza.","D":"os cargos vagos que não tiverem candidato aprovado em concurso.","E":"os cargos de padrão inferior ao do funcionário."},"gabarito":"A","explicacao":"O art. 33, § 1º, reserva para acesso os cargos cujas atribuições exijam experiência prévia do exercício de outro cargo. O § 2º manda que o acesso seja feito por aferição do mérito entre titulares de cargos que proporcionem essa experiência.","explicacoes":{"A":"Correta: art. 33, § 1º.","B":"Cargos em comissão são de livre nomeação, não de acesso.","C":"O acesso é para cargo da mesma natureza, de maior complexidade, e não para cargos isolados em geral.","D":"A falta de aprovados leva à regra do art. 12, não ao acesso.","E":"O acesso é elevação, logo para cargo de maior responsabilidade."},"fonte":"Lei 10.261/1968, art. 33, § 1º","mastigado":"A resposta é a letra A. Alguns cargos exigem que a pessoa já tenha a prática de outro cargo antes. Esses ficam reservados para o acesso, isto é, para quem já está dentro e acumulou essa experiência.","teSitua":{"termos":[{"termo":"acesso","significado":"subida do funcionário para cargo mais complexo da mesma natureza, por mérito."},{"termo":"experiência prévia","significado":"prática adquirida antes, no exercício de outro cargo."},{"termo":"provimento em comissão","significado":"forma de ocupar cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"O cargo de supervisor exige quem já tenha trabalhado como escrevente. Por isso ele é reservado para acesso: apenas escreventes com a experiência exigida, como Débora, podem concorrer, e o melhor mérito vence."}},{"id":"aut.administrativo_tj.movimentacao.0009","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, reversão é o ato pelo qual","alternativas":{"A":"o aposentado reingressa no serviço público, a pedido ou ex officio.","B":"o funcionário em disponibilidade reingressa no serviço público.","C":"o ex-funcionário demitido reingressa no serviço público.","D":"o funcionário volta ao cargo por decisão judicial.","E":"o funcionário é removido para outra repartição."},"gabarito":"A","explicacao":"Reversão é o reingresso do aposentado, a pedido ou ex officio (art. 35). As outras alternativas tratam de aproveitamento (art. 37), readmissão (art. 39), reintegração (art. 30) e remoção (art. 43).","explicacoes":{"A":"Correta: art. 35, caput.","B":"É o aproveitamento (art. 37).","C":"É a readmissão (art. 39).","D":"É a reintegração (art. 30).","E":"É a remoção (art. 43)."},"fonte":"Lei 10.261/1968, art. 35, caput","mastigado":"A resposta é a letra A. Reversão é a volta de quem já estava aposentado. Para não confundir: o em disponibilidade volta por aproveitamento; o demitido, por readmissão; e quem ganhou na Justiça, por reintegração.","teSitua":{"termos":[{"termo":"reversão","significado":"volta do aposentado à atividade no serviço público."},{"termo":"ex officio","significado":"por iniciativa da própria Administração, sem pedido do interessado."},{"termo":"disponibilidade","significado":"situação do servidor que fica sem exercer cargo, aguardando aproveitamento."}],"exemplo":"Sérgio se aposentou por invalidez, mas se recuperou totalmente. A Administração determinou sua volta ao trabalho. Esse retorno do aposentado à atividade é a reversão."}},{"id":"aut.administrativo_tj.movimentacao.0010","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":4,"enunciado":"A reversão ex officio será feita quando insubsistentes as razões que determinaram a aposentadoria por invalidez, sendo permitido, nesse caso, o reingresso mesmo do aposentado que contar mais de 58 (cinquenta e oito) anos de idade.","gabarito":"C","explicacao":"O art. 35, § 1º, prevê a reversão ex officio quando cessam as razões da aposentadoria por invalidez. O § 2º proíbe a reversão de quem tem mais de 58 anos, mas o § 3º permite, na reversão ex officio, o reingresso além desse limite.","fonte":"Lei 10.261/1968, art. 35, §§ 1º a 3º","mastigado":"Certo. Se o motivo da aposentadoria por invalidez desaparece, a Administração pode chamar o servidor de volta. O limite de 58 anos vale para a volta a pedido; quando é a Administração que determina, a idade não impede.","teSitua":{"termos":[{"termo":"reversão ex officio","significado":"volta do aposentado determinada pela própria Administração."},{"termo":"insubsistentes","significado":"que deixaram de existir; sem fundamento."},{"termo":"aposentadoria por invalidez","significado":"aposentadoria concedida por incapacidade para o trabalho."}],"exemplo":"Teodoro, de 60 anos, aposentou-se por invalidez, mas a perícia constatou sua plena recuperação. A Administração determinou a reversão ex officio. Mesmo passando de 58 anos, ele deve voltar, porque o limite de idade não vale nesse caso."}},{"id":"aut.administrativo_tj.movimentacao.0011","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":4,"enunciado":"Um aposentado de 55 anos requereu sua reversão à atividade. Segundo a Lei nº 10.261/1968, essa reversão a pedido","alternativas":{"A":"será feita a critério da Administração e dependerá, também, da existência de cargo vago que deva ser provido mediante promoção por merecimento.","B":"é direito subjetivo do aposentado, que deve ser atendido em 30 dias.","C":"independe de inspeção médica, por ter sido requerida pelo próprio interessado.","D":"é vedada, pois somente se admite reversão ex officio.","E":"dependerá de novo concurso público."},"gabarito":"A","explicacao":"O art. 36, § 2º, diz que a reversão a pedido é feita a critério da Administração e depende da existência de cargo vago que deva ser provido por promoção por merecimento. Em qualquer caso, exige-se inspeção médica que comprove a capacidade (art. 35, § 4º).","explicacoes":{"A":"Correta: art. 36, § 2º.","B":"Não é direito subjetivo; fica a critério da Administração.","C":"A inspeção médica é sempre exigida (art. 35, § 4º).","D":"A reversão a pedido é admitida (art. 35, caput).","E":"Não há exigência de novo concurso."},"fonte":"Lei 10.261/1968, art. 36, § 2º; art. 35, § 4º","mastigado":"A resposta é a letra A. O aposentado pode pedir para voltar, mas a Administração decide se aceita. Além disso, precisa haver uma vaga do tipo que seria preenchida por promoção por merecimento, e ele deve passar no exame médico.","teSitua":{"termos":[{"termo":"reversão a pedido","significado":"volta do aposentado à atividade solicitada por ele mesmo."},{"termo":"promoção por merecimento","significado":"avanço na carreira com base na avaliação do desempenho do servidor."},{"termo":"direito subjetivo","significado":"direito que a pessoa pode exigir, sem depender da vontade da Administração."}],"exemplo":"Cláudio, aposentado aos 55 anos, pede para voltar. A Administração avalia a conveniência, verifica se há cargo vago do tipo exigido e o encaminha à perícia médica. Só se tudo estiver em ordem a reversão é deferida."}},{"id":"aut.administrativo_tj.movimentacao.0012","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto paulista, a reversão far-se-á sempre em cargo diferente do anteriormente ocupado, ainda que de padrão superior.","gabarito":"E","explicacao":"A regra é a reversão no mesmo cargo (art. 36, caput). Só em casos especiais, a juízo do Governo, admite-se outro cargo, e de igual padrão de vencimentos, respeitada a habilitação profissional (§ 1º).","fonte":"Lei 10.261/1968, art. 36, caput e § 1º","mastigado":"Errado. O aposentado volta, como regra, para o mesmo cargo que tinha. Excepcionalmente pode ir para outro, mas com o mesmo padrão de vencimento, nunca para um cargo que pague mais.","teSitua":{"termos":[{"termo":"reversão","significado":"volta do aposentado à atividade."},{"termo":"padrão superior","significado":"nível de vencimento mais alto que o do cargo anterior."}],"exemplo":"Lia aposentou-se como oficial administrativa e foi revertida. Ela retorna ao mesmo cargo. Só em caso especial poderia ir para outro cargo, e ainda assim de igual padrão, nunca para um cargo de chefia mais bem pago."}},{"id":"aut.administrativo_tj.movimentacao.0013","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com a Lei nº 10.261/1968, o aproveitamento do funcionário em disponibilidade","alternativas":{"A":"dar-se-á, tanto quanto possível, em cargo de natureza e padrão correspondentes ao que ocupava, não podendo ser feito em cargo de padrão superior.","B":"é facultativo e depende de pedido do funcionário.","C":"poderá ser feito em cargo de padrão superior, se houver vaga.","D":"dispensa inspeção médica.","E":"só pode ocorrer em cargo de provimento em comissão."},"gabarito":"A","explicacao":"O aproveitamento é obrigatório (art. 38, caput) e se dá, tanto quanto possível, em cargo de natureza e padrão correspondentes, nunca em cargo de padrão superior (§ 1º). Exige inspeção médica (§ 3º).","explicacoes":{"A":"Correta: art. 38, § 1º.","B":"O art. 38 fala em aproveitamento obrigatório.","C":"É vedado o aproveitamento em cargo de padrão superior.","D":"A inspeção médica é exigida em todos os casos (§ 3º).","E":"O aproveitamento em comissão é possível (§ 7º), mas não é o único caminho."},"fonte":"Lei 10.261/1968, art. 38, caput e § 1º","mastigado":"A resposta é a letra A. Quem está em disponibilidade tem de ser aproveitado quando surgir vaga. Ele vai para um cargo parecido com o que tinha, mas nunca para um cargo mais bem pago, porque isso seria uma promoção disfarçada.","teSitua":{"termos":[{"termo":"aproveitamento","significado":"volta ao serviço do funcionário que estava em disponibilidade."},{"termo":"disponibilidade","significado":"situação do servidor que fica sem exercer cargo, aguardando nova vaga."},{"termo":"padrão","significado":"valor do cargo, formado pela referência e pelo grau."}],"exemplo":"O cargo de Célia foi extinto e ela ficou em disponibilidade. Surgiu vaga em cargo de natureza semelhante e mesmo padrão. A Administração deve aproveitá-la ali, e não poderia colocá-la num cargo de padrão maior."}},{"id":"aut.administrativo_tj.movimentacao.0014","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Se o aproveitamento se der em cargo de padrão inferior ao provento da disponibilidade, terá o funcionário direito à diferença.","gabarito":"C","explicacao":"É o que diz o art. 38, § 2º. O funcionário não pode ter perda financeira ao ser aproveitado em cargo de padrão inferior.","fonte":"Lei 10.261/1968, art. 38, § 2º","mastigado":"Certo. Se o servidor volta num cargo que paga menos do que ele recebia em disponibilidade, o Estado paga a diferença. Assim ele não perde dinheiro por ter sido aproveitado.","teSitua":{"termos":[{"termo":"aproveitamento","significado":"volta ao serviço do funcionário que estava em disponibilidade."},{"termo":"provento da disponibilidade","significado":"valor que o servidor recebe enquanto está em disponibilidade."}],"exemplo":"Murilo recebia R$ 5.000 em disponibilidade e foi aproveitado num cargo de padrão que paga R$ 4.600. Ele tem direito a receber os R$ 400 de diferença, para não ter perda."}},{"id":"aut.administrativo_tj.movimentacao.0015","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":3,"enunciado":"Conforme a Lei nº 10.261/1968, o funcionário em disponibilidade que for julgado incapaz para o serviço público, em inspeção médica,","alternativas":{"A":"será aposentado no cargo anteriormente ocupado.","B":"será exonerado de ofício.","C":"terá a disponibilidade cassada.","D":"será readaptado em cargo de padrão inferior.","E":"aguardará nova inspeção, sem prazo para decisão."},"gabarito":"A","explicacao":"O art. 38, § 6º, determina a aposentadoria no cargo anteriormente ocupado do funcionário em disponibilidade julgado incapaz em inspeção médica. A cassação da disponibilidade ocorre quando o aproveitado não toma posse e não entra em exercício no prazo (§ 5º).","explicacoes":{"A":"Correta: art. 38, § 6º.","B":"A incapacidade não leva à exoneração.","C":"A cassação é para quem não toma posse e não entra em exercício (§ 5º).","D":"A readaptação é instituto diverso (art. 41).","E":"A lei admite nova inspeção após 90 dias apenas quando o laudo não é favorável (§ 4º), mas para o incapaz prevê aposentadoria."},"fonte":"Lei 10.261/1968, art. 38, § 6º","mastigado":"A resposta é a letra A. Se o servidor em disponibilidade não tem mais condição de saúde para trabalhar, ele não fica esperando para sempre: é aposentado no cargo que tinha antes.","teSitua":{"termos":[{"termo":"disponibilidade","significado":"situação do servidor que fica sem exercer cargo, aguardando aproveitamento."},{"termo":"inspeção médica","significado":"exame feito por médico oficial para verificar a saúde do servidor."},{"termo":"cassada","significado":"anulada como punição, retirando o benefício."}],"exemplo":"Nélson estava em disponibilidade e foi chamado para aproveitamento. Na perícia, os médicos concluíram que ele está incapaz para o serviço público. Em vez de ser aproveitado, Nélson é aposentado no cargo que ocupava."}},{"id":"aut.administrativo_tj.movimentacao.0016","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto, readmissão é o ato pelo qual o ex-funcionário, demitido ou exonerado, reingressa no serviço público com ressarcimento dos prejuízos do período em que esteve afastado.","gabarito":"E","explicacao":"A readmissão ocorre sem direito a ressarcimento de prejuízos, assegurada apenas a contagem do tempo de serviço em cargos anteriores para efeito de aposentadoria e disponibilidade (art. 39). O ressarcimento é próprio da reintegração (art. 30).","fonte":"Lei 10.261/1968, art. 39, caput","mastigado":"Errado. Quem é readmitido volta sem receber nada pelo tempo em que ficou fora. Só aproveita o tempo antigo para aposentadoria e disponibilidade. Receber pelos prejuízos é coisa da reintegração, que vem de decisão judicial.","teSitua":{"termos":[{"termo":"readmissão","significado":"volta ao serviço de quem foi demitido ou exonerado, sem receber pelo tempo afastado."},{"termo":"ressarcimento dos prejuízos","significado":"pagamento do que a pessoa deixou de receber."}],"exemplo":"Valéria pediu exoneração há alguns anos e agora foi readmitida. Ela não recebe salários pelo período em que ficou fora, mas o tempo que trabalhou antes conta para sua aposentadoria."}},{"id":"aut.administrativo_tj.movimentacao.0017","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":4,"enunciado":"Um ex-funcionário foi demitido a bem do serviço público e pretende ser readmitido. Nos termos da Lei nº 10.261/1968,","alternativas":{"A":"a readmissão depende de reexame do processo administrativo e não pode ser decretada antes de decorridos 5 anos do ato demissório.","B":"a readmissão é vedada para sempre.","C":"basta o decurso de 2 anos do ato demissório.","D":"a readmissão independe de reexame do processo, bastando o pedido.","E":"a readmissão depende apenas de inspeção médica favorável."},"gabarito":"A","explicacao":"A readmissão do demitido exige reexame do processo administrativo que demonstre não haver inconveniente para o serviço (art. 39, § 1º). Se a demissão foi a bem do serviço público, só pode ser decretada após 5 anos do ato demissório (§ 2º).","explicacoes":{"A":"Correta: art. 39, §§ 1º e 2º.","B":"A lei não proíbe para sempre; exige 5 anos.","C":"O prazo é de 5 anos, não de 2.","D":"O reexame do processo é obrigatório para o demitido.","E":"A lei exige reexame do processo e, no caso, o prazo de 5 anos."},"fonte":"Lei 10.261/1968, art. 39, §§ 1º e 2º","mastigado":"A resposta é a letra A. Quem foi demitido só volta depois que a Administração reexamina o processo e conclui que não há problema. Se a demissão foi a bem do serviço público, a mais grave, é preciso esperar ainda cinco anos.","teSitua":{"termos":[{"termo":"demitido a bem do serviço público","significado":"punido com a forma mais grave de demissão, por falta muito séria."},{"termo":"ato demissório","significado":"ato oficial que aplicou a pena de demissão."},{"termo":"reexame do processo","significado":"nova análise do processo disciplinar que levou à demissão."}],"exemplo":"Álvaro foi demitido a bem do serviço público em 2020. Em 2023 pediu readmissão, mas o pedido não pode ser atendido, porque ainda não se passaram cinco anos. Só a partir de 2025, e após reexame do processo, poderá ser analisado."}},{"id":"aut.administrativo_tj.movimentacao.0018","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, a readaptação","alternativas":{"A":"é a investidura em cargo mais compatível com a capacidade do funcionário, depende sempre de inspeção médica e será feita mediante transferência.","B":"acarretará aumento de vencimento, como compensação ao funcionário.","C":"dispensa inspeção médica quando requerida pelo funcionário.","D":"será feita mediante remoção para outra repartição.","E":"acarretará redução proporcional do vencimento."},"gabarito":"A","explicacao":"Readaptação é a investidura em cargo mais compatível com a capacidade do funcionário e depende sempre de inspeção médica (art. 41). Não acarreta diminuição nem aumento de vencimento e é feita mediante transferência (art. 42).","explicacoes":{"A":"Correta: arts. 41 e 42.","B":"A readaptação não gera aumento (art. 42).","C":"A inspeção médica é sempre exigida (art. 41).","D":"Ela se faz por transferência, não por remoção (art. 42).","E":"A readaptação não gera diminuição (art. 42)."},"fonte":"Lei 10.261/1968, arts. 41 e 42","mastigado":"A resposta é a letra A. Se a saúde do servidor mudou e ele não consegue mais fazer o trabalho de antes, ele passa para um cargo compatível, sempre após exame médico. O salário não sobe nem desce, e a mudança é feita por transferência.","teSitua":{"termos":[{"termo":"readaptação","significado":"mudança do servidor para cargo compatível com sua capacidade, após exame médico."},{"termo":"investidura","significado":"ato de colocar a pessoa em um cargo."},{"termo":"inspeção médica","significado":"exame feito por médico oficial para avaliar a saúde do servidor."}],"exemplo":"Rogério teve um problema na coluna e não pode mais carregar caixas de processos. Após perícia, é transferido para um cargo compatível com sua condição, mantendo o mesmo vencimento. Isso é readaptação."}},{"id":"aut.administrativo_tj.movimentacao.0019","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com o Estatuto paulista, a remoção, a pedido ou ex officio, só poderá ser feita de uma para outra repartição da mesma Secretaria ou de um para outro órgão da mesma repartição, respeitada a lotação de cada repartição; a remoção por permuta exige requerimento de ambos os interessados e anuência dos respectivos chefes.","gabarito":"C","explicacao":"O art. 43 limita a remoção a esses dois casos e exige respeito à lotação (parágrafo único). O art. 44 trata da permuta: requerimento de ambos os interessados, com anuência dos respectivos chefes.","fonte":"Lei 10.261/1968, arts. 43 e 44","mastigado":"Certo. Remoção é mudar de lugar de trabalho sem mudar de cargo, dentro da mesma Secretaria ou da mesma repartição, e sempre respeitando o número de vagas de cada local. Na troca entre dois servidores, os dois pedem e os chefes concordam.","teSitua":{"termos":[{"termo":"remoção","significado":"mudança do local de exercício do servidor, sem mudança de cargo."},{"termo":"lotação","significado":"número de funcionários que devem trabalhar em cada repartição."},{"termo":"permuta","significado":"troca de lugar entre dois servidores, a pedido de ambos."},{"termo":"anuência","significado":"concordância ou autorização dada pelo chefe."}],"exemplo":"Ingrid trabalha no fórum de Osasco e Leandro no de Barueri. Os dois querem trocar de lugar. Eles fazem requerimento conjunto, os chefes concordam e a remoção por permuta é feita, sem alterar a lotação de cada unidade."}},{"id":"aut.administrativo_tj.movimentacao.0020","subtopico":"administrativo_tj.estatuto_sp.movimentacao","tipo":"multipla","dificuldade":3,"enunciado":"Em ano de eleições municipais, a Administração pretende remover ex officio um funcionário para repartição situada fora da localidade de sua residência. Segundo a Lei nº 10.261/1968, essa remoção é vedada no período de","alternativas":{"A":"6 meses antes até 3 meses após a data das eleições.","B":"3 meses antes até 6 meses após a data das eleições.","C":"6 meses antes até a data das eleições, apenas nas eleições federais.","D":"3 meses antes até 3 meses após a data das eleições.","E":"1 ano antes até a posse dos eleitos."},"gabarito":"A","explicacao":"O art. 45 proíbe remover ou transferir ex officio o funcionário para cargo fora da localidade de sua residência no período de 6 meses antes até 3 meses após as eleições. O parágrafo único estende a proibição a eleições federais, estaduais ou municipais.","explicacoes":{"A":"Correta: art. 45 e parágrafo único.","B":"Os prazos estão invertidos.","C":"A vedação vale também para eleições estaduais e municipais e se estende até 3 meses depois.","D":"O período anterior é de 6 meses, não de 3.","E":"Não há esse período na lei."},"fonte":"Lei 10.261/1968, art. 45 e parágrafo único","mastigado":"A resposta é a letra A. Perto das eleições, a Administração não pode mandar o servidor para outra cidade contra a vontade dele: a proibição vai de seis meses antes até três meses depois, em qualquer eleição. Isso evita perseguição política.","teSitua":{"termos":[{"termo":"ex officio","significado":"por iniciativa da Administração, sem pedido do servidor."},{"termo":"localidade de sua residência","significado":"cidade onde o servidor mora."}],"exemplo":"As eleições municipais são em outubro. Em maio, o chefe de Laura quer removê-la, contra a vontade dela, para outra cidade. Isso é proibido: o período vedado começou em abril e só termina em janeiro do ano seguinte."}},{"id":"aut.administrativo_tj.penalidades.0001","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, são penas disciplinares, entre outras,","alternativas":{"A":"repreensão, suspensão, multa e cassação de aposentadoria ou disponibilidade.","B":"advertência verbal, suspensão e destituição de função.","C":"repreensão, prisão administrativa e demissão.","D":"suspensão, multa e remoção compulsória.","E":"advertência, rebaixamento de cargo e demissão."},"gabarito":"A","explicacao":"O art. 251 enumera seis penas: repreensão, suspensão, multa, demissão, demissão a bem do serviço público e cassação de aposentadoria ou disponibilidade. A antiga prisão administrativa não existe mais no Estatuto, e remoção ou rebaixamento não são penas.","explicacoes":{"A":"Correta: art. 251.","B":"Advertência verbal e destituição de função não estão no art. 251.","C":"A prisão administrativa não é pena do art. 251 e não existe mais no Estatuto (art. 264 na redação atual).","D":"Remoção não é pena disciplinar.","E":"Advertência e rebaixamento não constam do art. 251."},"fonte":"Lei 10.261/1968, art. 251","mastigado":"A resposta é a letra A. O Estatuto tem seis punições: repreensão, suspensão, multa, demissão, demissão a bem do serviço público e cassação de aposentadoria ou disponibilidade. Nomes como advertência ou rebaixamento são de outras leis.","teSitua":{"termos":[{"termo":"repreensão","significado":"punição mais leve, aplicada por escrito, por indisciplina ou descumprimento de dever."},{"termo":"cassação de aposentadoria","significado":"anulação da aposentadoria como punição por falta grave cometida na ativa."},{"termo":"disponibilidade","significado":"situação do servidor que fica sem exercer cargo, recebendo proventos, aguardando aproveitamento."}],"exemplo":"Num curso de preparação, a professora pediu que Rita listasse as penas do Estatuto paulista. Ela citou repreensão, suspensão, multa, demissão, demissão a bem do serviço público e cassação. Acertou todas."}},{"id":"aut.administrativo_tj.penalidades.0002","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto, a pena de repreensão será aplicada por escrito, nos casos de indisciplina ou falta de cumprimento dos deveres.","gabarito":"C","explicacao":"É a redação do art. 253. Na aplicação de qualquer pena, consideram-se a natureza e a gravidade da infração e os danos ao serviço público (art. 252).","fonte":"Lei 10.261/1968, art. 253","mastigado":"Certo. A repreensão é a punição mais leve. Ela sempre é dada por escrito, para casos de indisciplina ou de descumprimento de algum dever do servidor.","teSitua":{"termos":[{"termo":"repreensão","significado":"punição mais leve, registrada por escrito na vida funcional do servidor."},{"termo":"indisciplina","significado":"desobediência às regras e à hierarquia do serviço."}],"exemplo":"O escrevente Breno chegou atrasado várias vezes e tratou mal um colega. Após o procedimento cabível, recebeu repreensão por escrito, anotada em seu assentamento individual."}},{"id":"aut.administrativo_tj.penalidades.0003","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Lei nº 10.261/1968, a pena de suspensão","alternativas":{"A":"não excederá de 90 dias e será aplicada em caso de falta grave ou de reincidência.","B":"não excederá de 30 dias e será aplicada em caso de qualquer falta leve.","C":"não excederá de 180 dias e só se aplica a faltas gravíssimas.","D":"não tem limite máximo, ficando a critério da autoridade.","E":"não excederá de 60 dias e só se aplica em caso de reincidência."},"gabarito":"A","explicacao":"O art. 254 fixa o limite de 90 dias e prevê a suspensão para falta grave ou reincidência. O funcionário suspenso perde todas as vantagens e direitos do exercício do cargo (§ 1º).","explicacoes":{"A":"Correta: art. 254, caput.","B":"O limite é de 90 dias.","C":"O limite é de 90 dias, e a pena cabe para falta grave ou reincidência.","D":"Há limite máximo de 90 dias.","E":"O limite é de 90 dias, e cabe também para falta grave."},"fonte":"Lei 10.261/1968, art. 254, caput","mastigado":"A resposta é a letra A. A suspensão é para falta grave ou para quem repete a falta. Ela tem limite: no máximo noventa dias. Durante a suspensão, o servidor perde as vantagens ligadas ao exercício do cargo.","teSitua":{"termos":[{"termo":"suspensão","significado":"punição que afasta o servidor do serviço por certo tempo, sem as vantagens do cargo."},{"termo":"reincidência","significado":"repetição de falta depois de já ter sido punido."}],"exemplo":"Depois de levar repreensão, Fernando voltou a desrespeitar as regras do cartório. Pela reincidência, recebeu suspensão de quinze dias, dentro do limite máximo de noventa dias previsto no Estatuto."}},{"id":"aut.administrativo_tj.penalidades.0004","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":3,"enunciado":"A autoridade que aplicar a pena de suspensão poderá convertê-la em multa, na base de 50% por dia de vencimento ou remuneração, sendo o funcionário, nesse caso, obrigado a permanecer em serviço.","gabarito":"C","explicacao":"É a regra do art. 254, § 2º. A conversão permite que o serviço não fique desfalcado, mantendo o caráter punitivo pela perda de metade do vencimento diário.","fonte":"Lei 10.261/1968, art. 254, § 2º","mastigado":"Certo. Em vez de afastar o servidor, a autoridade pode trocar a suspensão por multa: ele continua trabalhando, mas perde metade do que ganharia em cada dia de suspensão. Assim o serviço não fica parado.","teSitua":{"termos":[{"termo":"converter","significado":"trocar uma pena por outra."},{"termo":"multa","significado":"punição em dinheiro, descontada da remuneração."}],"exemplo":"A escrevente Lia recebeu dez dias de suspensão, mas o cartório estava sem gente. O juiz converteu a pena em multa: ela continuou trabalhando e perdeu metade do vencimento de cada um daqueles dez dias."}},{"id":"aut.administrativo_tj.penalidades.0005","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":4,"enunciado":"Na redação vigente da Lei nº 10.261/1968, considera-se inassiduidade, punível com demissão, a ausência ao serviço, sem causa justificável,","alternativas":{"A":"por mais de 15 dias consecutivos, ou por mais de 20 dias úteis intercalados, durante 1 ano.","B":"por mais de 30 dias consecutivos.","C":"por mais de 45 dias interpolados, durante 1 ano.","D":"por mais de 10 dias consecutivos ou 30 intercalados.","E":"por mais de 60 dias intercalados, durante 2 anos."},"gabarito":"A","explicacao":"A LC 1.361/2021 substituiu o abandono de cargo e as faltas interpoladas pela inassiduidade (art. 256, V), definida no § 1º como ausência sem causa justificável por mais de 15 dias consecutivos ou mais de 20 dias úteis intercalados, durante 1 ano.","explicacoes":{"A":"Correta: art. 256, § 1º, redação da LC 1.361/2021.","B":"Trinta dias consecutivos era o antigo abandono de cargo, revogado.","C":"Quarenta e cinco dias interpolados era a redação antiga, revogada.","D":"Os números estão trocados.","E":"Não há essa previsão."},"fonte":"Lei 10.261/1968, art. 256, V e § 1º (redação da LC 1.361/2021)","mastigado":"A resposta é a letra A. Faltar sem justificativa mais de quinze dias seguidos, ou mais de vinte dias úteis espalhados no mesmo ano, é inassiduidade e leva à demissão. Os prazos antigos de trinta e quarenta e cinco dias não valem mais.","teSitua":{"termos":[{"termo":"inassiduidade","significado":"falta habitual ao serviço, sem justificativa, além dos limites da lei."},{"termo":"sem causa justificável","significado":"sem motivo aceito pela lei, como doença comprovada."},{"termo":"intercalados","significado":"não seguidos, espalhados ao longo do período."}],"exemplo":"Ao longo de um ano, Tadeu faltou sem justificativa 22 dias úteis, em semanas diferentes. Como passou de vinte dias úteis intercalados, configurou-se a inassiduidade, que pode levar à demissão."}},{"id":"aut.administrativo_tj.penalidades.0006","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":4,"enunciado":"Para configuração da inassiduidade em razão de ausência ao serviço por mais de 15 dias consecutivos, segundo o Estatuto,","alternativas":{"A":"serão computados os sábados, os domingos, os feriados e os pontos facultativos subsequentes à primeira falta.","B":"serão computados apenas os dias úteis.","C":"não serão computados os feriados, em nenhuma hipótese.","D":"serão computados apenas os dias em que houve expediente forense.","E":"somente os dias de plantão serão computados."},"gabarito":"A","explicacao":"O art. 256, § 3º, 1, manda computar os sábados, domingos, feriados e pontos facultativos subsequentes à primeira falta. No regime de plantão, computam-se também os dias de folga subsequentes aos plantões faltados (item 2).","explicacoes":{"A":"Correta: art. 256, § 3º, 1.","B":"Na hipótese de dias consecutivos, contam-se também fins de semana e feriados; a contagem em dias úteis é para as faltas intercaladas.","C":"Os feriados subsequentes à primeira falta são computados.","D":"A lei não restringe aos dias de expediente.","E":"O regime de plantão tem regra complementar, mas não é o único computado."},"fonte":"Lei 10.261/1968, art. 256, § 3º, 1","mastigado":"A resposta é a letra A. Depois da primeira falta, os fins de semana e feriados seguintes entram na conta dos quinze dias seguidos. Quem some numa segunda-feira e só volta duas semanas depois já passou do limite.","teSitua":{"termos":[{"termo":"inassiduidade","significado":"falta habitual ao serviço sem justificativa, além do limite da lei."},{"termo":"pontos facultativos","significado":"dias em que o expediente é dispensado por decisão do governo, sem ser feriado."},{"termo":"subsequentes","significado":"que vêm logo depois, na sequência dos dias."}],"exemplo":"Paulo faltou de uma segunda-feira até a sexta-feira da semana seguinte, sem justificativa. Contando o sábado e o domingo intermediários, foram doze dias. Se continuasse ausente até a quarta-feira seguinte, passaria dos quinze dias consecutivos."}},{"id":"aut.administrativo_tj.penalidades.0007","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, a pena de demissão por ineficiência no serviço só será aplicada quando verificada a impossibilidade de readaptação.","gabarito":"C","explicacao":"É o que dispõe o art. 256, § 2º. A ineficiência no serviço é causa de demissão (inciso III), mas a lei exige antes verificar se o servidor pode ser readaptado.","fonte":"Lei 10.261/1968, art. 256, III e § 2º","mastigado":"Certo. Antes de demitir alguém por não render no trabalho, a Administração precisa ver se ele não serviria em outro cargo mais compatível com sua capacidade. Só se isso for impossível vem a demissão.","teSitua":{"termos":[{"termo":"ineficiência no serviço","significado":"incapacidade de realizar o trabalho do cargo de modo satisfatório."},{"termo":"readaptação","significado":"mudança do servidor para cargo mais compatível com sua capacidade, após exame médico."}],"exemplo":"O desempenho de Odair caiu muito depois de um problema de saúde. Antes de pensar em demissão por ineficiência, a Administração verificou se ele poderia ser readaptado em cargo compatível com sua condição."}},{"id":"aut.administrativo_tj.penalidades.0008","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Estatuto paulista, será aplicada a pena de demissão a bem do serviço público ao funcionário que","alternativas":{"A":"receber ou solicitar propinas, comissões, presentes ou vantagens de qualquer espécie, diretamente ou por intermédio de outrem, em razão de suas funções.","B":"deixar de comparecer ao serviço por 5 dias consecutivos.","C":"for ineficiente no serviço, havendo possibilidade de readaptação.","D":"cometer indisciplina pela primeira vez.","E":"deixar de residir no local onde exerce o cargo."},"gabarito":"A","explicacao":"Receber ou solicitar propinas e vantagens em razão das funções é hipótese de demissão a bem do serviço público (art. 257, VII). Faltas por 5 dias não configuram inassiduidade; a ineficiência leva à demissão simples e só quando impossível a readaptação; indisciplina leva a repreensão; residência é dever cujo descumprimento não está no art. 257.","explicacoes":{"A":"Correta: art. 257, VII.","B":"Cinco dias não configuram inassiduidade (art. 256, § 1º).","C":"Ineficiência leva à demissão simples, e só se impossível a readaptação (art. 256, § 2º).","D":"Indisciplina leva à repreensão (art. 253).","E":"Esse descumprimento de dever (art. 241, VII) não está entre as hipóteses do art. 257."},"fonte":"Lei 10.261/1968, art. 257, VII","mastigado":"A resposta é a letra A. Aceitar ou pedir propina, presente ou vantagem por causa do cargo é das faltas mais graves e leva à demissão a bem do serviço público, a forma mais severa de demissão.","teSitua":{"termos":[{"termo":"demissão a bem do serviço público","significado":"forma mais grave de demissão, que impede nova investidura por 10 anos."},{"termo":"propinas","significado":"pagamentos indevidos para que o servidor faça ou deixe de fazer algo."},{"termo":"por intermédio de outrem","significado":"por meio de outra pessoa."}],"exemplo":"Um advogado ofereceu dinheiro ao escrevente Flávio para que um processo andasse mais rápido. Flávio aceitou e pediu que o valor fosse entregue à sua esposa. Comprovado o fato, cabe demissão a bem do serviço público."}},{"id":"aut.administrativo_tj.penalidades.0009","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a Lei nº 10.261/1968, praticar, em serviço, ofensas físicas contra funcionários ou particulares, ainda que em legítima defesa, sujeita o funcionário à demissão a bem do serviço público.","gabarito":"E","explicacao":"O art. 257, V, prevê demissão a bem do serviço público para ofensas físicas em serviço contra funcionários ou particulares, salvo se em legítima defesa. A afirmativa elimina justamente a ressalva.","fonte":"Lei 10.261/1968, art. 257, V","mastigado":"Errado. Agredir alguém no serviço leva à demissão a bem do serviço público, mas a própria lei abre exceção para quem agiu em legítima defesa, isto é, para se proteger de uma agressão.","teSitua":{"termos":[{"termo":"ofensas físicas","significado":"agressões ao corpo de outra pessoa."},{"termo":"legítima defesa","significado":"reação moderada para repelir agressão injusta, atual ou iminente."},{"termo":"demissão a bem do serviço público","significado":"forma mais grave de demissão, com impedimento de nova investidura por 10 anos."}],"exemplo":"Um homem exaltado partiu para cima do escrevente Lauro no balcão do fórum. Lauro apenas o segurou e o empurrou para se proteger. Como agiu em legítima defesa, não cabe a demissão a bem do serviço público por esse fato."}},{"id":"aut.administrativo_tj.penalidades.0010","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Estatuto, a pena de cassação de aposentadoria ou disponibilidade será aplicada se ficar provado que o inativo","alternativas":{"A":"praticou, quando em atividade, falta grave para a qual é cominada a pena de demissão ou de demissão a bem do serviço público.","B":"deixou de comparecer à perícia médica anual.","C":"mudou de domicílio sem comunicar a Administração.","D":"aceitou cargo em comissão, depois de aposentado.","E":"exerceu mandato eletivo após a aposentadoria."},"gabarito":"A","explicacao":"O art. 259 prevê cassação se o inativo praticou, na atividade, falta punível com demissão ou demissão a bem do serviço público (I); aceitou ilegalmente cargo ou função pública (II); aceitou representação de Estado estrangeiro sem autorização do Presidente da República (III); ou praticou usura (IV). O aposentado pode exercer mandato eletivo ou cargo em comissão (art. 171, § 3º).","explicacoes":{"A":"Correta: art. 259, I.","B":"Não é hipótese do art. 259.","C":"Não é hipótese do art. 259.","D":"Aceitar cargo em comissão é permitido ao aposentado (art. 171, § 3º); o art. 259 fala em aceitar ilegalmente.","E":"O mandato eletivo é permitido ao aposentado (art. 171, § 3º)."},"fonte":"Lei 10.261/1968, art. 259, I; art. 171, § 3º","mastigado":"A resposta é a letra A. Aposentar-se não apaga uma falta grave feita na ativa. Se ficar provado que ele cometeu algo que daria demissão, a aposentadoria pode ser cassada. Ser vereador ou assessor depois de aposentado é permitido.","teSitua":{"termos":[{"termo":"cassação de aposentadoria","significado":"anulação da aposentadoria como punição."},{"termo":"inativo","significado":"servidor aposentado ou em disponibilidade."},{"termo":"cominada","significado":"prevista em lei como punição para aquela conduta."}],"exemplo":"Após a aposentadoria de Ademir, descobriu-se que, anos antes, ele havia desviado dinheiro do cartório, falta punível com demissão a bem do serviço público. Comprovado o fato no processo, a aposentadoria dele foi cassada."}},{"id":"aut.administrativo_tj.penalidades.0011","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":4,"enunciado":"Pela redação vigente do art. 260 da Lei nº 10.261/1968, os Diretores de Departamento e Divisão são competentes para aplicar penalidades até a de suspensão limitada a","alternativas":{"A":"30 dias.","B":"60 dias.","C":"90 dias.","D":"15 dias.","E":"8 dias."},"gabarito":"A","explicacao":"O art. 260 vigente atribui: ao Governador, todas as penas (I); aos Secretários, Procurador Geral, Controlador Geral e Superintendentes de Autarquia (II); aos Chefes de Gabinete, até a de suspensão (III); aos Coordenadores, até a de suspensão limitada a 60 dias (IV); e aos Diretores de Departamento e Divisão, até a de suspensão limitada a 30 dias (V).","explicacoes":{"A":"Correta: art. 260, V.","B":"Sessenta dias é o limite dos Coordenadores (inciso IV).","C":"Noventa dias é o máximo da suspensão em geral (art. 254), não o limite desses diretores.","D":"Quinze dias era limite da redação antiga, revogada.","E":"Oito dias era limite da redação antiga, revogada."},"fonte":"Lei 10.261/1968, art. 260, V (redação da LC 942/2003)","mastigado":"A resposta é a letra A. Quanto mais alta a autoridade, maior a pena que pode aplicar. Os Diretores de Departamento e Divisão podem suspender por até trinta dias; os Coordenadores, até sessenta; os Chefes de Gabinete, até a suspensão máxima.","teSitua":{"termos":[{"termo":"Diretores de Departamento e Divisão","significado":"autoridades que chefiam unidades administrativas intermediárias."},{"termo":"suspensão","significado":"pena que afasta o servidor do serviço por certo tempo."}],"exemplo":"Uma falta cometida por um servidor justificaria suspensão de 45 dias. O Diretor de Divisão não pode aplicá-la, porque seu limite é de 30 dias; o caso vai ao Coordenador, que pode aplicar até 60 dias."}},{"id":"aut.administrativo_tj.penalidades.0012","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Havendo mais de um infrator e diversidade de sanções, a competência para aplicar as penalidades será da autoridade responsável pela imposição da penalidade mais grave.","gabarito":"C","explicacao":"É o que diz o parágrafo único do art. 260, acrescentado pela LC 942/2003.","fonte":"Lei 10.261/1968, art. 260, parágrafo único","mastigado":"Certo. Se num mesmo caso vários servidores merecem penas diferentes, uma só autoridade decide tudo: a que tem poder para aplicar a pena mais grave. Assim o caso não fica dividido.","teSitua":{"termos":[{"termo":"infrator","significado":"pessoa que cometeu a infração."},{"termo":"diversidade de sanções","significado":"existência de penas diferentes para os envolvidos."}],"exemplo":"Num mesmo processo, apurou-se que Diva merecia repreensão e Juarez, demissão. Como a pena mais grave cabe ao Governador ou ao Secretário, essa autoridade decide sobre os dois servidores."}},{"id":"aut.administrativo_tj.penalidades.0013","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, extingue-se a punibilidade pela prescrição da falta sujeita à pena de repreensão, suspensão ou multa em","alternativas":{"A":"2 anos.","B":"1 ano.","C":"3 anos.","D":"5 anos.","E":"180 dias."},"gabarito":"A","explicacao":"O art. 261, I, fixa 2 anos para as faltas sujeitas a repreensão, suspensão ou multa; o inciso II, 5 anos para as sujeitas a demissão, demissão a bem do serviço público e cassação; e o inciso III, para a falta também prevista como infração penal, o prazo da prescrição em abstrato da pena criminal, se superior a 5 anos.","explicacoes":{"A":"Correta: art. 261, I.","B":"Não há prazo de 1 ano.","C":"Não há prazo de 3 anos.","D":"Cinco anos é o prazo das faltas sujeitas a demissão (inciso II).","E":"Não há prazo de 180 dias."},"fonte":"Lei 10.261/1968, art. 261, I","mastigado":"A resposta é a letra A. Faltas leves, punidas com repreensão, suspensão ou multa, prescrevem em dois anos. As graves, que dão demissão ou cassação, em cinco anos. Passado o prazo, a Administração não pode mais punir.","teSitua":{"termos":[{"termo":"punibilidade","significado":"possibilidade de a Administração aplicar uma pena."},{"termo":"prescrição","significado":"perda do direito de punir pelo decurso do tempo."}],"exemplo":"A chefia soube em 2022 de uma falta leve de Glória, punível com repreensão, mas não abriu sindicância. Em 2024, completados dois anos sem interrupção, a punibilidade se extinguiu pela prescrição."}},{"id":"aut.administrativo_tj.penalidades.0014","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a redação vigente do Estatuto, a prescrição começa a correr do dia em que a falta for cometida ou, nas faltas continuadas ou permanentes, do dia em que tenha cessado a continuação ou a permanência; e interrompem a prescrição a portaria que instaura sindicância e a que instaura processo administrativo.","gabarito":"C","explicacao":"É o que dispõem os §§ 1º e 2º do art. 261, na redação da LC 942/2003. A antiga regra, que contava o prazo da ciência da autoridade, foi revogada.","fonte":"Lei 10.261/1968, art. 261, §§ 1º e 2º","mastigado":"Certo. O prazo para punir começa no dia da falta, ou no dia em que ela parou, se era contínua. Ele é interrompido quando sai a portaria que abre a sindicância ou o processo administrativo.","teSitua":{"termos":[{"termo":"faltas continuadas ou permanentes","significado":"infrações que se prolongam no tempo ou se repetem em sequência."},{"termo":"portaria","significado":"ato escrito da autoridade que determina providências, como a abertura de um procedimento."},{"termo":"sindicância","significado":"procedimento disciplinar para faltas punidas com repreensão, suspensão ou multa."}],"exemplo":"Em março de 2022, Glória cometeu uma falta leve, punível com repreensão, mas nenhuma sindicância foi aberta. Em março de 2024, completados dois anos desde a falta sem interrupção, a punibilidade se extinguiu pela prescrição."}},{"id":"aut.administrativo_tj.penalidades.0015","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com a Lei nº 10.261/1968, a prescrição NÃO corre","alternativas":{"A":"durante o prazo estabelecido para o cumprimento do Termo de Ajustamento de Conduta.","B":"durante as férias do funcionário investigado.","C":"enquanto o funcionário estiver em licença-prêmio.","D":"durante o recesso forense.","E":"enquanto não for publicada a portaria de apuração preliminar."},"gabarito":"A","explicacao":"O art. 261, § 4º, diz que a prescrição não corre: enquanto sobrestado o processo para aguardar decisão judicial (1); enquanto insubsistente o vínculo funcional que venha a ser restabelecido (2); durante a suspensão da sindicância (3); no curso das práticas autocompositivas (4); e durante o prazo para cumprimento do Termo de Ajustamento de Conduta (5). O art. 267-M repete a última regra.","explicacoes":{"A":"Correta: art. 261, § 4º, 5, e art. 267-M.","B":"Férias não suspendem a prescrição.","C":"Licença-prêmio não está no rol.","D":"Recesso forense não está no rol.","E":"A apuração preliminar não é causa de interrupção nem de suspensão da prescrição."},"fonte":"Lei 10.261/1968, art. 261, § 4º, 5; art. 267-M","mastigado":"A resposta é a letra A. Enquanto o servidor cumpre o acordo de ajuste de conduta, o relógio da prescrição fica parado. Assim, se ele descumprir o acordo, a Administração ainda pode punir. Férias e licenças não param esse relógio.","teSitua":{"termos":[{"termo":"prescrição","significado":"perda do direito de punir pelo decurso do tempo."},{"termo":"Termo de Ajustamento de Conduta","significado":"acordo em que o servidor reconhece a irregularidade e se compromete a corrigir o comportamento."},{"termo":"recesso forense","significado":"período no fim do ano em que o expediente do Judiciário é suspenso."}],"exemplo":"Yara celebrou Termo de Ajustamento de Conduta com prazo de um ano e meio. Durante esse período, a prescrição não corre. Se ela descumprir o termo, a Administração ainda poderá apurar e punir a falta."}},{"id":"aut.administrativo_tj.penalidades.0016","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":3,"enunciado":"Extinta a punibilidade pela prescrição, a autoridade julgadora determinará o registro do fato nos assentamentos individuais do servidor.","gabarito":"C","explicacao":"É a regra do art. 261, § 5º. O § 6º manda ainda que a decisão que reconhecer a prescrição determine as providências para apurar a responsabilidade por sua ocorrência.","fonte":"Lei 10.261/1968, art. 261, §§ 5º e 6º","mastigado":"Certo. Mesmo sem poder punir por causa da prescrição, a autoridade manda anotar o fato na ficha do servidor. E deve investigar quem deixou o prazo passar.","teSitua":{"termos":[{"termo":"punibilidade","significado":"possibilidade de a Administração aplicar uma pena."},{"termo":"assentamentos individuais","significado":"ficha funcional com o histórico do servidor."},{"termo":"autoridade julgadora","significado":"autoridade que decide o procedimento disciplinar."}],"exemplo":"O processo contra Manoel demorou tanto que a falta prescreveu. A autoridade declarou a prescrição, mandou registrar o fato na ficha dele e determinou apuração para saber por que o processo atrasou."}},{"id":"aut.administrativo_tj.penalidades.0017","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Estatuto, quando a infração não estiver suficientemente caracterizada ou não estiver definida a autoria, a autoridade realizará","alternativas":{"A":"apuração preliminar, de natureza simplesmente investigativa, a ser concluída em 30 dias.","B":"processo administrativo, obrigatoriamente, no prazo de 90 dias.","C":"sindicância, no prazo improrrogável de 8 dias.","D":"suspensão preventiva do funcionário por 30 dias.","E":"arquivamento imediato, por falta de provas."},"gabarito":"A","explicacao":"O art. 265 prevê apuração preliminar, de natureza simplesmente investigativa, quando a infração não estiver caracterizada ou a autoria definida. Deve ser concluída em 30 dias (§ 1º); ao final, a autoridade opina pelo arquivamento ou pela instauração de sindicância ou processo (§ 3º).","explicacoes":{"A":"Correta: art. 265 e § 1º.","B":"O processo administrativo pressupõe falta caracterizada; a fase prévia é a apuração preliminar.","C":"Oito dias é o prazo para instaurar processo administrativo após a determinação (art. 277).","D":"A suspensão preventiva foi substituída pelas providências do art. 266.","E":"A lei manda investigar antes de arquivar."},"fonte":"Lei 10.261/1968, art. 265, caput e §§ 1º e 3º","mastigado":"A resposta é a letra A. Quando ainda não se sabe direito o que aconteceu ou quem fez, a autoridade faz primeiro uma investigação simples, a apuração preliminar, em trinta dias. Depois decide se arquiva ou abre sindicância ou processo.","teSitua":{"termos":[{"termo":"apuração preliminar","significado":"investigação inicial para esclarecer o fato e a autoria antes de abrir procedimento disciplinar."},{"termo":"autoria","significado":"identificação de quem praticou o ato."},{"termo":"sindicância","significado":"procedimento disciplinar para faltas punidas com repreensão, suspensão ou multa."}],"exemplo":"Sumiu um processo físico do cartório e ninguém sabe quem o retirou. A autoridade abre apuração preliminar, ouve os servidores e consulta os registros. Em trinta dias, conclui e opina pela instauração de sindicância contra quem foi identificado."}},{"id":"aut.administrativo_tj.penalidades.0018","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":4,"enunciado":"Determinada a instauração de sindicância ou processo administrativo, havendo conveniência para a instrução ou para o serviço, o Chefe de Gabinete, por despacho fundamentado, poderá ordenar o afastamento preventivo do servidor","alternativas":{"A":"sem prejuízo de vencimentos ou vantagens, até 180 dias, prorrogáveis uma única vez por igual período.","B":"com perda de 1/3 dos vencimentos, até 90 dias.","C":"sem vencimentos, até a decisão final do processo.","D":"sem prejuízo de vencimentos, por 30 dias improrrogáveis.","E":"com perda total dos vencimentos, até 60 dias."},"gabarito":"A","explicacao":"O art. 266, I, prevê afastamento preventivo, quando recomendado pela moralidade administrativa ou pela apuração do fato, sem prejuízo de vencimentos ou vantagens, até 180 dias, prorrogáveis uma única vez por igual período. O período computa-se como de efetivo exercício e não é descontado da pena de suspensão (art. 267).","explicacoes":{"A":"Correta: art. 266, I.","B":"A perda de 1/3 era da redação antiga, revogada.","C":"O afastamento é sem prejuízo de vencimentos.","D":"O prazo é de até 180 dias, prorrogáveis.","E":"Não há perda de vencimentos."},"fonte":"Lei 10.261/1968, art. 266, I; art. 267","mastigado":"A resposta é a letra A. O servidor investigado pode ser afastado para não atrapalhar a apuração, mas continua recebendo normalmente. O afastamento dura até cento e oitenta dias e pode ser prorrogado uma vez.","teSitua":{"termos":[{"termo":"afastamento preventivo","significado":"retirada temporária do servidor do serviço durante a apuração, sem caráter de pena."},{"termo":"despacho fundamentado","significado":"decisão escrita com as razões que a justificam."},{"termo":"moralidade administrativa","significado":"dever de agir com ética e honestidade na Administração."}],"exemplo":"Contra Wilma foi instaurado processo por suspeita de fraude em certidões. Para que ela não interfira nas provas, o Chefe de Gabinete a afastou preventivamente por 180 dias, sem corte no salário."}},{"id":"aut.administrativo_tj.penalidades.0019","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"certo_errado","dificuldade":4,"enunciado":"Para aplicação das práticas autocompositivas previstas na Lei nº 10.261/1968, é necessário que as partes reconheçam os fatos essenciais, o que implica admissão de culpa em eventual sindicância ou processo administrativo.","gabarito":"E","explicacao":"O art. 267-B, § 2º, exige o reconhecimento dos fatos essenciais, sem que isso implique admissão de culpa em eventual sindicância ou processo. O conteúdo das sessões é sigiloso e não pode ser usado como prova (§ 3º), e a participação é voluntária, sem que a recusa seja considerada em desfavor do funcionário (inciso II).","fonte":"Lei 10.261/1968, art. 267-B, § 2º (LC 1.361/2021)","mastigado":"Errado. Para entrar na mediação ou conciliação, as partes precisam reconhecer o que aconteceu, mas isso não vale como confissão de culpa. O que se fala nas sessões é sigiloso e não pode ser usado como prova depois.","teSitua":{"termos":[{"termo":"práticas autocompositivas","significado":"formas de resolver o conflito por acordo entre os envolvidos, como mediação e conciliação."},{"termo":"fatos essenciais","significado":"pontos principais do que aconteceu entre os envolvidos."},{"termo":"admissão de culpa","significado":"reconhecimento de responsabilidade pela falta."}],"exemplo":"Duas colegas de cartório, Bete e Sandra, discutiram e trocaram ofensas. Encaminhadas à mediação, ambas reconheceram que houve a discussão. Esse reconhecimento não serve como confissão num eventual processo disciplinar."}},{"id":"aut.administrativo_tj.penalidades.0020","subtopico":"administrativo_tj.estatuto_sp.penalidades","tipo":"multipla","dificuldade":4,"enunciado":"Nos termos da Lei nº 10.261/1968, a celebração do Termo de Ajustamento de Conduta poderá ser proposta quando atendidos, entre outros, os seguintes requisitos relativos ao funcionário:","alternativas":{"A":"ter mais de 5 anos de efetivo exercício no cargo ou função e não ter celebrado Termo de Ajustamento de Conduta nos últimos 3 anos.","B":"ter mais de 2 anos de exercício e não ter sofrido punição nos últimos 2 anos.","C":"ter agido com dolo, desde que tenha reparado o dano.","D":"estar respondendo a outro processo disciplinar.","E":"ter mais de 10 anos de exercício, independentemente de punições anteriores."},"gabarito":"A","explicacao":"O art. 267-F exige: não ter agido com dolo ou má-fé (I); mais de 5 anos de efetivo exercício (II); nenhuma punição nos últimos 5 anos (III); nenhuma sindicância ou processo em curso (IV); e não ter celebrado TAC nos últimos 3 anos (V). O prazo de cumprimento do termo vai de 1 a 2 anos (art. 267-I, parágrafo único).","explicacoes":{"A":"Correta: art. 267-F, II e V.","B":"Os prazos são de 5 anos de exercício e 5 anos sem punição.","C":"O funcionário não pode ter agido com dolo ou má-fé (inciso I).","D":"Não pode haver sindicância ou processo em curso (inciso IV).","E":"A lei exige ausência de punição nos últimos 5 anos."},"fonte":"Lei 10.261/1968, art. 267-F (LC 1.361/2021)","mastigado":"A resposta é a letra A. O acordo de ajuste de conduta é para servidor experiente e sem histórico ruim: mais de cinco anos no cargo, sem punição nos últimos cinco anos, sem processo aberto, sem má intenção e sem outro acordo desse tipo nos últimos três anos.","teSitua":{"termos":[{"termo":"Termo de Ajustamento de Conduta","significado":"acordo em que o servidor reconhece a irregularidade e se compromete a corrigir a conduta e reparar o dano."},{"termo":"efetivo exercício","significado":"tempo de trabalho real e computável no cargo."},{"termo":"dolo","significado":"intenção de praticar o ato errado."}],"exemplo":"Amanda, com oito anos de cargo e ficha limpa, danificou por descuido um equipamento do cartório. Como não houve dolo e ela nunca firmou acordo semelhante, foi-lhe proposto Termo de Ajustamento de Conduta, com ressarcimento integral do prejuízo."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0001","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, posse é o ato que investe o cidadão em cargo público, e exercício é o ato pelo qual o funcionário assume as atribuições e responsabilidades do cargo.","gabarito":"C","explicacao":"As duas definições estão nos arts. 46 (posse) e 57 (exercício) do Estatuto. Primeiro o cidadão toma posse, assinando o termo; depois entra em exercício, começando a trabalhar.","fonte":"Lei 10.261/1968, arts. 46 e 57","mastigado":"Certo. Posse é o momento em que a pessoa assina o compromisso e passa a ocupar o cargo. Exercício é quando ela de fato começa a trabalhar e assume as tarefas. São dois passos diferentes.","teSitua":{"termos":[{"termo":"investe","significado":"coloca oficialmente a pessoa no cargo."},{"termo":"atribuições e responsabilidades","significado":"tarefas e deveres próprios do cargo."}],"exemplo":"Gabriela assinou o termo de posse como escrevente numa segunda-feira. Na semana seguinte, apresentou-se no cartório e começou a trabalhar. A assinatura foi a posse; o início do trabalho foi o exercício."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0002","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o Estatuto dos Funcionários Públicos Civis de SP, NÃO é requisito para a posse em cargo público","alternativas":{"A":"possuir diploma de curso superior em qualquer caso.","B":"ser brasileiro.","C":"ter completado 18 anos de idade.","D":"estar no gozo dos direitos políticos.","E":"estar em dia com as obrigações militares."},"gabarito":"A","explicacao":"O art. 47 lista como requisitos: ser brasileiro; 18 anos completos; obrigações militares em dia; gozo dos direitos políticos; boa conduta; boa saúde; aptidão; e atendimento às condições especiais do cargo. Diploma superior não é requisito geral; só seria exigível se fosse condição especial prescrita para o cargo.","explicacoes":{"A":"Correta: diploma superior não é requisito geral do art. 47.","B":"Ser brasileiro é requisito (art. 47, I).","C":"A idade mínima de 18 anos é requisito (art. 47, II).","D":"O gozo dos direitos políticos é requisito (art. 47, IV).","E":"A quitação militar é requisito (art. 47, III)."},"fonte":"Lei 10.261/1968, art. 47","mastigado":"A resposta é a letra A. A lei pede nacionalidade brasileira, 18 anos, serviço militar em dia, direitos políticos, boa conduta, saúde e aptidão. Faculdade não é exigência geral: só vale quando o cargo específico pede.","teSitua":{"termos":[{"termo":"posse","significado":"ato que coloca oficialmente a pessoa no cargo público."},{"termo":"gozo dos direitos políticos","significado":"situação de quem pode votar e ser votado, sem suspensão desses direitos."},{"termo":"obrigações militares","significado":"deveres com o serviço militar, como o alistamento."}],"exemplo":"Caio, de 19 anos, brasileiro, com título de eleitor regular e certificado de reservista, foi aprovado para um cargo de nível médio. Mesmo sem faculdade, ele cumpre os requisitos do Estatuto para tomar posse."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0003","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo a Lei nº 10.261/1968, a deficiência da capacidade física, comprovadamente estacionária, não será considerada impedimento para a posse, desde que não impeça o desempenho normal das funções do cargo.","gabarito":"C","explicacao":"É o que diz o parágrafo único do art. 47, ao tratar do requisito de boa saúde (inciso VI). A deficiência estável não impede a posse se for compatível com o desempenho normal das funções.","fonte":"Lei 10.261/1968, art. 47, parágrafo único","mastigado":"Certo. Ter uma deficiência física que não piora com o tempo não impede alguém de tomar posse. O que importa é se a pessoa consegue fazer normalmente o trabalho do cargo.","teSitua":{"termos":[{"termo":"comprovadamente estacionária","significado":"que, segundo exame, não evolui nem se agrava com o tempo."},{"termo":"desempenho normal das funções","significado":"capacidade de fazer o trabalho do cargo de forma regular."}],"exemplo":"Lucas usa cadeira de rodas desde a infância, e sua condição é estável. Aprovado como escrevente, ele pode tomar posse, porque a deficiência não o impede de realizar as tarefas do cargo."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0004","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":3,"enunciado":"Quanto ao requisito de boa saúde para a posse, a Lei nº 10.261/1968, com a redação vigente, prevê que ele será comprovado","alternativas":{"A":"em inspeção por órgão médico oficial do Estado, para cargo efetivo, ou por Atestado de Saúde Ocupacional expedido por médico registrado no Conselho Regional, para cargo em comissão.","B":"sempre por Atestado de Saúde Ocupacional, para qualquer cargo.","C":"apenas por declaração do próprio candidato.","D":"por inspeção em órgão médico oficial, inclusive para cargo em comissão, sem exceção.","E":"somente para cargos que exijam esforço físico."},"gabarito":"A","explicacao":"O art. 47, VI, com redação da LC 1.123/2010, distingue: cargo efetivo exige inspeção por órgão médico oficial do Estado; cargo em comissão, apresentação de Atestado de Saúde Ocupacional expedido por médico registrado no Conselho Regional.","explicacoes":{"A":"Correta: art. 47, VI, na redação vigente.","B":"O atestado ocupacional vale só para cargo em comissão.","C":"A lei exige comprovação médica, não autodeclaração.","D":"Para cargo em comissão basta o Atestado de Saúde Ocupacional.","E":"O requisito vale para todos os cargos."},"fonte":"Lei 10.261/1968, art. 47, VI (redação da LC 1.123/2010)","mastigado":"A resposta é a letra A. Para cargo de concurso, a saúde é avaliada pela perícia oficial do Estado. Para cargo de confiança, basta um atestado de saúde ocupacional dado por médico com registro no conselho.","teSitua":{"termos":[{"termo":"cargo efetivo","significado":"cargo permanente, ocupado por concursado."},{"termo":"Atestado de Saúde Ocupacional","significado":"documento médico que declara a pessoa apta para determinado trabalho."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"Pâmela, aprovada em concurso, foi à perícia médica oficial do Estado antes da posse. Já Rubens, nomeado assessor em comissão, apresentou um Atestado de Saúde Ocupacional assinado por seu médico, registrado no conselho regional."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0005","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos do Estatuto, a posse verificar-se-á mediante a assinatura de termo em que o funcionário prometa cumprir fielmente os deveres do cargo, termo esse lavrado em livro próprio e assinado pela autoridade que der posse.","gabarito":"C","explicacao":"É o que dispõe o art. 49 e seu parágrafo único. O art. 51 acrescenta que a autoridade que der posse deve verificar, sob pena de responsabilidade, se foram satisfeitas as condições para a investidura.","fonte":"Lei 10.261/1968, art. 49 e parágrafo único","mastigado":"Certo. A posse acontece com a assinatura de um termo em que a pessoa promete cumprir bem os deveres do cargo. Esse termo fica registrado num livro e também é assinado pela autoridade que dá a posse.","teSitua":{"termos":[{"termo":"termo","significado":"documento escrito que registra um ato oficial."},{"termo":"lavrado","significado":"escrito e registrado formalmente em livro oficial."}],"exemplo":"Na cerimônia de posse, Eduardo assinou o termo prometendo cumprir os deveres de escrevente. A juíza diretora do fórum, que deu a posse, também assinou o termo, registrado no livro próprio."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0006","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":3,"enunciado":"Conforme a Lei nº 10.261/1968, a posse poderá ser tomada por procuração","alternativas":{"A":"quando se tratar de funcionário ausente do Estado, em comissão do Governo ou, em casos especiais, a critério da autoridade competente.","B":"em qualquer caso, por livre escolha do nomeado.","C":"apenas quando o nomeado estiver hospitalizado.","D":"somente para cargos em comissão.","E":"em nenhuma hipótese, por ser ato personalíssimo."},"gabarito":"A","explicacao":"O art. 50 admite posse por procuração quando se tratar de funcionário ausente do Estado, em comissão do Governo ou, em casos especiais, a critério da autoridade competente.","explicacoes":{"A":"Correta: art. 50.","B":"Não é livre escolha; depende das hipóteses legais.","C":"A lei não restringe a hospitalização; fala em ausência do Estado, comissão do Governo e casos especiais.","D":"Não há restrição a cargos em comissão.","E":"A lei expressamente admite a posse por procuração."},"fonte":"Lei 10.261/1968, art. 50","mastigado":"A resposta é a letra A. Em regra a pessoa toma posse pessoalmente. Mas, se estiver fora do Estado, a serviço do Governo, ou em caso especial aceito pela autoridade, pode mandar um procurador assinar por ela.","teSitua":{"termos":[{"termo":"procuração","significado":"documento pelo qual alguém autoriza outra pessoa a agir em seu nome."},{"termo":"em comissão do Governo","significado":"em missão oficial a serviço do Governo."},{"termo":"autoridade competente","significado":"pessoa com poder legal para praticar aquele ato."}],"exemplo":"Aprovada em concurso, Tânia estava em missão oficial em Brasília na data da posse. Ela enviou procuração ao irmão, que tomou posse em seu nome, como permite o Estatuto."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0007","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":2,"enunciado":"Publicado no órgão oficial o ato de nomeação, o nomeado deverá tomar posse, nos termos da Lei nº 10.261/1968, no prazo de","alternativas":{"A":"30 dias, prorrogável por mais 30 dias a requerimento do interessado.","B":"15 dias, improrrogável.","C":"30 dias, improrrogável.","D":"60 dias, prorrogável por mais 60 dias.","E":"8 dias, prorrogável uma vez por igual período."},"gabarito":"A","explicacao":"O art. 52 fixa 30 dias contados da publicação do ato de provimento, prorrogáveis por mais 30 a requerimento do interessado (§ 1º). Se a posse não ocorrer no prazo, o ato de provimento fica sem efeito (§ 3º).","explicacoes":{"A":"Correta: art. 52, caput e § 1º.","B":"O prazo é de 30 dias e pode ser prorrogado.","C":"O prazo é prorrogável por mais 30 dias.","D":"O prazo é de 30 dias.","E":"Oito dias é o período de trânsito (art. 61), não o prazo de posse."},"fonte":"Lei 10.261/1968, art. 52, caput e § 1º","mastigado":"A resposta é a letra A. Depois que a nomeação sai no Diário Oficial, a pessoa tem trinta dias para tomar posse. Se precisar, pode pedir mais trinta. Perder esse prazo faz a nomeação perder o efeito.","teSitua":{"termos":[{"termo":"órgão oficial","significado":"Diário Oficial, jornal onde os atos do governo são publicados."},{"termo":"ato de nomeação","significado":"ato que escolhe oficialmente a pessoa para o cargo."},{"termo":"requerimento","significado":"pedido formal e escrito à Administração."}],"exemplo":"A nomeação de Fábio saiu no Diário Oficial em 2 de maio. Ele tem até 1º de junho para tomar posse, mas, como estava terminando um curso, requereu prorrogação e ganhou mais trinta dias."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0008","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo o Estatuto paulista, se a posse não se der dentro do prazo legal, o nomeado será demitido do cargo.","gabarito":"E","explicacao":"Se a posse não ocorrer no prazo, será tornado sem efeito o ato de provimento (art. 52, § 3º). Quem não tomou posse nem chegou a ser funcionário; não há demissão. Já quem tomou posse e não entra em exercício no prazo é exonerado (art. 60, § 4º).","fonte":"Lei 10.261/1968, art. 52, § 3º","mastigado":"Errado. Quem não toma posse no prazo ainda nem virou funcionário, então não há o que demitir: a nomeação simplesmente perde o efeito. Demissão é punição para quem já é servidor e comete falta.","teSitua":{"termos":[{"termo":"posse","significado":"ato que coloca oficialmente a pessoa no cargo."},{"termo":"demitido","significado":"afastado do cargo como punição por falta grave."}],"exemplo":"Nomeado em março, Wagner esqueceu o prazo e não apareceu para tomar posse. A Administração publicou ato tornando sem efeito sua nomeação, e a vaga foi oferecida ao próximo colocado. Wagner não foi demitido, porque nunca chegou a ser funcionário."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0009","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":3,"enunciado":"Um candidato nomeado apresentou-se ao órgão médico oficial para a perícia de ingresso, que exigiu exames complementares. Nos termos da Lei nº 10.261/1968, a contagem do prazo para posse","alternativas":{"A":"poderá ser suspensa por até 120 dias, a critério do órgão médico oficial.","B":"não se suspende em nenhuma hipótese.","C":"fica suspensa por tempo indeterminado, até a conclusão dos exames.","D":"poderá ser suspensa por até 30 dias, apenas.","E":"recomeça a correr da data da nomeação."},"gabarito":"A","explicacao":"O art. 53, I, permite suspender a contagem por até 120 dias, a critério do órgão médico oficial, sempre que a inspeção médica exigir. O inciso II prevê suspensão por 30 dias se o candidato recorrer da decisão médica, recurso a ser interposto em até 5 dias (§ 2º). O prazo volta a correr se o candidato, sem motivo justificado, deixar de se submeter aos exames (§ 1º).","explicacoes":{"A":"Correta: art. 53, I.","B":"A lei prevê suspensão.","C":"O limite é de 120 dias.","D":"Trinta dias é a suspensão pela interposição de recurso (inciso II).","E":"A suspensão não reinicia o prazo da nomeação."},"fonte":"Lei 10.261/1968, art. 53, I (redação da LC 1.123/2010)","mastigado":"A resposta é a letra A. Se a perícia pedir mais exames, o prazo da posse fica parado por até cento e vinte dias, conforme decidir o órgão médico. Assim o candidato não perde a vaga por demora dos exames.","teSitua":{"termos":[{"termo":"perícia de ingresso","significado":"exame médico oficial feito antes da posse no cargo."},{"termo":"exames complementares","significado":"exames adicionais pedidos pelo médico para concluir a avaliação."},{"termo":"órgão médico oficial","significado":"serviço médico do Estado responsável pelas perícias."}],"exemplo":"Na perícia de Joice, o médico pediu um exame cardiológico que demoraria semanas. O órgão médico suspendeu a contagem do prazo de posse. Quando o laudo saiu, o prazo voltou a correr e ela tomou posse a tempo."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0010","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":3,"enunciado":"Conforme a redação vigente da Lei nº 10.261/1968, o funcionário efetivo nomeado para cargo em comissão fica dispensado, no ato da posse, da apresentação do atestado de saúde exigido pelo art. 47, VI.","gabarito":"C","explicacao":"É a redação do art. 55, dada pela LC 1.123/2010. Quem já é efetivo e é nomeado para cargo em comissão não precisa apresentar novo atestado de saúde na posse.","fonte":"Lei 10.261/1968, art. 55 (redação da LC 1.123/2010)","mastigado":"Certo. Quem já é servidor efetivo e é chamado para um cargo de confiança não precisa apresentar atestado de saúde de novo na posse. A saúde dele já foi verificada quando entrou no serviço público.","teSitua":{"termos":[{"termo":"efetivo","significado":"servidor que ocupa cargo permanente obtido por concurso."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"Bruna é escrevente efetiva há seis anos e foi nomeada para um cargo em comissão de assessora. Na posse do novo cargo, ela não precisou levar atestado de saúde, porque a lei a dispensa."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0011","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com a Lei nº 10.261/1968, o exercício do cargo terá início no prazo de 30 dias contados da data da posse ou, no caso de remoção, da publicação oficial do ato. O funcionário que não entrar em exercício dentro do prazo","alternativas":{"A":"será exonerado.","B":"terá a posse tornada sem efeito.","C":"será demitido a bem do serviço público.","D":"sofrerá pena de suspensão.","E":"terá o prazo automaticamente prorrogado."},"gabarito":"A","explicacao":"Pelo art. 60, § 4º, o funcionário que não entrar em exercício no prazo será exonerado. O § 1º permite prorrogação por 30 dias a requerimento do interessado e a juízo da autoridade, e o art. 86, § 1º, 3, confirma a exoneração nessa hipótese.","explicacoes":{"A":"Correta: art. 60, § 4º.","B":"Tornar sem efeito é a consequência de não tomar posse (art. 52, § 3º).","C":"Não entrar em exercício não é causa de demissão.","D":"Não há pena de suspensão para essa hipótese.","E":"A prorrogação depende de requerimento e juízo da autoridade (§ 1º)."},"fonte":"Lei 10.261/1968, art. 60, caput e § 4º; art. 86, § 1º, 3","mastigado":"A resposta é a letra A. Se a pessoa toma posse mas não começa a trabalhar no prazo, ela é exonerada, isto é, desligada sem caráter de punição. Não confunda: se não toma posse, a nomeação perde o efeito.","teSitua":{"termos":[{"termo":"exercício","significado":"início efetivo do trabalho no cargo."},{"termo":"remoção","significado":"mudança do local de trabalho sem mudança de cargo."},{"termo":"exonerado","significado":"desligado do cargo sem que isso seja uma punição."}],"exemplo":"Henrique tomou posse em 5 de agosto, mas não se apresentou ao cartório nem pediu prorrogação. Passados trinta dias, foi exonerado. Se nem tivesse tomado posse, sua nomeação seria apenas tornada sem efeito."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0012","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":2,"enunciado":"Segundo o Estatuto, em caso de mudança de sede, será concedido ao funcionário um período de trânsito de até","alternativas":{"A":"8 dias, a contar do desligamento do funcionário.","B":"15 dias, a contar da publicação do ato.","C":"30 dias, a contar da posse.","D":"5 dias úteis, a contar do desligamento.","E":"10 dias, a contar da chegada à nova sede."},"gabarito":"A","explicacao":"O art. 61 concede período de trânsito de até 8 dias, contados do desligamento. O art. 78, XIV, considera de efetivo exercício o trânsito que não exceda esse prazo.","explicacoes":{"A":"Correta: art. 61.","B":"O prazo é de até 8 dias, contados do desligamento.","C":"Trinta dias é o prazo para entrar em exercício (art. 60).","D":"A lei fala em até 8 dias, sem menção a dias úteis (os prazos do Estatuto são corridos, art. 323).","E":"O prazo é de até 8 dias, contados do desligamento."},"fonte":"Lei 10.261/1968, art. 61","mastigado":"A resposta é a letra A. Quando o servidor precisa mudar de cidade por causa do trabalho, ele ganha até oito dias para se mudar, contados de quando sai do posto antigo. Esses dias contam como trabalho efetivo.","teSitua":{"termos":[{"termo":"mudança de sede","significado":"transferência do local de trabalho para outra cidade."},{"termo":"período de trânsito","significado":"dias concedidos para o servidor se mudar e se apresentar no novo local."},{"termo":"desligamento","significado":"saída formal do servidor do posto de trabalho anterior."}],"exemplo":"Vítor foi removido de Ribeirão Preto para Marília. Ele se desligou do fórum antigo numa sexta-feira e teve até oito dias para fazer a mudança antes de se apresentar no novo fórum."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0013","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos do Estatuto, nenhum funcionário poderá ter exercício em serviço ou repartição diferente daquela em que estiver lotado, salvo nos casos previstos na lei ou mediante autorização do Governador; nessa última hipótese, o afastamento só será permitido para fim determinado e prazo certo.","gabarito":"C","explicacao":"A regra está nos arts. 65 e 66. O afastamento autorizado pelo Governador pode ser com ou sem prejuízo de vencimentos, mas sempre para fim determinado e prazo certo.","fonte":"Lei 10.261/1968, arts. 65 e 66","mastigado":"Certo. O servidor trabalha onde está lotado. Para trabalhar em outro lugar, precisa de previsão na lei ou de autorização do Governador, e mesmo assim só para um objetivo definido e por tempo certo.","teSitua":{"termos":[{"termo":"lotado","significado":"designado oficialmente para trabalhar em determinada repartição."},{"termo":"fim determinado e prazo certo","significado":"objetivo definido e período com começo e fim marcados."}],"exemplo":"Juliano, lotado numa Secretaria, foi convidado para ajudar outro órgão num projeto. Com autorização do Governador, ele foi afastado por seis meses, exclusivamente para esse projeto, e depois voltou à sua repartição."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0014","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":4,"enunciado":"Um funcionário estadual foi preso preventivamente. Segundo a redação vigente da Lei nº 10.261/1968, ele","alternativas":{"A":"será considerado afastado do exercício do cargo, com prejuízo da remuneração, até a condenação ou absolvição transitada em julgado.","B":"continuará recebendo integralmente sua remuneração durante a prisão.","C":"será imediatamente demitido.","D":"receberá 2/3 do vencimento durante o afastamento.","E":"permanecerá em exercício até o trânsito em julgado."},"gabarito":"A","explicacao":"O art. 70, com redação da LC 1.012/2007, determina que o servidor preso em flagrante, preventiva ou temporariamente, ou pronunciado, seja considerado afastado do exercício, com prejuízo da remuneração, até a condenação ou absolvição transitada em julgado. A antiga regra dos 2/3 do vencimento foi substituída.","explicacoes":{"A":"Correta: art. 70, caput, redação vigente.","B":"O afastamento é com prejuízo da remuneração.","C":"A prisão provisória não gera demissão imediata.","D":"A previsão de 2/3 é da redação antiga, já alterada.","E":"O servidor preso é afastado do exercício."},"fonte":"Lei 10.261/1968, art. 70 (redação da LC 1.012/2007)","mastigado":"A resposta é a letra A. O servidor preso provisoriamente fica afastado e não recebe salário até o processo criminal terminar. A antiga regra de receber dois terços não vale mais: cuidado com essa pegadinha.","teSitua":{"termos":[{"termo":"preso preventivamente","significado":"detido antes da condenação, por ordem do juiz, para proteger o processo ou a sociedade."},{"termo":"transitada em julgado","significado":"decisão definitiva, sem possibilidade de recurso."}],"exemplo":"O servidor Ronaldo foi preso preventivamente durante uma investigação. A partir da prisão ele fica afastado do cargo e sem remuneração. Se for absolvido de forma definitiva, a situação dele será revista; se for condenado, aplicam-se as regras seguintes da lei."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0015","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com o Estatuto paulista, o funcionário eleito vereador, quando a vereança não for remunerada, ficará afastado do cargo durante todo o mandato, com prejuízo do vencimento.","gabarito":"E","explicacao":"Na vereança não remunerada, o afastamento só ocorre nos dias de sessão e desde que o horário das sessões coincida com o horário de trabalho (art. 74, caput), e se dá sem prejuízo de vencimentos e vantagens (§ 1º). Durante o mandato, é vedada a remoção ou transferência (§ 2º).","fonte":"Lei 10.261/1968, art. 74 e §§ 1º e 2º","mastigado":"Errado. Se o vereador não ganha pelo mandato, ele só deixa de trabalhar nos dias de sessão que caem no horário do serviço, e continua recebendo normalmente. Além disso, não pode ser removido enquanto for vereador.","teSitua":{"termos":[{"termo":"vereança","significado":"mandato de vereador na Câmara Municipal."},{"termo":"com prejuízo do vencimento","significado":"sem receber o salário do cargo durante o afastamento."}],"exemplo":"Sônia é escrevente e foi eleita vereadora numa cidade pequena onde o cargo não é remunerado. As sessões são às terças à tarde, no horário do expediente. Só nesses dias ela se afasta, sem perder o salário."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0016","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, o funcionário no desempenho de mandato eletivo federal ou estadual","alternativas":{"A":"ficará afastado de seu cargo, com prejuízo do vencimento ou remuneração.","B":"poderá acumular o cargo com o mandato, se houver compatibilidade de horários.","C":"ficará afastado, podendo optar pela remuneração do cargo.","D":"será exonerado do cargo efetivo.","E":"ficará afastado apenas nos dias de sessão."},"gabarito":"A","explicacao":"O art. 72 determina o afastamento do cargo, com prejuízo do vencimento ou remuneração, durante o mandato eletivo federal ou estadual. A faculdade de opção existe para Prefeito ou Vereador remunerado (art. 73).","explicacoes":{"A":"Correta: art. 72.","B":"Não há acumulação com mandato federal ou estadual.","C":"A opção é prevista para Prefeito ou Vereador remunerado (art. 73), não para mandato federal ou estadual.","D":"O funcionário é afastado, não exonerado.","E":"O afastamento só nos dias de sessão é para vereança não remunerada (art. 74)."},"fonte":"Lei 10.261/1968, art. 72","mastigado":"A resposta é a letra A. Quem é eleito deputado federal, deputado estadual ou senador sai do cargo e deixa de receber dele durante o mandato. A possibilidade de escolher qual salário receber é só para prefeito e vereador remunerado.","teSitua":{"termos":[{"termo":"mandato eletivo","significado":"cargo político obtido por eleição, como o de deputado."},{"termo":"com prejuízo do vencimento","significado":"sem receber o salário do cargo enquanto durar o afastamento."}],"exemplo":"O servidor Ivo foi eleito deputado estadual. Durante os quatro anos do mandato, ele fica afastado do cargo e não recebe o vencimento estadual de servidor, apenas o subsídio de deputado."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0017","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, são considerados de efetivo exercício, para todos os efeitos legais, os dias em que o funcionário estiver afastado em virtude de casamento, até 8 dias, e de falecimento dos avós, netos, sogros, padrasto ou madrasta, até 2 dias.","gabarito":"C","explicacao":"O art. 78 considera de efetivo exercício, entre outros: casamento, até 8 dias (II); falecimento do cônjuge, filhos, pais e irmãos, até 8 dias (III); e falecimento dos avós, netos, sogros, padrasto ou madrasta, até 2 dias (IV, redação da LC 318/1983).","fonte":"Lei 10.261/1968, art. 78, II e IV","mastigado":"Certo. Quem se casa pode faltar até oito dias sem prejuízo. Pela morte de avós, netos, sogros, padrasto ou madrasta, são até dois dias. Esses dias contam como se a pessoa tivesse trabalhado.","teSitua":{"termos":[{"termo":"efetivo exercício","significado":"tempo considerado como de trabalho real, para todos os efeitos."},{"termo":"padrasto ou madrasta","significado":"marido da mãe ou esposa do pai, que não é o pai ou a mãe biológica."}],"exemplo":"Débora se casou numa sexta-feira e ficou oito dias fora do cartório. No mês seguinte, faltou dois dias pela morte da avó. Todos esses dias contam como efetivo exercício, sem desconto e sem prejuízo na contagem de tempo."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0018","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do Estatuto, NÃO é computado para nenhum efeito o tempo de","alternativas":{"A":"serviço gratuito.","B":"férias.","C":"licença-prêmio.","D":"licença à funcionária gestante.","E":"serviços obrigatórios por lei."},"gabarito":"A","explicacao":"O art. 85 diz que o tempo de serviço gratuito não será computado para nenhum efeito. Férias, licença-prêmio, licença à gestante e serviços obrigatórios por lei são de efetivo exercício (art. 78, I, IX, VII e V).","explicacoes":{"A":"Correta: art. 85.","B":"Férias são de efetivo exercício (art. 78, I).","C":"Licença-prêmio é de efetivo exercício (art. 78, IX).","D":"Licença à gestante é de efetivo exercício (art. 78, VII).","E":"Serviços obrigatórios por lei são de efetivo exercício (art. 78, V)."},"fonte":"Lei 10.261/1968, art. 85; art. 78","mastigado":"A resposta é a letra A. O trabalho feito de graça, sem remuneração, não conta para nada no tempo de serviço. Já férias, licença-prêmio, licença-gestante e serviços obrigatórios, como o júri, contam como trabalho efetivo.","teSitua":{"termos":[{"termo":"serviço gratuito","significado":"trabalho prestado sem receber remuneração."},{"termo":"licença-prêmio","significado":"período de descanso remunerado concedido ao servidor assíduo após certo tempo de serviço."},{"termo":"serviços obrigatórios por lei","significado":"deveres impostos pela lei a qualquer cidadão, como servir como jurado."}],"exemplo":"Antes de entrar no Estado, Celso ajudou de graça uma repartição por um ano. Esse período não conta para nada. Já os dias em que ele serviu como jurado, depois de empossado, contam como efetivo exercício."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0019","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com a Lei nº 10.261/1968, a vacância do cargo decorrerá de exoneração, demissão, transferência, acesso, aposentadoria e falecimento, e a exoneração dar-se-á, entre outras hipóteses, a critério do Governo, quando se tratar de ocupante de cargo em comissão.","gabarito":"C","explicacao":"O art. 86 lista as seis causas de vacância. O § 1º prevê exoneração a pedido, a critério do Governo para ocupante de cargo em comissão e quando o funcionário não entrar em exercício no prazo. O § 2º diz que a demissão é penalidade.","fonte":"Lei 10.261/1968, art. 86, caput e § 1º","mastigado":"Certo. O cargo fica vago quando o ocupante sai por exoneração, demissão, transferência, acesso, aposentadoria ou morte. O ocupante de cargo de confiança pode ser exonerado quando o Governo quiser.","teSitua":{"termos":[{"termo":"vacância","significado":"situação do cargo que ficou sem ocupante."},{"termo":"exoneração","significado":"desligamento do cargo sem caráter de punição."},{"termo":"cargo em comissão","significado":"cargo de confiança, de livre nomeação e exoneração."}],"exemplo":"O assessor Marcelo ocupava cargo em comissão e foi exonerado porque o novo secretário quis montar sua própria equipe. O cargo dele ficou vago. Não houve punição: foi exoneração a critério da Administração."}},{"id":"aut.administrativo_tj.posse_exercicio_vacancia.0020","subtopico":"administrativo_tj.estatuto_sp.posse_exercicio_vacancia","tipo":"multipla","dificuldade":2,"enunciado":"Sobre a vacância do cargo, conforme o Estatuto paulista, é correto afirmar que","alternativas":{"A":"a demissão será aplicada como penalidade nos casos previstos na lei.","B":"a remoção é uma das causas de vacância.","C":"a readaptação gera vacância do cargo por exoneração.","D":"a exoneração é sempre penalidade disciplinar.","E":"a promoção é causa de vacância prevista no art. 86."},"gabarito":"A","explicacao":"O art. 86, § 2º, diz que a demissão será aplicada como penalidade nos casos previstos na lei. A remoção e a promoção não estão no rol do art. 86, e a exoneração não é pena (§ 1º).","explicacoes":{"A":"Correta: art. 86, § 2º.","B":"Remoção não está entre as causas do art. 86.","C":"A readaptação é feita mediante transferência (art. 42), e não por exoneração.","D":"A exoneração não tem caráter punitivo.","E":"A promoção não está no art. 86; o acesso, sim."},"fonte":"Lei 10.261/1968, art. 86, § 2º","mastigado":"A resposta é a letra A. Demissão é castigo por falta grave. Exoneração é saída sem castigo. Remoção e promoção não deixam o cargo vago pela lista da lei; o acesso e a transferência, sim.","teSitua":{"termos":[{"termo":"vacância","significado":"situação do cargo que ficou sem ocupante."},{"termo":"penalidade","significado":"punição aplicada ao servidor por uma infração."},{"termo":"readaptação","significado":"mudança do servidor para cargo compatível com sua capacidade, após exame médico."}],"exemplo":"Lúcio foi demitido após processo administrativo que comprovou falta grave: isso é penalidade. Já Rita pediu exoneração para abrir um negócio próprio. Os dois cargos ficaram vagos, mas só no caso de Lúcio houve punição."}},{"id":"aut.administrativo_tj.processo_disciplinar.0001","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da redação vigente da Lei nº 10.261/1968, será obrigatório o processo administrativo quando a falta disciplinar, por sua natureza, possa determinar a pena de","alternativas":{"A":"demissão, demissão a bem do serviço público ou cassação de aposentadoria ou disponibilidade.","B":"repreensão.","C":"suspensão de até 30 dias.","D":"multa.","E":"repreensão ou suspensão, conforme o caso."},"gabarito":"A","explicacao":"A apuração se faz por sindicância ou processo administrativo, com contraditório e ampla defesa (art. 268). A sindicância cabe quando a falta possa gerar repreensão, suspensão ou multa (art. 269); o processo administrativo é obrigatório para demissão, demissão a bem do serviço público e cassação de aposentadoria ou disponibilidade (art. 270).","explicacoes":{"A":"Correta: art. 270.","B":"Repreensão é apurada por sindicância (art. 269).","C":"Suspensão é apurada por sindicância (art. 269).","D":"Multa é apurada por sindicância (art. 269).","E":"Ambas são apuradas por sindicância (art. 269)."},"fonte":"Lei 10.261/1968, arts. 268, 269 e 270","mastigado":"A resposta é a letra A. Faltas que podem dar as penas mais pesadas, como demissão ou cassação, exigem processo administrativo completo. As faltas mais leves, punidas com repreensão, suspensão ou multa, são apuradas por sindicância.","teSitua":{"termos":[{"termo":"processo administrativo","significado":"procedimento disciplinar completo, obrigatório para as faltas que podem levar à demissão ou cassação."},{"termo":"demissão a bem do serviço público","significado":"forma mais grave de demissão, que impede nova investidura por 10 anos."},{"termo":"cassação de aposentadoria","significado":"anulação da aposentadoria como punição."}],"exemplo":"Há indícios de que o servidor Gérson recebeu propina, falta punível com demissão a bem do serviço público. A Administração instaura processo administrativo. Se a falta fosse apenas atraso frequente, punível com repreensão, bastaria sindicância."}},{"id":"aut.administrativo_tj.processo_disciplinar.0002","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":3,"enunciado":"Segundo o Estatuto, aplicam-se à sindicância as regras do processo administrativo, com algumas modificações. Entre elas,","alternativas":{"A":"a autoridade sindicante e cada acusado poderão arrolar até 3 testemunhas, e a sindicância deverá estar concluída em 60 dias.","B":"a autoridade sindicante e cada acusado poderão arrolar até 10 testemunhas, e a sindicância deverá estar concluída em 30 dias.","C":"não há direito de defesa na sindicância.","D":"a sindicância pode ser instaurada contra funcionário já exonerado.","E":"a sindicância deverá estar concluída em 90 dias, sem limite de testemunhas."},"gabarito":"A","explicacao":"O art. 273 manda aplicar à sindicância as regras do processo administrativo, com as modificações: até 3 testemunhas para a autoridade sindicante e para cada acusado (I); conclusão em 60 dias (II); envio, com o relatório, à autoridade competente para decidir (III). Não se instaura sindicância contra quem já perdeu o vínculo (art. 269, parágrafo único).","explicacoes":{"A":"Correta: art. 273, I e II.","B":"No processo administrativo são até 5 testemunhas (art. 283, § 1º); na sindicância, até 3; e o prazo é de 60 dias.","C":"A apuração assegura contraditório e ampla defesa (art. 268).","D":"É vedada sindicância contra funcionário já exonerado (art. 269, parágrafo único).","E":"O prazo é de 60 dias e há limite de 3 testemunhas."},"fonte":"Lei 10.261/1968, art. 273, I a III; art. 269, parágrafo único","mastigado":"A resposta é a letra A. A sindicância é uma versão mais curta do processo: cada lado leva até três testemunhas e tudo deve terminar em sessenta dias. No processo administrativo, são até cinco testemunhas por lado.","teSitua":{"termos":[{"termo":"sindicância","significado":"procedimento disciplinar mais simples, para faltas punidas com repreensão, suspensão ou multa."},{"termo":"arrolar","significado":"indicar numa lista, para serem ouvidas."},{"termo":"autoridade sindicante","significado":"pessoa encarregada de conduzir a sindicância."}],"exemplo":"Na sindicância contra Ruth por atrasos frequentes, ela indicou três testemunhas, o máximo permitido. A autoridade sindicante também ouviu três. Tudo precisa ser concluído em sessenta dias, quando o relatório segue para decisão."}},{"id":"aut.administrativo_tj.processo_disciplinar.0003","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com a Lei nº 10.261/1968, o processo administrativo deverá ser instaurado por portaria, no prazo improrrogável de 8 dias do recebimento da determinação, e concluído no de","alternativas":{"A":"90 dias da citação do acusado.","B":"60 dias da instauração.","C":"30 dias da citação, prorrogáveis por igual período.","D":"120 dias da publicação da portaria.","E":"180 dias do recebimento da determinação."},"gabarito":"A","explicacao":"O art. 277 fixa: instauração por portaria em 8 dias improrrogáveis do recebimento da determinação e conclusão em 90 dias da citação do acusado. Da portaria devem constar a identificação do acusado, a infração com descrição sucinta dos fatos, as normas infringidas e a penalidade mais elevada em tese cabível (§ 1º).","explicacoes":{"A":"Correta: art. 277, caput.","B":"Sessenta dias é o prazo da sindicância (art. 273, II).","C":"Não é esse o prazo do processo administrativo.","D":"Não há prazo de 120 dias.","E":"Cento e oitenta dias é o limite do afastamento preventivo (art. 266, I)."},"fonte":"Lei 10.261/1968, art. 277, caput e § 1º","mastigado":"A resposta é a letra A. Recebida a ordem de abrir o processo, a portaria deve sair em oito dias, sem prorrogação. A partir da citação do acusado, o processo tem noventa dias para terminar.","teSitua":{"termos":[{"termo":"portaria","significado":"ato escrito da autoridade que abre o processo e descreve a acusação."},{"termo":"improrrogável","significado":"que não pode ser estendido."},{"termo":"citação do acusado","significado":"ato que comunica oficialmente ao servidor a acusação e o chama para se defender."}],"exemplo":"O Secretário determinou a instauração de processo contra Noel em 2 de junho. A portaria saiu em 9 de junho, dentro dos oito dias. Noel foi citado em 20 de junho, e o processo deve terminar em até noventa dias a partir daí."}},{"id":"aut.administrativo_tj.processo_disciplinar.0004","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do Estatuto paulista, a citação do acusado no processo administrativo será feita","alternativas":{"A":"pessoalmente, no mínimo 2 dias antes do interrogatório; não encontrado o acusado, por edital publicado uma vez no Diário Oficial, no mínimo 10 dias antes do interrogatório.","B":"por carta registrada, com 24 horas de antecedência.","C":"por edital publicado três vezes no Diário Oficial, com prazo de 15 dias.","D":"por telefone, mediante certidão do secretário.","E":"pessoalmente, com antecedência mínima de 15 dias, vedada a citação por edital."},"gabarito":"A","explicacao":"O art. 278, § 2º, exige citação pessoal no mínimo 2 dias antes do interrogatório, pelo superior hierárquico ou diretamente. O § 3º prevê citação por edital, publicado uma vez no Diário Oficial, no mínimo 10 dias antes, quando o acusado não é encontrado, se furta à citação ou tem paradeiro ignorado. As regras de 24 horas, carta registrada e três publicações eram da redação antiga.","explicacoes":{"A":"Correta: art. 278, §§ 2º e 3º.","B":"Era a redação antiga, revogada.","C":"Era a redação antiga, revogada; hoje o edital é publicado uma vez, 10 dias antes.","D":"Não há citação por telefone.","E":"A antecedência mínima é de 2 dias, e o edital é admitido."},"fonte":"Lei 10.261/1968, art. 278, §§ 2º e 3º (redação da LC 942/2003)","mastigado":"A resposta é a letra A. O acusado é chamado pessoalmente, pelo menos dois dias antes do interrogatório. Se não for achado ou se esconder, a citação vai para o Diário Oficial, uma vez, com pelo menos dez dias de antecedência.","teSitua":{"termos":[{"termo":"citação","significado":"ato que comunica oficialmente ao acusado a acusação e o chama para o processo."},{"termo":"interrogatório","significado":"momento em que o acusado é ouvido sobre os fatos."},{"termo":"edital","significado":"aviso oficial publicado no Diário Oficial quando a pessoa não é encontrada."}],"exemplo":"O servidor Lúcio mudou de endereço sem avisar e não foi encontrado no trabalho. A citação foi feita por edital, publicado uma vez no Diário Oficial, doze dias antes do interrogatório, cumprindo a antecedência mínima de dez dias."}},{"id":"aut.administrativo_tj.processo_disciplinar.0005","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"certo_errado","dificuldade":2,"enunciado":"No processo administrativo disciplinar do Estatuto paulista, não comparecendo o acusado, será decretada sua revelia por despacho, prosseguindo-se nos demais atos do processo, e ao acusado revel será nomeado advogado dativo.","gabarito":"C","explicacao":"É o que dispõem os arts. 280 e 281, na redação da LC 942/2003. O art. 282, § 3º, também manda nomear advogado dativo quando o acusado não tiver recursos ou se negar a constituir advogado.","fonte":"Lei 10.261/1968, arts. 280 e 281","mastigado":"Certo. Se o acusado não aparece, o processo continua sem ele, e a autoridade nomeia um advogado para defendê-lo. Ninguém fica sem defesa no processo disciplinar.","teSitua":{"termos":[{"termo":"revelia","significado":"situação de quem, chamado ao processo, não comparece nem se defende."},{"termo":"advogado dativo","significado":"advogado nomeado pela autoridade para defender quem não tem defensor."}],"exemplo":"Citado regularmente, Josué não compareceu ao interrogatório. O presidente decretou sua revelia por despacho e nomeou um advogado dativo, que passou a acompanhar todos os atos e apresentar a defesa dele."}},{"id":"aut.administrativo_tj.processo_disciplinar.0006","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":3,"enunciado":"Encerrada a fase probatória do processo administrativo previsto na Lei nº 10.261/1968, a defesa poderá apresentar alegações finais no prazo de","alternativas":{"A":"7 dias; o relatório deverá ser apresentado em 10 dias, contados da apresentação das alegações finais.","B":"10 dias; o relatório deverá ser apresentado em 48 horas.","C":"5 dias; o relatório deverá ser apresentado em 30 dias.","D":"3 dias; o relatório deverá ser apresentado em 20 dias.","E":"15 dias; o relatório deverá ser apresentado em 15 dias."},"gabarito":"A","explicacao":"O art. 292 dá 7 dias para alegações finais; não apresentadas, o presidente designa advogado dativo e fixa novo prazo (parágrafo único). O relatório vem em 10 dias, contados das alegações finais (art. 293). Depois, a autoridade que instaurou o processo julga em 20 dias ou determina diligência (art. 295).","explicacoes":{"A":"Correta: arts. 292 e 293.","B":"Dez dias para defesa era da redação antiga.","C":"Não são esses os prazos vigentes.","D":"Três dias é o prazo para requerer provas após o interrogatório (art. 283).","E":"Não são esses os prazos vigentes."},"fonte":"Lei 10.261/1968, arts. 292, 293 e 295","mastigado":"A resposta é a letra A. Terminada a produção de provas, a defesa tem sete dias para suas alegações finais. Em seguida, quem preside tem dez dias para fazer o relatório, e a autoridade tem vinte dias para julgar.","teSitua":{"termos":[{"termo":"fase probatória","significado":"etapa do processo em que se produzem as provas, como depoimentos e documentos."},{"termo":"alegações finais","significado":"última manifestação da defesa antes do relatório."},{"termo":"relatório","significado":"documento que resume o processo e propõe absolvição ou punição."}],"exemplo":"Ouvidas as testemunhas no processo contra Ilda, abriu-se vista à defesa, que apresentou alegações finais em sete dias. Dez dias depois, o relatório propôs a pena de suspensão, e os autos seguiram para julgamento."}},{"id":"aut.administrativo_tj.processo_disciplinar.0007","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":4,"enunciado":"Instaurado processo exclusivamente para apurar inassiduidade, nos termos da redação vigente do Estatuto,","alternativas":{"A":"a defesa somente poderá versar sobre força maior, coação ilegal ou motivo legalmente justificável que impeça o comparecimento ao trabalho, e o processo se extingue se o acusado pedir exoneração até o interrogatório ou por ocasião dele.","B":"a defesa poderá versar sobre qualquer matéria, e o pedido de exoneração não interfere no processo.","C":"não há direito de defesa, pois a falta é comprovada pelo ponto.","D":"o processo prossegue mesmo que o acusado peça exoneração antes do interrogatório.","E":"a defesa só pode alegar doença, comprovada por atestado particular."},"gabarito":"A","explicacao":"Pelo art. 311, a defesa no processo por inassiduidade só pode versar sobre força maior, coação ilegal ou motivo legalmente justificável que impeça o comparecimento. O art. 310 extingue o processo instaurado exclusivamente para apurar inassiduidade se o indiciado pedir exoneração até a data do interrogatório ou por ocasião dele; e o art. 309 impede a instauração se o funcionário já tiver pedido exoneração.","explicacoes":{"A":"Correta: arts. 310 e 311.","B":"A matéria de defesa é limitada (art. 311), e a exoneração extingue o processo (art. 310).","C":"Há direito de defesa, com matéria limitada.","D":"A exoneração pedida até o interrogatório extingue o processo (art. 310).","E":"A lei fala em força maior, coação ilegal ou motivo legalmente justificável."},"fonte":"Lei 10.261/1968, arts. 309, 310 e 311 (redação da LC 1.361/2021)","mastigado":"A resposta é a letra A. Quem responde por faltar demais só pode se defender dizendo que algo o impediu de ir trabalhar: força maior, coação ou motivo previsto em lei. E, se pedir para sair até o interrogatório, o processo acaba.","teSitua":{"termos":[{"termo":"inassiduidade","significado":"falta habitual ao serviço, sem justificativa, além dos limites da lei."},{"termo":"força maior","significado":"acontecimento inevitável que impede a pessoa de cumprir uma obrigação."},{"termo":"coação ilegal","significado":"pressão ou ameaça indevida que obriga alguém a agir ou deixar de agir."}],"exemplo":"Acusado de inassiduidade, Célio alegou que esteve internado sem conseguir avisar. Essa é uma defesa admitida. Se ele preferisse deixar o cargo, poderia pedir exoneração até o interrogatório, e o processo seria extinto."}},{"id":"aut.administrativo_tj.processo_disciplinar.0008","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, da decisão que aplicar penalidade caberá recurso","alternativas":{"A":"por uma única vez, no prazo de 30 dias, apresentado à autoridade que aplicou a pena, que terá 10 dias para mantê-la ou reformá-la, motivadamente.","B":"por até duas vezes, no prazo de 15 dias, dirigido diretamente ao Governador.","C":"por uma única vez, no prazo de 10 dias, com efeito suspensivo automático.","D":"sem limite de vezes, enquanto houver autoridade superior.","E":"no prazo de 5 dias, apenas se a pena for de demissão."},"gabarito":"A","explicacao":"O art. 312 admite recurso por uma única vez, em 30 dias da publicação ou da intimação pessoal (§ 1º), apresentado à autoridade que aplicou a pena, que tem 10 dias para manter ou reformar motivadamente (§ 3º); mantida ou reformada parcialmente, a decisão segue a reexame do superior (§ 4º). Os recursos não têm efeito suspensivo (art. 314).","explicacoes":{"A":"Correta: art. 312, caput e §§ 1º e 3º.","B":"O recurso é único e apresentado à autoridade que aplicou a pena.","C":"O prazo é de 30 dias, e não há efeito suspensivo (art. 314).","D":"Cabe recurso uma única vez.","E":"Cabe contra qualquer decisão que aplique penalidade, em 30 dias."},"fonte":"Lei 10.261/1968, arts. 312 e 314","mastigado":"A resposta é a letra A. O servidor punido pode recorrer uma vez, em trinta dias. O recurso é entregue a quem aplicou a pena, que pode mudar de ideia em dez dias; se não mudar, o recurso sobe ao superior. Enquanto isso, a pena continua valendo.","teSitua":{"termos":[{"termo":"recurso","significado":"pedido para que a decisão seja revista."},{"termo":"motivadamente","significado":"com explicação das razões da decisão."},{"termo":"efeito suspensivo","significado":"efeito que paralisa a decisão até o julgamento do recurso."}],"exemplo":"Punida com suspensão, Jordana recorreu no 25º dia após a publicação. A autoridade que a puniu manteve a decisão em dez dias e enviou o recurso ao superior. Enquanto isso, a suspensão foi cumprida, porque o recurso não suspende a pena."}},{"id":"aut.administrativo_tj.processo_disciplinar.0009","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com o Estatuto paulista, admite-se, a qualquer tempo, a revisão de punição disciplinar de que não caiba mais recurso, se surgirem fatos ou circunstâncias ainda não apreciados ou vícios insanáveis de procedimento, bastando para tanto a simples alegação de injustiça da decisão.","gabarito":"E","explicacao":"O art. 315 admite a revisão a qualquer tempo nessas hipóteses, mas o § 1º diz que a simples alegação de injustiça da decisão não constitui fundamento do pedido. O ônus da prova cabe ao requerente (§ 4º) e a pena não pode ser agravada pela revisão (art. 316).","fonte":"Lei 10.261/1968, art. 315, caput e § 1º; art. 316","mastigado":"Errado. A revisão pode ser pedida a qualquer tempo, mas precisa de fato novo ou de um erro grave no procedimento. Dizer apenas que a decisão foi injusta não basta. E a revisão nunca pode piorar a pena.","teSitua":{"termos":[{"termo":"revisão","significado":"novo exame de punição já definitiva, para reduzi-la ou anulá-la."},{"termo":"vícios insanáveis","significado":"defeitos graves no procedimento que não podem ser corrigidos."},{"termo":"alegação de injustiça","significado":"afirmação de que a decisão foi injusta, sem trazer fato novo."}],"exemplo":"Anos após ser suspenso, Valmir descobriu um documento que prova que estava em outra cidade no dia da falta. Com esse fato novo, ele pode pedir revisão. Se apenas reclamasse que a pena foi injusta, o pedido seria indeferido."}},{"id":"aut.administrativo_tj.processo_disciplinar.0010","subtopico":"administrativo_tj.estatuto_sp.processo_disciplinar","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos do art. 323 da Lei nº 10.261/1968, os prazos previstos no Estatuto serão todos contados por dias corridos, não se computando no prazo o dia inicial e prorrogando-se o vencimento que incidir em sábado, domingo, feriado ou facultativo para o primeiro dia útil seguinte.","gabarito":"C","explicacao":"É a regra do art. 323 e de seu parágrafo único, aplicável a todos os prazos do Estatuto, inclusive os do procedimento disciplinar.","fonte":"Lei 10.261/1968, art. 323 e parágrafo único","mastigado":"Certo. No Estatuto paulista, os prazos contam todos os dias, inclusive fins de semana. O primeiro dia não entra na conta, e, se o último cair num dia sem expediente, o prazo passa para o próximo dia útil.","teSitua":{"termos":[{"termo":"dias corridos","significado":"contagem que inclui todos os dias, úteis ou não."},{"termo":"facultativo","significado":"dia de ponto facultativo, em que o expediente é dispensado."},{"termo":"primeiro dia útil seguinte","significado":"próximo dia com expediente normal."}],"exemplo":"Rosa foi intimada numa segunda-feira para apresentar alegações em sete dias. A contagem começa na terça e termina na segunda seguinte. Se esse último dia fosse feriado, o prazo terminaria na terça-feira."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0001","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei Estadual nº 10.261/1968, são formas de provimento dos cargos públicos, entre outras,","alternativas":{"A":"a nomeação, a transferência e a readmissão.","B":"a nomeação, a promoção e a remoção.","C":"a transferência, a remoção e a readaptação.","D":"a reversão, a promoção e a substituição.","E":"o aproveitamento, a remoção e a substituição."},"gabarito":"A","explicacao":"O art. 11 lista sete formas de provimento: nomeação, transferência, reintegração, acesso, reversão, aproveitamento e readmissão. Promoção, remoção, readaptação e substituição não constam dessa lista.","explicacoes":{"A":"Correta: nomeação, transferência e readmissão estão no art. 11, I, II e VII.","B":"Promoção e remoção não são formas de provimento no art. 11.","C":"Remoção e readaptação não constam do art. 11; a readaptação se faz mediante transferência (art. 42).","D":"Promoção e substituição não estão no rol do art. 11.","E":"Remoção e substituição não estão no rol do art. 11."},"fonte":"Lei 10.261/1968, art. 11, I a VII","mastigado":"A resposta é a letra A. A lei dá uma lista fechada de sete jeitos de ocupar um cargo: nomeação, transferência, reintegração, acesso, reversão, aproveitamento e readmissão. Promoção, remoção e substituição ficam de fora, e é aí que a banca tenta confundir.","teSitua":{"termos":[{"termo":"provimento","significado":"ato que preenche um cargo público vago, colocando nele uma pessoa."},{"termo":"readmissão","significado":"volta ao serviço de quem foi demitido ou exonerado, sem receber pelo tempo em que ficou fora."},{"termo":"readaptação","significado":"mudança do servidor para cargo mais compatível com sua capacidade física ou mental, após exame médico."}],"exemplo":"Ana passou no concurso de escrevente e foi nomeada: isso é provimento por nomeação. Já seu colega Paulo apenas mudou de cartório dentro da mesma comarca; isso é remoção, que não preenche cargo novo e não está na lista das formas de provimento."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0002","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto dos Funcionários Públicos Civis do Estado de São Paulo, funcionário público, para os fins do Estatuto, é a pessoa legalmente investida em cargo público.","gabarito":"C","explicacao":"É a definição literal do art. 3º da Lei 10.261/1968. O art. 4º completa: cargo público é o conjunto de atribuições e responsabilidades cometidas a um funcionário.","fonte":"Lei 10.261/1968, art. 3º","mastigado":"Certo. Para o Estatuto paulista, é funcionário público quem foi colocado num cargo público de forma legal. Não basta trabalhar para o Estado: é preciso ocupar um cargo de verdade, com posse regular.","teSitua":{"termos":[{"termo":"legalmente investida","significado":"colocada no cargo seguindo todas as regras da lei, como concurso, nomeação e posse."},{"termo":"cargo público","significado":"conjunto de tarefas e responsabilidades criado por lei e ocupado por um funcionário."}],"exemplo":"Carla foi aprovada em concurso, nomeada e tomou posse no cargo de escrevente do TJSP. A partir daí ela é funcionária pública para o Estatuto. Já o estagiário Bruno, que ajuda no cartório, não ocupa cargo público e não se enquadra nessa definição."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0003","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com a Lei nº 10.261/1968, o conjunto de cargos da mesma denominação recebe o nome de","alternativas":{"A":"classe.","B":"carreira.","C":"quadro.","D":"padrão.","E":"lotação."},"gabarito":"A","explicacao":"Classe é o conjunto de cargos da mesma denominação (art. 7º). Carreira é o conjunto de classes da mesma natureza de trabalho, escalonadas por complexidade e responsabilidade (art. 8º); quadro é o conjunto de carreiras e de cargos isolados (art. 9º); padrão é o conjunto de referência e grau (art. 6º, parágrafo único); lotação é o número de funcionários que devem ter exercício em cada repartição (art. 58).","explicacoes":{"A":"Correta: art. 7º.","B":"Carreira reúne classes da mesma natureza de trabalho (art. 8º).","C":"Quadro é o conjunto de carreiras e de cargos isolados (art. 9º).","D":"Padrão é o conjunto de referência e grau do cargo (art. 6º, parágrafo único).","E":"Lotação é o número de funcionários de cada repartição (art. 58)."},"fonte":"Lei 10.261/1968, art. 7º","mastigado":"A resposta é a letra A. Pense numa escada: cargos com o mesmo nome formam uma classe; classes do mesmo tipo de trabalho formam uma carreira; e todas as carreiras mais os cargos isolados formam o quadro.","teSitua":{"termos":[{"termo":"denominação","significado":"nome oficial dado ao cargo, como escrevente técnico judiciário."},{"termo":"quadro","significado":"conjunto de todas as carreiras e cargos isolados de um órgão."},{"termo":"padrão","significado":"valor do cargo, formado pela referência numérica e pelo grau."},{"termo":"lotação","significado":"quantidade de funcionários que deve trabalhar em cada repartição."}],"exemplo":"No tribunal de Jonas há cem cargos chamados escrevente técnico judiciário. Juntos, esses cem cargos com o mesmo nome formam uma classe. Se houver outras classes do mesmo tipo de trabalho, mais complexas, todas juntas formam a carreira."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0004","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Conforme o Estatuto dos Funcionários Públicos Civis de SP, carreira é o conjunto de cargos de denominações diferentes reunidos em um mesmo órgão, independentemente da natureza do trabalho.","gabarito":"E","explicacao":"Carreira é o conjunto de classes da mesma natureza de trabalho, escalonadas segundo o nível de complexidade e o grau de responsabilidade (art. 8º). A afirmativa descreve algo próximo de quadro (art. 9º) e ignora a exigência de mesma natureza de trabalho.","fonte":"Lei 10.261/1968, art. 8º","mastigado":"Errado. Carreira reúne classes do mesmo tipo de trabalho, organizadas como degraus, do mais simples ao mais complexo. A natureza do trabalho é justamente o que une a carreira, e a afirmativa diz o contrário.","teSitua":{"termos":[{"termo":"carreira","significado":"conjunto de classes do mesmo tipo de trabalho, organizadas em degraus de complexidade e responsabilidade."},{"termo":"natureza do trabalho","significado":"tipo de atividade que o cargo exerce, como tarefas jurídicas, administrativas ou técnicas."}],"exemplo":"Lúcia entrou como escrevente. Na mesma carreira há degraus com tarefas cada vez mais complexas, todos ligados ao mesmo tipo de serviço cartorário. Um cargo de motorista, por ter trabalho de outra natureza, não faz parte da carreira dela."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0005","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":2,"enunciado":"Um chefe de cartório determina que um escrevente passe a executar, de forma permanente, tarefas próprias de outro cargo, sem relação com as atribuições do seu. À luz da Lei nº 10.261/1968, essa determinação","alternativas":{"A":"é vedada, ressalvadas apenas as funções de chefia e direção e as comissões legais.","B":"é permitida, desde que o funcionário concorde por escrito.","C":"é permitida por até 2 (dois) anos, vedada a prorrogação.","D":"é vedada em qualquer hipótese, inclusive para funções de chefia.","E":"é permitida sempre que houver necessidade de serviço."},"gabarito":"A","explicacao":"O art. 10 proíbe atribuir ao funcionário serviços diversos dos inerentes ao seu cargo, exceto as funções de chefia e direção e as comissões legais. Concordância do servidor ou necessidade de serviço não afastam a vedação.","explicacoes":{"A":"Correta: é a regra e a exceção do art. 10.","B":"A concordância do funcionário não está prevista como exceção.","C":"Não há prazo que autorize o desvio; o prazo de 2 anos aparece no art. 12, para outro assunto.","D":"A lei ressalva expressamente chefia, direção e comissões legais.","E":"Necessidade de serviço não é exceção prevista no art. 10."},"fonte":"Lei 10.261/1968, art. 10","mastigado":"A resposta é a letra A. Cada um faz o serviço do próprio cargo; o chefe não pode desviar o funcionário para tarefas de outro cargo. As únicas exceções são assumir chefia ou direção e participar de comissões previstas em lei.","teSitua":{"termos":[{"termo":"atribuições","significado":"tarefas e poderes próprios de um cargo, definidos por lei."},{"termo":"comissões legais","significado":"grupos de trabalho previstos em lei, como uma comissão de concurso."}],"exemplo":"Roberto é escrevente, mas o chefe quer que ele passe a dirigir o carro oficial todos os dias. Isso é proibido, porque foge do cargo dele. Porém, se Roberto for designado para integrar uma comissão prevista em lei, a designação é válida."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0006","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Pela Lei nº 10.261/1968, as nomeações serão feitas em caráter vitalício, em comissão ou em caráter efetivo, conforme a natureza do cargo.","gabarito":"C","explicacao":"O art. 13 prevê as três formas: vitalício, nos casos previstos na Constituição; em comissão, quando a lei assim determinar; e efetivo, para cargo de provimento dessa natureza.","fonte":"Lei 10.261/1968, art. 13, I a III","mastigado":"Certo. A lei prevê três jeitos de nomear: vitalício (só nos casos que a Constituição manda, como juízes), em comissão (cargos de confiança definidos em lei) e efetivo (cargos de concurso, como o de escrevente).","teSitua":{"termos":[{"termo":"caráter vitalício","significado":"forma de nomeação em que o cargo só se perde por sentença judicial, prevista na Constituição para certas carreiras."},{"termo":"em comissão","significado":"nomeação para cargo de confiança, de livre escolha e livre exoneração pela autoridade."},{"termo":"caráter efetivo","significado":"nomeação para cargo ocupado por concursado, com possibilidade de estabilidade."}],"exemplo":"No mesmo fórum, a juíza Helena tem cargo vitalício, o assessor Marcos foi nomeado em comissão pelo desembargador, e a escrevente Joana, aprovada em concurso, foi nomeada em caráter efetivo. São as três formas de nomeação do Estatuto."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0007","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos da Lei nº 10.261/1968, a nomeação para cargo público de provimento efetivo será precedida de concurso público, no qual","alternativas":{"A":"as provas serão avaliadas de 0 a 100 pontos e aos títulos serão atribuídos, no máximo, 50 pontos.","B":"as provas e os títulos serão avaliados, cada um, de 0 a 100 pontos.","C":"as provas serão avaliadas de 0 a 10 pontos e os títulos, no máximo, 5 pontos.","D":"os títulos valerão sempre mais que as provas.","E":"as provas serão avaliadas de 0 a 100 pontos e os títulos, no máximo, 100 pontos."},"gabarito":"A","explicacao":"O art. 14 exige concurso de provas ou de provas e títulos, e seu parágrafo único fixa a escala: provas de 0 a 100 pontos; títulos com no máximo 50 pontos.","explicacoes":{"A":"Correta: art. 14, parágrafo único.","B":"Os títulos têm teto de 50, não de 100 pontos.","C":"A escala das provas é de 0 a 100.","D":"A lei não dá aos títulos peso maior; ao contrário, limita-os a 50 pontos.","E":"O teto dos títulos é 50 pontos."},"fonte":"Lei 10.261/1968, art. 14, parágrafo único","mastigado":"A resposta é a letra A. Nas provas, a nota vai de zero a cem. Os títulos (diplomas, cursos) ajudam, mas valem no máximo cinquenta pontos. Assim o título nunca pesa mais que a prova.","teSitua":{"termos":[{"termo":"provimento efetivo","significado":"forma de ocupar cargo permanente, destinado a concursados."},{"termo":"títulos","significado":"comprovantes de formação ou experiência, como diplomas de pós-graduação, que somam pontos no concurso."}],"exemplo":"No concurso de Pedro, ele tirou 80 pontos nas provas e tinha um mestrado. Pela regra do Estatuto, os títulos dele poderiam somar no máximo 50 pontos, enquanto as provas são medidas numa escala de zero a cem."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0008","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Segundo o Estatuto dos Funcionários Públicos Civis de SP, cabe às instruções especiais do concurso determinar, em função da natureza do cargo, entre outros pontos, o prazo de validade do concurso.","gabarito":"C","explicacao":"O art. 18 enumera o que as instruções especiais determinam: se o concurso será de provas ou de provas e títulos; as condições de provimento; o tipo e o conteúdo das provas; a forma de julgamento; os critérios de habilitação e classificação; e, no inciso VI, o prazo de validade do concurso.","fonte":"Lei 10.261/1968, art. 18, VI","mastigado":"Certo. As regras de cada concurso ficam nas instruções especiais (o que chamamos hoje de edital). Entre elas está por quanto tempo o concurso vale para chamar aprovados.","teSitua":{"termos":[{"termo":"instruções especiais","significado":"normas próprias de cada concurso, expedidas pelo órgão competente, semelhantes ao edital."},{"termo":"prazo de validade","significado":"período em que os aprovados podem ser chamados para nomeação."}],"exemplo":"O edital do concurso de escrevente que Fernanda prestou diz que ele vale por dois anos, prorrogável. Essa definição está nas instruções especiais do concurso, como manda o Estatuto paulista."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0009","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":2,"enunciado":"Conforme a Lei nº 10.261/1968, a nomeação para cargo efetivo obedecerá","alternativas":{"A":"à ordem de classificação no concurso.","B":"à ordem de inscrição no concurso.","C":"ao critério de conveniência da autoridade, entre os aprovados.","D":"à antiguidade no serviço público dos aprovados.","E":"à ordem de entrega dos documentos para posse."},"gabarito":"A","explicacao":"O art. 20 determina que a nomeação obedecerá à ordem de classificação no concurso. Não há escolha livre entre aprovados nem critério de inscrição ou antiguidade.","explicacoes":{"A":"Correta: art. 20.","B":"A ordem de inscrição não interfere na nomeação.","C":"Não há escolha discricionária entre aprovados.","D":"Antiguidade no serviço público não é critério de nomeação.","E":"A entrega de documentos é fase posterior, ligada à posse."},"fonte":"Lei 10.261/1968, art. 20","mastigado":"A resposta é a letra A. Quem ficou mais bem colocado é chamado primeiro. A autoridade não pode pular candidatos nem escolher por preferência, por tempo de serviço ou por ordem de inscrição.","teSitua":{"termos":[{"termo":"ordem de classificação","significado":"posição de cada aprovado na lista final do concurso, da maior para a menor nota."}],"exemplo":"Rafael ficou em 3º lugar e Bianca em 10º no concurso de escrevente. Abertas duas vagas, são nomeados o 1º e o 2º colocados. Bianca não pode ser chamada antes de Rafael, porque a nomeação segue a classificação."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0010","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":3,"enunciado":"De acordo com a Lei nº 10.261/1968, a realização dos concursos será descentralizada, cabendo a cada repartição organizar o seu próprio certame.","gabarito":"E","explicacao":"O art. 15 determina o contrário: a realização dos concursos será centralizada num só órgão. O art. 19 apenas permite que as instruções especiais prevejam execução e classificação por regiões.","fonte":"Lei 10.261/1968, art. 15","mastigado":"Errado. A lei manda concentrar a realização dos concursos num único órgão. O que pode haver é a divisão das vagas e da classificação por regiões, se as regras do concurso assim previrem.","teSitua":{"termos":[{"termo":"centralizada","significado":"reunida num único órgão responsável por toda a organização."},{"termo":"certame","significado":"concurso; disputa organizada entre candidatos."}],"exemplo":"Em vez de cada fórum fazer seu próprio concurso, o Estado concentra a organização num único órgão. Assim, Mariana, que mora em Bauru, e Tiago, de Santos, fazem o mesmo concurso, ainda que disputem vagas de regiões diferentes."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0011","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Nos termos do Estatuto, as instruções especiais poderão determinar que a execução do concurso, bem como a classificação dos habilitados, seja feita por regiões.","gabarito":"C","explicacao":"É o que prevê literalmente o art. 19 da Lei 10.261/1968. Concursos regionalizados, como os de escrevente do TJSP por circunscrição, encontram base nesse dispositivo.","fonte":"Lei 10.261/1968, art. 19","mastigado":"Certo. As regras do concurso podem dividir a prova e a lista de aprovados por região. É por isso que existem concursos em que o candidato disputa vagas apenas de uma determinada região do Estado.","teSitua":{"termos":[{"termo":"instruções especiais","significado":"normas próprias de cada concurso, semelhantes ao edital."},{"termo":"habilitados","significado":"candidatos aprovados que atingiram a nota mínima exigida."}],"exemplo":"No concurso de Gustavo, as vagas foram separadas por região do Estado. Ele se inscreveu para a região de Campinas e concorre apenas com quem escolheu essa mesma região, com lista de classificação própria."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0012","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":3,"enunciado":"Segundo a Lei nº 10.261/1968, as provas de habilitação, realizadas pelo órgão encarregado dos concursos, destinam-se","alternativas":{"A":"à transferência e a outras formas de provimento que não impliquem critério competitivo.","B":"exclusivamente à nomeação para cargos em comissão.","C":"à promoção por merecimento.","D":"à remoção a pedido entre repartições.","E":"à posse de candidatos aprovados em concurso."},"gabarito":"A","explicacao":"O art. 21 diz que as provas de habilitação servem para fins de transferência e de outras formas de provimento que não impliquem critério competitivo. O art. 22 manda o regulamento fixar suas normas gerais, aplicando, no que couber, as regras dos concursos.","explicacoes":{"A":"Correta: art. 21.","B":"Cargo em comissão é de livre nomeação e não depende de prova de habilitação.","C":"A promoção tem regras próprias (art. 87 e seguintes), fora deste ponto.","D":"A remoção não é forma de provimento e não exige prova de habilitação.","E":"A posse depende dos requisitos do art. 47, não de prova de habilitação."},"fonte":"Lei 10.261/1968, art. 21","mastigado":"A resposta é a letra A. A prova de habilitação não é uma disputa de notas; ela só confere se o servidor está apto. Por isso é usada na transferência e em outras formas de provimento sem competição entre candidatos.","teSitua":{"termos":[{"termo":"provas de habilitação","significado":"exames que verificam se o servidor tem aptidão para o cargo, sem disputa por classificação."},{"termo":"critério competitivo","significado":"forma de seleção em que os candidatos disputam entre si e são ordenados por nota."},{"termo":"transferência","significado":"passagem do funcionário de um cargo efetivo para outro."}],"exemplo":"Sílvia é funcionária estadual e pediu transferência para outro cargo efetivo. Como não há disputa com outros candidatos, ela faz uma prova de habilitação apenas para mostrar que tem aptidão para as novas funções."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0013","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Conforme o Estatuto dos Funcionários Públicos Civis de SP, haverá substituição no impedimento legal e temporário do ocupante de qualquer cargo público, seja ele de chefia ou não.","gabarito":"E","explicacao":"O art. 23 restringe a substituição ao impedimento legal e temporário do ocupante de cargo de chefia ou de direção. Não há previsão genérica para qualquer cargo.","fonte":"Lei 10.261/1968, art. 23, caput","mastigado":"Errado. A substituição prevista no Estatuto só existe para cargos de chefia ou de direção, quando o titular está temporariamente impedido. Um cargo comum sem chefia não tem substituto automático por essa regra.","teSitua":{"termos":[{"termo":"impedimento legal e temporário","significado":"afastamento previsto em lei e por tempo limitado, como férias ou licença."},{"termo":"chefia ou de direção","significado":"cargos de comando de uma unidade, como chefe de seção ou diretor."}],"exemplo":"A diretora do cartório, Dona Regina, sai de férias por trinta dias. Como o cargo dela é de direção, um funcionário é designado para substituí-la nesse período. Se fosse um escrevente sem chefia de férias, não haveria substituição nos termos do Estatuto."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0014","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":3,"enunciado":"Vago o cargo de chefia ocupado por um diretor que se aposentou, o funcionário que o substituía, segundo a Lei nº 10.261/1968,","alternativas":{"A":"passará a responder pelo expediente da unidade até o provimento do cargo.","B":"deverá deixar imediatamente a substituição.","C":"será automaticamente nomeado para o cargo vago.","D":"permanecerá na substituição pelo prazo máximo de 30 dias.","E":"dependerá de concurso interno para continuar respondendo pela unidade."},"gabarito":"A","explicacao":"O parágrafo único do art. 23 diz que, ocorrendo a vacância, o substituto passará a responder pelo expediente da unidade ou órgão correspondente até o provimento do cargo. Não há nomeação automática nem prazo de 30 dias.","explicacoes":{"A":"Correta: art. 23, parágrafo único.","B":"A lei manda o substituto continuar, não sair.","C":"Responder pelo expediente não equivale a ser nomeado para o cargo.","D":"Não há esse limite de 30 dias; vale até o provimento.","E":"Não há concurso interno previsto para isso."},"fonte":"Lei 10.261/1968, art. 23, parágrafo único","mastigado":"A resposta é a letra A. Quando o cargo de chefia fica vago de vez, quem já substituía continua tocando a unidade até alguém ser oficialmente colocado no cargo. Ele não vira dono do cargo, apenas segura o serviço.","teSitua":{"termos":[{"termo":"responder pelo expediente","significado":"cuidar do funcionamento diário da unidade, assinando e decidindo o necessário."},{"termo":"provimento","significado":"ato que preenche o cargo vago com um novo ocupante."}],"exemplo":"O diretor Antônio se aposentou. Luíza, que já o substituía nas férias, continua respondendo pela unidade até que outro diretor seja designado. Ela não se torna diretora automaticamente."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0015","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":3,"enunciado":"Sobre a substituição prevista na Lei nº 10.261/1968, é correto afirmar que","alternativas":{"A":"recairá sempre em funcionário público e, quando não for automática, dependerá de ato da autoridade competente.","B":"poderá recair em pessoa estranha ao serviço público, se houver urgência.","C":"dependerá sempre de ato do Governador.","D":"não gera qualquer direito à remuneração do cargo do substituído.","E":"só pode durar até 60 dias, qualquer que seja o impedimento."},"gabarito":"A","explicacao":"O art. 24 determina que a substituição recairá sempre em funcionário público e, quando não for automática, dependerá da expedição de ato de autoridade competente. O substituto exerce o cargo enquanto durar o impedimento (§ 1º) e recebe o padrão e as vantagens do cargo substituído (§ 2º).","explicacoes":{"A":"Correta: art. 24, caput.","B":"A substituição recai sempre em funcionário público.","C":"Basta ato da autoridade competente, não necessariamente do Governador.","D":"O § 2º garante o padrão e as vantagens do cargo do substituído.","E":"A substituição dura enquanto durar o impedimento (§ 1º)."},"fonte":"Lei 10.261/1968, art. 24, caput e § 1º","mastigado":"A resposta é a letra A. Só um funcionário público pode substituir outro. Se a substituição não estiver prevista para acontecer sozinha, a autoridade precisa editar um ato designando o substituto.","teSitua":{"termos":[{"termo":"automática","significado":"que acontece sozinha, por previsão já existente, sem precisar de novo ato."},{"termo":"autoridade competente","significado":"pessoa que tem poder legal para praticar aquele ato."}],"exemplo":"A chefe de seção Márcia ficou doente. Como não havia substituto previamente definido, o diretor publicou portaria designando o funcionário Caio para substituí-la. Um advogado de fora não poderia ser designado, porque a substituição recai sempre em funcionário público."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0016","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Durante todo o tempo em que exercer a substituição, o substituto terá direito a perceber o valor do padrão e as vantagens pecuniárias inerentes ao cargo do substituído e mais as vantagens pessoais a que fizer jus.","gabarito":"C","explicacao":"É a regra do art. 24, § 2º. O § 3º acrescenta que, durante a substituição, ele perde o vencimento e as vantagens do próprio cargo, se não optar por ele.","fonte":"Lei 10.261/1968, art. 24, § 2º","mastigado":"Certo. Quem substitui ganha o salário do cargo de chefia que está ocupando, mais as vantagens pessoais que já tinha, como adicionais por tempo de serviço. É justo: faz o trabalho do chefe e recebe como chefe.","teSitua":{"termos":[{"termo":"padrão","significado":"valor do cargo, formado pela referência e pelo grau."},{"termo":"vantagens pecuniárias","significado":"valores em dinheiro pagos além do vencimento, como gratificações."},{"termo":"vantagens pessoais","significado":"valores ligados à pessoa do servidor, como adicional por tempo de serviço."}],"exemplo":"Henrique substitui a diretora do cartório por dois meses. Nesse período, recebe o valor do cargo de diretora e as gratificações dele, somados ao seu adicional por tempo de serviço, que é uma vantagem pessoal dele."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0017","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":3,"enunciado":"Um funcionário designado para substituir um diretor, durante o tempo da substituição, nos termos do Estatuto paulista,","alternativas":{"A":"perderá o vencimento e as vantagens do seu próprio cargo, se por ele não optar.","B":"acumulará o vencimento do seu cargo com o do cargo do substituído.","C":"receberá apenas a diferença entre os dois vencimentos, sem opção.","D":"não poderá optar pelo vencimento do seu cargo.","E":"receberá metade do vencimento do substituído."},"gabarito":"A","explicacao":"Pelo art. 24, § 3º, o substituto perderá, durante a substituição, o vencimento ou a remuneração e demais vantagens pecuniárias do seu cargo, se pelo mesmo não optar. Não há acumulação dos dois vencimentos.","explicacoes":{"A":"Correta: art. 24, § 3º.","B":"A lei não permite somar os dois vencimentos.","C":"A lei não fala em diferença; fala em perda do próprio vencimento, salvo opção.","D":"A opção pelo vencimento do próprio cargo é expressamente permitida.","E":"Não há pagamento de metade do vencimento."},"fonte":"Lei 10.261/1968, art. 24, § 3º","mastigado":"A resposta é a letra A. O substituto não ganha dois salários. Ele passa a receber o do cargo que substitui e deixa de receber o seu, a não ser que prefira ficar com o próprio, se for mais vantajoso.","teSitua":{"termos":[{"termo":"substituição","significado":"exercício temporário de cargo de chefia por outro funcionário, durante o impedimento do titular."},{"termo":"optar","significado":"escolher entre duas possibilidades de remuneração."}],"exemplo":"Joaquim ganha mais no seu cargo do que ganharia como substituto do diretor. Ao assumir a substituição, ele pode optar por continuar recebendo o seu próprio vencimento, mas não pode somar os dois."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0018","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos termos da Lei nº 10.261/1968, os tesoureiros, caixas e outros funcionários que tenham valores sob sua guarda, em caso de impedimento, serão substituídos por funcionários de sua confiança que indicarem, respondendo a sua fiança pela gestão do substituto.","gabarito":"C","explicacao":"É a regra excepcional do art. 25, justificada pela necessidade de serviço. Feita a indicação por escrito ao chefe, este propõe o ato de designação, aplicando-se ao substituto os §§ 1º e 2º do art. 24 (parágrafo único).","fonte":"Lei 10.261/1968, art. 25","mastigado":"Certo. Quem cuida de dinheiro público pode indicar alguém de sua confiança para substituí-lo quando se afastar. Em troca, a garantia que ele prestou continua respondendo pelo que o substituto fizer.","teSitua":{"termos":[{"termo":"tesoureiros, caixas","significado":"funcionários que guardam e movimentam dinheiro ou valores da repartição."},{"termo":"fiança","significado":"garantia prestada por quem guarda valores, que cobre eventuais prejuízos."},{"termo":"gestão","significado":"administração dos valores durante o período de substituição."}],"exemplo":"O tesoureiro Wilson vai sair de licença. Ele indica por escrito a colega Teresa, de sua confiança, para substituí-lo. Se Teresa causar algum desfalque, a fiança de Wilson responde pela gestão dela."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0019","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"multipla","dificuldade":2,"enunciado":"Conforme a Lei nº 10.261/1968, as suas disposições, exceto no que colidirem com a legislação especial, aplicam-se aos funcionários","alternativas":{"A":"dos 3 Poderes do Estado e aos do Tribunal de Contas do Estado.","B":"apenas do Poder Executivo estadual.","C":"dos 3 Poderes do Estado e aos empregados das autarquias.","D":"apenas dos Poderes Executivo e Legislativo.","E":"estaduais e municipais do Estado de São Paulo."},"gabarito":"A","explicacao":"O parágrafo único do art. 1º estende o Estatuto aos funcionários dos 3 Poderes do Estado e aos do Tribunal de Contas, ressalvada a legislação especial. O art. 2º exclui os empregados das autarquias, entidades paraestatais e serviços industriais.","explicacoes":{"A":"Correta: art. 1º, parágrafo único.","B":"O Estatuto não se limita ao Executivo.","C":"Os empregados das autarquias estão excluídos pelo art. 2º.","D":"O Judiciário também está incluído.","E":"O Estatuto é estadual; não alcança os servidores municipais."},"fonte":"Lei 10.261/1968, art. 1º, parágrafo único","mastigado":"A resposta é a letra A. O Estatuto vale para os funcionários do Executivo, do Legislativo e do Judiciário paulistas, além do Tribunal de Contas, salvo quando lei especial disser algo diferente. Por isso ele cai na prova do TJSP.","teSitua":{"termos":[{"termo":"colidirem","significado":"entrarem em conflito com outra norma, contrariando o que ela diz."},{"termo":"legislação especial","significado":"lei própria de uma categoria, que prevalece sobre a regra geral naquilo que trata."},{"termo":"autarquias","significado":"entidades públicas criadas por lei para atividades típicas do Estado, com autonomia administrativa."}],"exemplo":"Juliana é escrevente do TJSP, que integra o Poder Judiciário estadual. O Estatuto dos Funcionários Públicos se aplica a ela, salvo nos pontos em que a lei própria dos servidores do Tribunal disponha de forma diferente."}},{"id":"aut.administrativo_tj.provimento_nomeacao.0020","subtopico":"administrativo_tj.estatuto_sp.provimento_nomeacao","tipo":"certo_errado","dificuldade":2,"enunciado":"De acordo com o Estatuto dos Funcionários Públicos Civis de SP, os cargos públicos são isolados ou de carreira, e o conjunto de referência e grau constitui o padrão do cargo.","gabarito":"C","explicacao":"O art. 5º classifica os cargos em isolados ou de carreira. O art. 6º atribui aos cargos valores por referências numéricas seguidas de letras indicadoras de graus, e seu parágrafo único diz que o conjunto de referência e grau constitui o padrão.","fonte":"Lei 10.261/1968, arts. 5º e 6º, parágrafo único","mastigado":"Certo. Um cargo pode ser isolado (sem degraus para subir) ou fazer parte de uma carreira. O valor do cargo é dado por um número (referência) e uma letra (grau), e os dois juntos formam o padrão.","teSitua":{"termos":[{"termo":"isolados","significado":"cargos que não fazem parte de uma carreira com degraus de ascensão."},{"termo":"referência","significado":"número que indica o nível de valor atribuído ao cargo."},{"termo":"grau","significado":"letra que acompanha a referência e indica a posição dentro dela."}],"exemplo":"No holerite de Diego aparece a referência 10, grau C. Esse conjunto é o padrão do cargo dele. Como o cargo de Diego integra uma carreira, ele pode avançar de grau ao longo do tempo, o que não ocorreria num cargo isolado."}}]`);export{e as default};